local config = {
  ui_story_5038_50380001_1_dialog_content = "Masuk.",
  ui_story_5038_50380001_2_dialog_content = "Oke!",
  ui_story_5038_50380001_3_dialog_content = "Fiuh, tolong beri tahu saya bahwa saya tidak terlambat ?!",
  ui_story_5038_50380001_4_dialog_content = "Ada apa dengan terengah-engah, Tweety? Anda terburu-buru?",
  ui_story_5038_50380001_5_dialog_content = "Saya baru saja mengirimkan surat, tetapi penerima tidak dapat memahami saya, dan kami memutuskan untuk menandatanganinya.",
  ui_story_5038_50380001_6_dialog_content = "Bagaimana ini bisa terjadi? Saya selalu mempermainkan Universese saya!",
  ui_story_5038_50380001_7_dialog_content = "Ha ha! Baik, selamat jalan. Pasti sulit bekerja di tempat asing?",
  ui_story_5038_50380001_8_dialog_content = "Ini bukan masalah! Tidak ada hal kecil yang akan menghentikan saya!",
  ui_story_5038_50380001_9_dialog_content = "Apakah saya menjaga Anda dari hal-hal penting, Nawoxel?",
  ui_story_5038_50380001_10_dialog_content = "Tidak tidak. Tidak semuanya. Aku tidak terburu-buru hari ini.",
  ui_story_5038_50380001_11_dialog_content = "Sebaliknya, waktu Anda lebih berharga...",
  ui_story_5038_50380001_12_dialog_content = "Baik? Maksud kamu apa?",
  ui_story_5038_50380001_13_dialog_content = "Bundel pos baru telah tiba! Berikut daftarnya. Lihatlah.",
  ui_story_5038_50380001_14_dialog_content = "<size=50>Hah?! 30 item?!!</size>",
  ui_story_5038_50380001_15_dialog_content = "Itu hanya yang mendesak. Anda akan menemukan 50 lainnya yang normal di belakang.",
  ui_story_5038_50380001_16_dialog_content = "Belum selesai?",
  ui_story_5038_50380001_17_dialog_content = "B-Kenapa tiba-tiba ada begitu banyak?",
  ui_story_5038_50380001_18_dialog_content = "Saya masih memiliki beberapa wiv saya yang saya belum dewiver...",
  ui_story_5038_50380001_19_dialog_content = "Ada waktu puncak untuk mengirim surat, dan saat ini adalah waktu yang sangat sibuk.",
  ui_story_5038_50380001_20_dialog_content = "Juga, sepertinya ada sesuatu yang terjadi di Umbraton...",
  ui_story_5038_50380001_21_dialog_content = "Lihat alamat pengirimannya, Tweety.",
  ui_story_5038_50380001_22_dialog_content = "Baiklah, mari kita lihat...",
  ui_story_5038_50380001_23_dialog_content = "Oh! Ini semua dari Umbraton ke... <color=#FFB400>Twin Pavilions Bay?</color>",
  ui_story_5038_50380001_24_dialog_content = "Itu benar. Pengiriman barang mendesak dari Umbraton ke tempat-tempat di seluruh Twin Pavilions Bay.",
  ui_story_5038_50380001_25_dialog_content = "Semuanya ditandai sebagai sangat penting. Saya khawatir Anda mungkin cukup sibuk dalam beberapa hari mendatang.",
  ui_story_5038_50380001_26_dialog_content = "Wow! Tempat seperti apa Twin Pavivions Bay itu? Dimana itu? Saya belum pernah ke sana sebelumnya!",
  ui_story_5038_50380001_27_dialog_content = "Dalam hal ini, silakan gunakan kesempatan ini untuk menjelajah.",
  ui_story_5038_50380001_28_dialog_content = "Ini adalah waktu yang tepat untuk mengunjungi Twin Pavilions Bay.",
  ui_story_5038_50380001_29_dialog_content = "Baiklah! Maka saya harus menjadi lemah untuk... Dapatkan... PERGI!",
  ui_story_5038_50380001_30_dialog_content = "<color=#e8d9bb>5 Hari Kemudian</color>",
  ui_story_5038_50380001_31_dialog_content = "<size=50>Wahhhhhhhh—</size>",
  ui_story_5038_50380001_32_dialog_content = "<size=50>PlayerName! B-Bantu aku!</size>",
  ui_story_5038_50380001_33_dialog_content = "Hah? Tweety? Apa yang salah?!",
  ui_story_5038_50380001_34_dialog_content = "Apa yang terjadi?",
  ui_story_5038_50380001_35_dialog_content = "Saya tidak bisa menyelesaikan pengiriman semua pengiriman ini!",
  ui_story_5038_50380001_36_dialog_content = "Ambil napas dalam-dalam dan tenang. Beritahu kami pelan-pelan.",
  ui_story_5038_50380001_37_dialog_content = "Jadi, Anda tahu, baru-baru ini Umbwaton menyewa Courier Union untuk membantu banyak dewi <color=#FFB400>kertas merah</color>.",
  ui_story_5038_50380001_38_dialog_content = "Karena ini pesanan besar, dan sangat mendesak, saya bekerja lembur untuk mengirimkan semuanya...",
  ui_story_5038_50380001_39_dialog_content = "Tapi justru karena ini, aku sudah mencapai batasku...",
  ui_story_5038_50380001_40_dialog_content = "Saya telah bekerja sangat keras selama lima hari penuh! Tapi aku hanya menyelesaikan sedikit, dan...",
  ui_story_5038_50380001_41_dialog_content = "hanya ada satu hari tersisa sampai periode sibuk DUA!",
  ui_story_5038_50380001_42_dialog_content = "Apakah ada sanksi tegas untuk pengiriman terlambat?",
  ui_story_5038_50380001_43_dialog_content = "Saya akan menunda semua orang, dan Serikat Kurir akan... akan... menjebak saya!",
  ui_story_5038_50380001_44_dialog_content = "Dan saya tidak akan punya uang, lalu tidak ada makanan, lalu tidak ada rumah...",
  ui_story_5038_50380001_45_dialog_content = "maka saya harus kembali memotong kayu di Cloud Mwountain!",
  ui_story_5038_50380001_46_dialog_content = "Sedrastis itu?!",
  ui_story_5038_50380001_47_dialog_content = "Jadi... Tweety mau minta bantuannya, mas!",
  ui_story_5038_50380001_48_dialog_content = "Bisakah saya mempekerjakan Sowoz untuk men-twansport saya?",
  ui_story_5038_50380001_49_dialog_content = "Saya akan membayar! Ketika saya mendapatkan salawy bulan ini, saya akan memberikan semuanya untuk Anda!",
  ui_story_5038_50380001_50_dialog_content = "Anda tidak perlu khawatir tentang pembayaran. Saya akan dengan senang hati membantu Anda.",
  ui_story_5038_50380001_51_dialog_content = "Karena waktu tampaknya sangat penting, sebaiknya kita pergi sekarang!",
  ui_story_5038_50380001_52_dialog_content = "Kemana tujuanmu?",
  ui_story_5038_50380001_53_dialog_content = "Sebuah kota pelabuhan bernama Twin Pavilions Bay.",
  ui_story_5038_50380001_54_dialog_content = "Soroz kebetulan berada tepat di atas Cekungan Sungai Emas sekarang.",
  ui_story_5038_50380001_55_dialog_content = "Jika kita mengikuti sungai ke hilir sampai kita melihat lautan, di situlah Twin Pavilions Bay berada.",
  ui_story_5038_50380001_56_dialog_content = "Anda pernah ke sana?!",
  ui_story_5038_50380001_57_dialog_content = "Tidak, tidak secara pribadi. Saya baru saja membacanya di perpustakaan Lumopolis.",
  ui_story_5038_50380001_58_dialog_content = "Itu terletak di sepanjang muara Sungai Emas dan memiliki budaya uniknya sendiri. Ini sering dikutip dalam berbagai buku.",
  ui_story_5038_50380001_59_dialog_content = "Juga, Anda mungkin akrab dengan asal-usulnya.",
  ui_story_5038_50380001_60_dialog_content = "Kok bisa?",
  ui_story_5038_50380001_61_dialog_content = "<color=#FFB400>Serikat Lin</color> mendirikan kota.",
  ui_story_5038_50380001_62_dialog_content = "Persekutuan Lin?! Bukankah mereka di Umbraton?",
  ui_story_5038_50380001_63_dialog_content = "Umbraton adalah tempat mereka menjalankan bisnis, tetapi Twin Pavilions Bay adalah tempat yang mereka sebut rumah.",
  ui_story_5038_50380001_64_dialog_content = "Jangan lupa, Guild Lin berasal dari benua lain jauh di timur.",
  ui_story_5038_50380001_65_dialog_content = "Sebelum mereka muncul, muara Sungai Emas hanya menampung beberapa desa nelayan kecil yang miskin.",
  ui_story_5038_50380001_66_dialog_content = "Suatu hari, sebuah kapal besar tiba di pantainya dan membawa beberapa Lin Guild ke Astra.",
  ui_story_5038_50380001_67_dialog_content = "Mereka menurunkan banyak barang dari timur jauh, yang kemudian mereka angkut di sepanjang Sungai Emas ke Umbraton.",
  ui_story_5038_50380001_68_dialog_content = "Mereka harus mempekerjakan pekerja, dan membutuhkan tempat untuk menginap dan makan. Seiring waktu, penduduk desa setempat secara bertahap menemukan pekerjaan baru.",
  ui_story_5038_50380001_69_dialog_content = "Pelabuhan makmur dengan uang yang dihasilkan Lin Guild.",
  ui_story_5038_50380001_70_dialog_content = "Penduduk setempat menyambut baik pengaruh budaya timur, dan membangun kota dengan gaya Longzhou.",
  ui_story_5038_50380001_71_dialog_content = "Sejak saat itu, Persekutuan Lin menetap dan hidup berdampingan dengan penduduk setempat secara harmonis hingga hari ini.",
  ui_story_5038_50380001_72_dialog_content = "Jadi itulah Twin Pavilions Bay, tujuan kami.",
  ui_story_5038_50380001_73_dialog_content = "Wow, kota yang dibangun oleh para pedagang! Aku belum pernah melihat tempat seperti itu sebelumnya.",
  ui_story_5038_50380001_74_dialog_content = "A-Apakah akan sangat mahal di sana? Tabungan kami tidak banyak.",
  ui_story_5038_50380001_75_dialog_content = "Saya mendengar bahwa di tempat-tempat yang makmur, Anda harus membayar untuk parkir kendaraan dan barang-barang lainnya. Bisakah Anda bayangkan berapa biaya untuk memarkir sesuatu seperti Soroz?",
  ui_story_5038_50380001_76_dialog_content = "Yah, saya tidak akan khawatir tentang biaya parkir, tetapi untuk menghindari masalah yang tidak perlu...",
  ui_story_5038_50380001_77_dialog_content = "Saya akan merekomendasikan mendaratkan Soroz di suatu tempat di luar kota, PlayerName.",
  ui_story_5038_50380001_78_dialog_content = "Ada benarnya.",
  ui_story_5038_50380001_79_dialog_content = "Lihat! Saya pikir kita hampir sampai!",
  ui_story_5038_50380001_80_dialog_content = "Wah... Bahkan jalanannya indah!",
  ui_story_5038_50380001_81_dialog_content = "Ya! Ada warna merah di mana-mana, sangat cantik!",
  ui_story_5038_50380001_82_dialog_content = "Sepertinya tempat yang sangat bahagia dan hidup.",
  ui_story_5038_50380001_83_dialog_content = "Ya. Menurut buku, seluruh kota bergaya benua yang sama sekali berbeda.",
  ui_story_5038_50380001_84_dialog_content = "Di suatu tempat di seberang lautan, beginilah tampilan rumah dan jalan mereka.",
  ui_story_5038_50380001_85_dialog_content = "Seolah-olah benua di sisi lain adalah dunia yang sama sekali berbeda.",
  ui_story_5038_50380001_86_dialog_content = "Dan, dan, saya yakin mereka juga memiliki liburan yang sangat berbeda!",
  ui_story_5038_50380001_87_dialog_content = "Semua kertas merah yang saya kirim hari ini pasti untuk festival kedua.",
  ui_story_5038_50380001_88_dialog_content = "Disebut apa lagi...?",
  ui_story_5038_50380001_89_dialog_content = "Selamat Tahun Baru! Apakah Anda di sini untuk Festival Musim Semi?",
  ui_story_5038_50380001_90_dialog_content = "Oh ya! Ini disebut Festival Spwing!",
  ui_story_5038_50380001_91_dialog_content = "Kami tidak mendapatkan banyak wajah asing di sekitar Twin Pavilions Bay akhir-akhir ini. Apakah Anda dari luar kota?",
  ui_story_5038_50380001_92_dialog_content = "Aku bisa tahu hanya dengan melihat pakaianmu.",
  ui_story_5038_50380001_93_dialog_content = "Waktu yang tepat, Pak! Ini kertas merah yang dipesan toko Anda. Tolong, tandatangani di sini!",
  ui_story_5038_50380001_94_dialog_content = "Oh terima kasih. Dan di sanalah saya, khawatir itu tidak akan tiba tepat waktu!",
  ui_story_5038_50380001_95_dialog_content = "Maaf mau bertanya, tapi saya bertanya-tanya mengapa Anda memesan begitu banyak kertas merah dari Umbraton?",
  ui_story_5038_50380001_96_dialog_content = "Mereka penting untuk menyambut tahun baru.",
  ui_story_5038_50380001_97_dialog_content = "Sudah menjadi tradisi di Longzhou untuk menggantungkan dua lembar kertas merah dengan tulisan \"Berkah\" di pintu mereka untuk Festival Musim Semi.",
  ui_story_5038_50380001_98_dialog_content = "Mereka membantu kami berdoa untuk keberuntungan dan kemakmuran di tahun depan.",
  ui_story_5038_50380001_99_dialog_content = "Longzhou—apakah itu nama benua timur?",
  ui_story_5038_50380001_100_dialog_content = "Tepat. Sepertinya kalian tidak terlalu akrab dengan kami.",
  ui_story_5038_50380001_101_dialog_content = "Kami yang tinggal di sini di Twin Pavilions Bay semuanya cukup mandiri, dan jarang berinteraksi dengan tempat-tempat yang jauh di pedalaman.",
  ui_story_5038_50380001_102_dialog_content = "Kami dapat, dan akan, dengan mudah membeli kertas merah ini di toko lokal kami sendiri.",
  ui_story_5038_50380001_103_dialog_content = "Tapi tahun ini... ada sedikit situasi.",
  ui_story_5038_50380001_104_dialog_content = "Situasi seperti apa?",
  ui_story_5038_50380001_105_dialog_content = "Toko kami semua kehabisan stok. Bukan hanya kertas, tapi semuanya, termasuk kebutuhan.",
  ui_story_5038_50380001_106_dialog_content = "Kenapa... Kau bahkan kehabisan cadangan?",
  ui_story_5038_50380001_107_dialog_content = "Biasanya, Guild Lin <color=#FFB400>kapal suplai</color> datang sekali setiap beberapa bulan dari Longzhou.",
  ui_story_5038_50380001_108_dialog_content = "Tapi kami belum melihat jejaknya selama setengah tahun terakhir. Kami tidak tahu apa yang terjadi.",
  ui_story_5038_50380001_109_dialog_content = "Toko-toko yang mengandalkan kapal pemasok untuk membeli inventaris tidak dapat bertahan selamanya.",
  ui_story_5038_50380001_110_dialog_content = "Kertas merah adalah bagian dari apa yang hilang. Jadi kami tidak punya pilihan selain memesan beberapa dari Umbraton.",
  ui_story_5038_50380001_111_dialog_content = "(Ah, jadi itu yang terjadi. Kedengarannya mengkhawatirkan...)",
  ui_story_5038_50380001_112_dialog_content = "(Persekutuan Lin bahkan pernah membantuku sebelumnya, tapi aku tidak tahu bagaimana keadaan mereka.)",
  ui_story_5038_50380001_113_dialog_content = "Oh... aku tahu rasanya. Anda pasti sangat merindukan cita rasa rumah, Pak.",
  ui_story_5038_50380001_114_dialog_content = "<color=#e8d9bb>Klakson... Klakson...</color>",
  ui_story_5038_50380001_115_dialog_content = "Tempat apa itu?",
  ui_story_5038_50380001_116_dialog_content = "Kedengarannya seperti klakson yang datang dari pelabuhan ...",
  ui_story_5038_50380001_117_dialog_content = "Itu... klakson kapal!",
  ui_story_5038_50380001_118_dialog_content = "Tentu saja! Saya tahu foghorn di mana saja!",
  ui_story_5038_50380001_119_dialog_content = "Ada kapal di pelabuhan! Mungkinkah itu Lin Guild?",
  ui_story_5038_50380001_120_dialog_content = "Apakah itu kapal pemasok Lin Guild?",
  ui_story_5038_50380001_121_dialog_content = "Sepertinya kami datang di saat yang tepat.",
  ui_story_5038_50380001_122_dialog_content = "Ini kapal pasokan, sungguh!",
  ui_story_5038_50380001_123_dialog_content = "Oh, syukurlah! Saya khawatir saya tidak akan bisa mendapatkan apa pun untuk Festival Musim Semi!",
  ui_story_5038_50380001_124_dialog_content = "Seseorang datang!",
  ui_story_5038_50380001_125_dialog_content = "...",
  ui_story_5038_50380001_126_dialog_content = "(Ada seorang pria aneh di sana, yang tampaknya sama sekali tidak bersemangat.)",
  ui_story_5038_50380001_127_dialog_content = "Keluar dari jalan! Biarkan dia lewat! Beri ruang untuk pria tua, lemah, sakit, cacat!",
  ui_story_5038_50380001_128_dialog_content = "Anda, anak muda! Anda memblokir roda!",
  ui_story_5038_50380001_129_dialog_content = "B-Benda yang dia duduki itu... kursi roda?!",
  ui_story_5038_50380001_130_dialog_content = "aku minta maaf! Di mana sopan santun saya?",
  ui_story_5038_50380001_131_dialog_content = "Tidak repot. Saya sudah mengatakan berkali-kali, Liqing, Nak, jangan memberi label pada saya semua itu ...",
  ui_story_5038_50380001_132_dialog_content = "Aku belum mati, otakku berfungsi dengan baik.",
  ui_story_5038_50380001_133_dialog_content = "Ha ha ha ha! Aku hanya ingin membuat kita melewati kerumunan lebih cepat!",
  ui_story_5038_50380001_134_dialog_content = "Saya telah menunggu selamanya untuk membeli ramuan obat yang luar biasa dari Longzhou!",
  ui_story_5038_50380001_135_dialog_content = "Biarkan lewat! aku duluan! Saya membawa Nightium!",
  ui_story_5038_50380001_136_dialog_content = "Naik! Lanjutkan!",
  ui_story_5038_50380001_137_dialog_content = "Hah? Jangan mendorong!",
  ui_story_5038_50380001_138_dialog_content = "Diam, semuanya.",
  ui_story_5038_50380001_139_dialog_content = "...",
  ui_story_5038_50380001_140_dialog_content = "Shadowind benar-benar mengalami perubahan. Bahkan sang kapten adalah wajah baru.",
  ui_story_5038_50380001_141_dialog_content = "Saya Yuebai, kapten baru kapal dagang Lin Guild, Shadowind.",
  ui_story_5038_50380001_142_dialog_content = "... Sepertinya kalian semua mengenali anggota Lin yang biasanya bepergian dengan kapal ini.",
  ui_story_5038_50380001_143_dialog_content = "Setengah tahun terakhir melihat beberapa perubahan strategis dalam keluarga Lin, yang mengakibatkan mereka tidak dapat mengirim kapal ke laut.",
  ui_story_5038_50380001_144_dialog_content = "Saya yakin memutuskan rute antara Longzhou dan Astra untuk waktu yang lama sangat sulit.",
  ui_story_5038_50380001_145_dialog_content = "Tapi itu sekarang semua di masa lalu. Sekarang Shadowind memiliki saya di pucuk pimpinannya,",
  ui_story_5038_50380001_146_dialog_content = "rute Longzhou-Astra akan secara resmi <color=#FFB400>melanjutkan bisnis</color>.",
  ui_story_5038_50380001_147_dialog_content = "... Mereka benar-benar melakukannya, Zhong Xu! Mereka benar-benar datang!",
  ui_story_5038_50380001_148_dialog_content = "Kita bisa kembali sekarang!",
  ui_story_5038_50380001_149_dialog_content = "...",
  ui_story_5038_50380001_150_dialog_content = "Kita bisa kembali ke Longzhou? Seperti itu? Tapi aku belum menyiapkan...",
  ui_story_5038_50380001_151_dialog_content = "Ya, saya sudah menjadwalkan pertemuan dengan mitra bisnis saya. Aku ragu aku bisa keluar dari mereka...",
  ui_story_5038_50380001_152_dialog_content = "Siapa pun yang ingin kembali ke Longzhou hanya perlu membeli tiket.",
  ui_story_5038_50380001_153_dialog_content = "Namun, karena rute kembali telah berubah, harap perhatikan hal-hal tertentu yang terkait <color=#FFB400>risiko</color>.",
  ui_story_5038_50380001_154_dialog_content = "Sudahlah! Setiap kapal Lin dapat diandalkan! Tolong, tiga tiket untuk saya!",
  ui_story_5038_50380001_155_dialog_content = "Beri aku satu dulu! Tidak mau harus memperebutkan mereka...",
  ui_story_5038_50380001_156_dialog_content = "Tolong, semuanya, tenang. Tidak perlu panik.",
  ui_story_5038_50380001_157_dialog_content = "Masih ada waktu sebelum perjalanan pulang kami.",
  ui_story_5038_50380001_158_dialog_content = "Saya tahu semua orang di sini adalah orang baik sejak saya turun.",
  ui_story_5038_50380001_159_dialog_content = "Mungkinkah ada pria atau wanita yang ingin diriku yang rendah hati membaca keberuntungan mereka, mungkin sedikit menerangi jalan mereka?",
  ui_story_5038_50380001_160_dialog_content = "Dan Tianxian si scammer menyerang lagi, menipu orang dengan lidah peraknya...",
  ui_story_5038_50380001_161_dialog_content = "Kenapa, Putri Dantang! Seseorang bukanlah pembohong, saya jamin.",
  ui_story_5038_50380001_162_dialog_content = "... Hati-hati, Putri!",
  ui_story_5038_50380001_163_dialog_content = "Oooooooh!",
  ui_story_5038_50380001_164_dialog_content = "Wow! Shadowind terlihat lebih baik dari sebelumnya!",
  ui_story_5038_50380001_165_dialog_content = "Jauh lebih luas juga..",
  ui_story_5038_50380001_166_dialog_content = "Hehehe... Refleks yang sangat cepat, Jiu.",
  ui_story_5038_50380001_167_dialog_content = "<color=#e8d9bb>*Kerumunan bergumam*</color>",
  ui_story_5038_50380001_168_dialog_content = "Huh...",
  ui_story_5038_50380001_169_dialog_content = "Anda baik-baik saja, Tweety?",
  ui_story_5038_50380001_170_dialog_content = "Aku ingin melihat-lihat Shadowind juga...",
  ui_story_5038_50380001_171_dialog_content = "Saya yakin ada banyak hal keren untuk dilihat.",
  ui_story_5038_50380001_172_dialog_content = "Maksudmu seperti ini, kurir kecil?",
  ui_story_5038_50380001_173_dialog_content = "WOW!! Tumpukan besar kertas cowor merah!",
  ui_story_5038_50380001_174_dialog_content = "Itu berat! Itulah yang saya cari!",
  ui_story_5038_50380001_175_dialog_content = "Aku pernah mendengar Twin Pavilions Bay kehabisan persediaan bahkan sebelum kami pergi, dengan Festival Musim Semi yang semakin dekat, tidak kurang.",
  ui_story_5038_50380001_176_dialog_content = "Mereka tidak punya pilihan selain mencari persediaan dari guild pedalaman dan kemudian mengatur sekelompok kurir untuk mengirimkan semuanya.",
  ui_story_5038_50380001_177_dialog_content = "Namun, sekarang kertas dari Longzhou ada di sini, hal-hal tidak akan merepotkan Anda.",
  ui_story_5038_50380001_178_dialog_content = "<size=50>HAY! Aku baik-baik saja sekarang!!</size>",
  ui_story_5038_50380001_179_dialog_content = "Tweety akhirnya mati.",
  ui_story_5038_50380001_180_dialog_content = "Apakah kalian bertiga dari pedalaman Astra?",
  ui_story_5038_50380001_181_dialog_content = "Anda bisa tahu hanya dengan melihat pakaian kami, bukan?",
  ui_story_5038_50380001_182_dialog_content = "Saya menantikan keramahan Anda, kalau begitu.",
  ui_story_5038_50380001_183_dialog_content = "Shadowind akan tetap berada di perairan Astra untuk sementara waktu.",
  ui_story_5038_50380001_184_dialog_content = "Mari kita saling mengenal selama ini.",
  ui_story_5038_50380001_185_dialog_content = "(Wow! Sungguh wanita yang tabah dan mengesankan!)",
  ui_story_5038_50380001_186_dialog_content = "S-Tentu. aku PlayerName.",
  ui_story_5038_50380001_187_dialog_content = "Selamat datang di Astra, tamu dari Longzhou!",
  ui_story_5038_50380101_1_dialog_content = "<color=#e8d9bb>Jalan Twin Pavilions Bay</color>",
  ui_story_5038_50380101_2_dialog_content = "(Waktu kita di sini seperti liburan yang panjang dan langka...)",
  ui_story_5038_50380101_3_dialog_content = "(Twin Pavilions Bay adalah tempat yang santai selama Festival Musim Semi.)",
  ui_story_5038_50380101_4_dialog_content = "Apa yang dipikirkan, PlayerName?",
  ui_story_5038_50380101_5_dialog_content = "Aku hanya memikirkan betapa cepatnya waktu berlalu. Aku bahkan tidak tahu sudah berapa lama kita berada di sini.",
  ui_story_5038_50380101_6_dialog_content = "Saya bersedia. Saya menyimpan buku harian yang sangat rinci.",
  ui_story_5038_50380101_7_dialog_content = "Izinkan aku melihat... PlayerName dan Tianxian menghabiskan tiga hari pertama mengembara di Jalan Jajanan Spesial Timur...",
  ui_story_5038_50380101_8_dialog_content = "Hari ke empat sampai enam dihabiskan untuk kami mengikuti berbagai permainan catur Twin Pavilions Bay...",
  ui_story_5038_50380101_9_dialog_content = "Hari ketujuh sampai sepuluh, kalah telak dalam kontes kaligrafi Festival Musim Semi Dantang...",
  ui_story_5038_50380101_10_dialog_content = "Hari sepuluh sampai lima belas—",
  ui_story_5038_50380101_11_dialog_content = "Oke, oke... Cukup!",
  ui_story_5038_50380101_12_dialog_content = "Lagi pula, kita mungkin harus mulai merencanakan keberangkatan kita segera.",
  ui_story_5038_50380101_13_dialog_content = "Ambil selama yang Anda inginkan, PlayerName... Tapi aku harus berangkat ke Illumina besok.",
  ui_story_5038_50380101_14_dialog_content = "Apa? Begitu cepat?!",
  ui_story_5038_50380101_15_dialog_content = "Nah, sudah waktunya rantai suplai musim dingin khusus Illumina untuk bangkit dan berjalan.",
  ui_story_5038_50380101_16_dialog_content = "Aku harus pergi membantu dengan distribusi.",
  ui_story_5038_50380101_17_dialog_content = "Dan aku harus pergi ke Northland sesuai tradisi, menghabiskan tahun baru bersama Ratu Bethlehem.",
  ui_story_5038_50380101_18_dialog_content = "Jika tidak ada penundaan, pelatihku dari Northland akan tiba di sini malam ini.",
  ui_story_5038_50380101_19_dialog_content = "Kamu juga, Carleen?",
  ui_story_5038_50380101_20_dialog_content = "Nah, begitu lama, liburan. Itu menyenangkan...",
  ui_story_5038_50380101_21_dialog_content = "Wah!! Lihat siapa yang saya temukan!",
  ui_story_5038_50380101_22_dialog_content = "Selamat pagi, Tuan Navigator, Nona Wakil, Nona Carween!",
  ui_story_5038_50380101_23_dialog_content = "Pagi Tweety!",
  ui_story_5038_50380101_24_dialog_content = "Bagaimana kerjanya? Masih sibuk?",
  ui_story_5038_50380101_25_dialog_content = "Baik-baik saja sekarang! Sudah kembali normal!",
  ui_story_5038_50380101_26_dialog_content = "Hanya ada satu hal yang tersisa untuk dewiver!",
  ui_story_5038_50380101_27_dialog_content = "Apakah Anda masih membutuhkan bantuan? Aku masih punya waktu sebelum aku harus lepas landas.",
  ui_story_5038_50380101_28_dialog_content = "Terima kasih, Nona Vice, tapi aku punya ini! Dan coba tebak?",
  ui_story_5038_50380101_29_dialog_content = "saya membeli sebuah <color=#FFB400>tiket</color> untuk Shadowind!",
  ui_story_5038_50380101_30_dialog_content = "Apakah Anda akan mempercayainya? Ini adalah surat jarak jauh! Itu harus dikirim ke Longzhou!",
  ui_story_5038_50380101_31_dialog_content = "Saya sangat berhati-hati untuk mengantarkan yang lain lebih awal, jadi saya tidak ketinggalan kapal!",
  ui_story_5038_50380101_32_dialog_content = "Sepertinya kesempatan besar untuk bepergian.",
  ui_story_5038_50380101_33_dialog_content = "Hehe! Saya sangat menantikannya!",
  ui_story_5038_50380101_34_dialog_content = "Sepertinya yang bisa dibicarakan semua orang baru-baru ini adalah kepergian Shadowind yang akan segera terjadi.",
  ui_story_5038_50380101_35_dialog_content = "Yup, beberapa orang sedikit cemas.",
  ui_story_5038_50380101_36_dialog_content = "Kau tahu... Aku punya <color=#FFB400>sendok dalam</color> tentang mengapa keluarga Lin harus menangguhkan rute mereka selama enam bulan!",
  ui_story_5038_50380101_37_dialog_content = "Eh... siapa kamu?",
  ui_story_5038_50380101_38_dialog_content = "Oh, saya ingat! Anda adalah pria baik yang membantu orang tua di kursi roda!",
  ui_story_5038_50380101_39_dialog_content = "Ha ha! Aku bukan hanya pria baik! Zhong Xu adalah temanku, sekaligus pasienku.",
  ui_story_5038_50380101_40_dialog_content = "Kami adalah penumpang bersama di kapal yang sama ketika kami datang dari Longzhou.",
  ui_story_5038_50380101_41_dialog_content = "Nama saya Liqing. Saya seorang dokter kucing pengembara, berkeliling dan menyelamatkan nyawa!",
  ui_story_5038_50380101_42_dialog_content = "Meeoong!",
  ui_story_5038_50380101_43_dialog_content = "Wah!",
  ui_story_5038_50380101_44_dialog_content = "I-I-Itu kucing!",
  ui_story_5038_50380101_45_dialog_content = "Ayo, Tinytail, bersikaplah! Maafkan aku, dia hanya bermain.",
  ui_story_5038_50380101_46_dialog_content = "Kemarilah, Tinytail.",
  ui_story_5038_50380101_47_dialog_content = "Jelas, dia lebih memilih perusahaan saya daripada perusahaan Anda.",
  ui_story_5038_50380101_48_dialog_content = "Hanya karena semua kucing lain yang berkeliaran di sekitarmu...",
  ui_story_5038_50380101_49_dialog_content = "Permisi, saya di sini untuk mengkonfirmasi detail penumpang.",
  ui_story_5038_50380101_50_dialog_content = "Bisakah mereka yang hadir—yaitu Tweety, Zhong Xu, dan Liqing—mengonfirmasi pemesanan mereka kembali ke Longzhou?",
  ui_story_5038_50380101_51_dialog_content = "Ya!",
  ui_story_5038_50380101_52_dialog_content = "Sangat bagus. Sebelum kita berangkat, saya punya beberapa pengumuman lagi.",
  ui_story_5038_50380101_53_dialog_content = "Penduduk Longzhou, saya yakin Anda pernah mendengar tentang kompas laut legendaris keluarga Lin.",
  ui_story_5038_50380101_54_dialog_content = "Mereka dulu mengandalkan objek ini untuk mempertahankan supremasi maritim mereka.",
  ui_story_5038_50380101_55_dialog_content = "Sayangnya, harta unik ini hilang, dan sejauh ini belum ditemukan.",
  ui_story_5038_50380101_56_dialog_content = "Saya telah menyebutkan ini sebelumnya, tetapi harap pastikan Anda memahami risiko dari perjalanan kita yang akan datang.",
  ui_story_5038_50380101_57_dialog_content = "Kami tidak benar-benar memiliki pengalaman navigasi tanpa kompas, jadi ini akan menjadi petualangan pelayaran.",
  ui_story_5038_50380101_58_dialog_content = "Kami memiliki kondisi yang menguntungkan dalam perjalanan ke sini, yang membuat perjalanan menjadi aman dan lancar.",
  ui_story_5038_50380101_59_dialog_content = "Namun, saya tidak dapat menjamin bahwa perjalanan pulang akan sama. Saya perlu memastikan bahwa semua penumpang sepenuhnya menyadari hal ini.",
  ui_story_5038_50380101_60_dialog_content = "Secara pribadi, saya akan melakukannya <color=#FFB400>tidak menyarankan</color> menaiki Shadowind tanpa alasan yang jelas.",
  ui_story_5038_50380101_61_dialog_content = "(Apakah ini salah satu insiden yang dihadapi Lin selama setengah tahun terakhir ini...?)",
  ui_story_5038_50380101_62_dialog_content = "Aku tidak takut! Saya percaya pada Nona Yuebai!",
  ui_story_5038_50380101_63_dialog_content = "Anda orang yang berani, bukan?",
  ui_story_5038_50380101_64_dialog_content = "Kebetulan mungkin, tapi karena aku sudah berkeliling memberitahu semua orang tentang ini...",
  ui_story_5038_50380101_65_dialog_content = "Setiap orang yang memiliki tiket segera dibatalkan.",
  ui_story_5038_50380101_66_dialog_content = "Beberapa mengatakan mereka harus tetap tinggal karena alasan keluarga, yang lain karena tiba-tiba ada perubahan rencana.",
  ui_story_5038_50380101_67_dialog_content = "Saya curiga itu karena tidak ada yang benar-benar mau mempertaruhkan hidup mereka, ketika dorongan datang untuk mendorong.",
  ui_story_5038_50380101_68_dialog_content = "Tetapi dalam hal ini, maka Anda juga sedang mempertaruhkan hidup Anda, Nona Yuebai!",
  ui_story_5038_50380101_69_dialog_content = "... Saya memiliki keyakinan pada kemampuan saya untuk menangani berbagai hal. Lagi pula, ini adalah pekerjaanku.",
  ui_story_5038_50380101_70_dialog_content = "Anda tampaknya tidak terlalu percaya diri.",
  ui_story_5038_50380101_71_dialog_content = "Penasaran gak dimana <color=#FFB400>Kompas</color> berakhir?",
  ui_story_5038_50380101_72_dialog_content = "?!?",
  ui_story_5038_50380101_73_dialog_content = "Apakah Anda salah satu dari Lins? Atau...",
  ui_story_5038_50380101_74_dialog_content = "Ini keren, Nyonya Kapten! Kami benar-benar ada selama <color=#FFB400>kejadian</color> enam bulan yang lalu.",
  ui_story_5038_50380101_75_dialog_content = "Mustahil... Sejauh yang kutahu, tidak ada satu jiwa pun yang berhasil lolos dari cengkeraman bajak laut...",
  ui_story_5038_50380101_76_dialog_content = "Jika Anda bahkan tidak tahu, para perompak pasti tidak akan tahu!",
  ui_story_5038_50380101_77_dialog_content = "Lagi pula, saya cukup yakin bukan hanya saya dan Zhong Xu tua di sini yang tidak jatuh ke kedalaman lautan saat itu.",
  ui_story_5038_50380101_78_dialog_content = "Anda adalah Tuan Zhong Xu, saya kira?",
  ui_story_5038_50380101_79_dialog_content = "Ya Bu.",
  ui_story_5038_50380101_80_dialog_content = "Guildmaster sangat memperhatikan keselamatan Anda. Dia akan senang mengetahui Anda masih hidup.",
  ui_story_5038_50380101_81_dialog_content = "Hehe, jadi dia berhasil kabur juga ya?",
  ui_story_5038_50380101_82_dialog_content = "Anda adalah kapten yang sangat berani. Saya mengagumi kegigihan Anda dalam melanjutkan rute.",
  ui_story_5038_50380101_83_dialog_content = "Saya membayangkan Anda tidak hanya di sini dalam perjalanan pengiriman barang dagangan! Tentunya misi Anda adalah mencari Kompas juga?",
  ui_story_5038_50380101_84_dialog_content = "... Benar.",
  ui_story_5038_50380101_85_dialog_content = "Jika Anda masih bertekad untuk ikut, tolong, bantu saya.",
  ui_story_5038_50380101_86_dialog_content = "Tentu saja! Mari kita bicara lebih banyak begitu kita berada di kapal, kita tidak boleh meninggalkan tamu pedalaman kita berdiri di sekitar sini.",
  ui_story_5038_50380101_87_dialog_content = "K-maksudmu kita? Jangan pedulikan kami, sungguh...",
  ui_story_5038_50380101_88_dialog_content = "Lagi pula, kami berangkat dua hari dari sekarang. Saya kira saya akan melihat Anda kemudian, di pelabuhan.",
  ui_story_5038_50380101_89_dialog_content = "<color=#e8d9bb>Dua hari kemudian</color>",
  ui_story_5038_50380101_90_dialog_content = "Wah, kalau bukan PlayerName!",
  ui_story_5038_50380101_91_dialog_content = "Datang untuk melihat kami pergi, kan?",
  ui_story_5038_50380101_92_dialog_content = "Yah, agak. Carleen dan Vice sudah pergi, tapi ingin aku menyampaikan pesan kepada kalian.",
  ui_story_5038_50380101_93_dialog_content = "\"Semoga perjalanan Anda lancar dan aman, dan semoga Anda segera mengunjungi Astra lagi.\"",
  ui_story_5038_50380101_94_dialog_content = "Itu pada dasarnya yang ingin saya katakan juga.",
  ui_story_5038_50380101_95_dialog_content = "Aku tahu kita baru bertemu baru-baru ini, tapi aku masih sedikit sedih karena kita harus berpisah secepat ini.",
  ui_story_5038_50380101_96_dialog_content = "Hehe... Kalian Astra selalu memakai hati di lengan baju.",
  ui_story_5038_50380101_97_dialog_content = "Putri Dantang, apakah Anda ingin mencoba dan mengatakan sesuatu sebagai tanggapan?",
  ui_story_5038_50380101_98_dialog_content = "Er... A-Aku? Eh...",
  ui_story_5038_50380101_99_dialog_content = "Aku akan mengingatmu sayang juga, PlayerName.",
  ui_story_5038_50380101_100_dialog_content = "Zhong Xu dan Tianxian sudah bergabung. Kita harus pergi juga.",
  ui_story_5038_50380101_101_dialog_content = "Oh! Itu mengingatkanku... Dimana burung putih kecil tempo hari?",
  ui_story_5038_50380101_102_dialog_content = "... Benar? Saya juga ingin mengucapkan selamat tinggal pada Tweety.",
  ui_story_5038_50380101_103_dialog_content = "<size=50>Wahhhhhhhh—</size>",
  ui_story_5038_50380101_104_dialog_content = "<size=50>PlayerName! B-Bantu aku!</size>",
  ui_story_5038_50380101_105_dialog_content = "Ah! Itu dia, Tweety!",
  ui_story_5038_50380101_106_dialog_content = "Saya tidak bisa menyelesaikan pengiriman semua posting saya!",
  ui_story_5038_50380101_107_dialog_content = "Saya tiba-tiba menerima pengiriman mendesak di Northland! Couwier Union tidak dapat mengirim orang lain!",
  ui_story_5038_50380101_108_dialog_content = "Mengering di bagian itu, dan jarak pandang sangat rendah. Saya satu-satunya yang cukup akrab dengan area ini!",
  ui_story_5038_50380101_109_dialog_content = "Jadi ... Apakah Anda mengatakan Anda ...",
  ui_story_5038_50380101_110_dialog_content = "Sooo... Saya datang untuk menanyakan apakah Anda mau membantu saya lagi, PlayerName?",
  ui_story_5038_50380101_111_dialog_content = "Kupikir aku bisa mempekerjakanmu untuk pergi ke Wongzhou untukku!",
  ui_story_5038_50380101_112_dialog_content = "Saya bisa membayar! Tunggu sampai saya mendapatkan salawy bulan depan! Aku akan memberikan semuanya untukmu!",
  ui_story_5038_50380101_113_dialog_content = "(Ini terdengar familiar...)",
  ui_story_5038_50380101_114_dialog_content = "Aku ingin sekali membantumu, sungguh, dan uang tidak penting!",
  ui_story_5038_50380101_115_dialog_content = "Tapi masalahnya, apakah tiket Anda dapat dialihkan?",
  ui_story_5038_50380101_116_dialog_content = "Ada apa?",
  ui_story_5038_50380101_117_dialog_content = "Nona Yuebai!!",
  ui_story_5038_50380101_118_dialog_content = "Oh... Mmhmm... Aku mengerti.",
  ui_story_5038_50380101_119_dialog_content = "Biasanya, tiket tidak dapat dikembalikan dan tidak dapat dialihkan.",
  ui_story_5038_50380101_120_dialog_content = "Oh... baiklah...",
  ui_story_5038_50380101_121_dialog_content = "Aku akan pergi meminta salah satu penumpang di kapal untuk membantu sebagai gantinya...",
  ui_story_5038_50380101_122_dialog_content = "Namun, sebagai kapten, saya akan dengan senang hati mengundang Anda naik, PlayerName.",
  ui_story_5038_50380101_123_dialog_content = "Hah?! Itu bagus, tapi tiba-tiba, kejutan ...",
  ui_story_5038_50380101_124_dialog_content = "Anda harus berterima kasih kepada Zhong Xu untuk ini.",
  ui_story_5038_50380101_125_dialog_content = "Saya baru memutuskan untuk mencari The Compass lagi, sejak perbincangan kami beberapa hari lalu.",
  ui_story_5038_50380101_126_dialog_content = "Zhong Xu mengatakan bahwa hal-hal mungkin menjadi sedikit lebih lancar dengan bantuan Caelestite.",
  ui_story_5038_50380101_127_dialog_content = "(Lebih halus...? Apakah kemampuan psikisku seharusnya bisa merasakan objek seperti itu?)",
  ui_story_5038_50380101_128_dialog_content = "Setidaknya kita bisa memanfaatkan pengalaman kita datang ke sini untuk perjalanan pulang.",
  ui_story_5038_50380101_129_dialog_content = "Kami juga memiliki Zhong Xu dan Liqing bersama kami, yang keduanya ada di sana saat The Compass hilang.",
  ui_story_5038_50380101_130_dialog_content = "Putri Dantang, Jiu, dan Tianxian akan melakukan apa saja untuk menjaga kapal tetap aman.",
  ui_story_5038_50380101_131_dialog_content = "Jika Anda memercayai saya untuk menavigasi, saya menghargai bantuan Anda.",
  ui_story_5038_50380101_132_dialog_content = "(Saya telah beberapa kali bertemu dengan Lin Guild di masa lalu, dan bahkan berteman dengan beberapa dari mereka...)",
  ui_story_5038_50380101_133_dialog_content = "(Jadi kali ini jika saya bisa membantu mereka...)",
  ui_story_5038_50380101_134_option_content = "Biar kulakukan!",
  ui_story_5038_50380101_135_dialog_content = "Terima kasih telah bersedia, PlayerName. Aku akan menunggumu di kapal.",
  ui_story_5038_50380101_136_dialog_content = "Te-Terima kasih, Tuan Navigator!",
  ui_story_5038_50380101_137_dialog_content = "Apa yang kamu tunggu? Ayo naik!",
  ui_story_5038_50380101_138_dialog_content = "A-baiklah! Saya datang!",
  ui_story_5038_50380101_139_dialog_content = "Meeeow!",
  ui_story_5038_50380101_140_dialog_content = "Ooh! Tinytail melihat ikan!",
  ui_story_5038_50380101_141_dialog_content = "Tidak, Tinytail. Tidak melompat!",
  ui_story_5038_50380101_142_dialog_content = "Meong...",
  ui_story_5038_50380101_143_dialog_content = "Angin Astra tampaknya jauh lebih kuat daripada angin Longzhou...",
  ui_story_5038_50380101_144_dialog_content = "Sempurna untuk berlayar.",
  ui_story_5038_50380101_145_dialog_content = "Itu sudah menangkap layar Shadowind. Tampaknya dari ... barat daya.",
  ui_story_5038_50380101_146_dialog_content = "Aku akan membersihkan geladak. Silakan duduk dengan tenang, semuanya!",
  ui_story_5038_50380101_147_dialog_content = "Shadowind, berlayarlah!",
  ui_story_5038_50380201_1_dialog_content = "(Sungguh kapal yang luar biasa! Ini lebih besar dari yang pernah saya naiki.)",
  ui_story_5038_50380201_2_dialog_content = "(Bahkan desain geladak kaya akan karakter timur jauh.)",
  ui_story_5038_50380201_3_dialog_content = "(Pemandangannya juga luar biasa...)",
  ui_story_5038_50380201_4_dialog_content = "(Ahhh! Langit biru, ombak bergulung, angin laut...)",
  ui_story_5038_50380201_5_dialog_content = "Hah?",
  ui_story_5038_50380201_6_dialog_content = "Zhong Xu, mengapa kamu di sini sendirian, menatap laut, melamun?",
  ui_story_5038_50380201_7_dialog_content = "Saya sedang mengamati ombak.",
  ui_story_5038_50380201_8_dialog_content = "Apakah... ada sesuatu untuk dilihat di sana?",
  ui_story_5038_50380201_9_dialog_content = "Gelombang lautan itu sama, kemanapun kamu pergi. Dan dengan demikian, menatap mereka mengingatkan saya pada rumah saya.",
  ui_story_5038_50380201_10_dialog_content = "Anda pasti sangat merindukannya.",
  ui_story_5038_50380201_11_dialog_content = "Oh, itu mengingatkan saya. Sebelum kami pergi, saya mendapat kesan bahwa banyak penduduk Twin Pavilions Bay jangka panjang akan ikut bersama kami.",
  ui_story_5038_50380201_12_dialog_content = "Saya tidak akan pernah berharap itu akan berakhir hanya dengan Anda dan Liqing.",
  ui_story_5038_50380201_13_dialog_content = "Ketika Anda mengembara terlalu lama di negeri asing, Anda sering ingin pulang.",
  ui_story_5038_50380201_14_dialog_content = "Mereka yang mengembalikan tiketnya masih merindukan tanah airnya, tetapi benih-benih kepemilikan telah mengakar bagi mereka di Twin Pavilions Bay.",
  ui_story_5038_50380201_15_dialog_content = "Mereka punya keluarga di Twin Pavilions Bay sekarang, dan teman-teman baru. Kerinduan akan tanah air mereka adalah nostalgia yang lebih melankolis dari apa pun.",
  ui_story_5038_50380201_16_dialog_content = "Hanya orang sepertiku yang bisa datang dan pergi sebebas angin tanpa ada yang mengikat mereka.",
  ui_story_5038_50380201_17_dialog_content = "saya rasa saya mengerti apa yang anda maksud...",
  ui_story_5038_50380201_18_dialog_content = "Heh... sobat muda, saya heran bahwa yang masih muda senang mendengarkan ocehan seorang lelaki tua.",
  ui_story_5038_50380201_19_dialog_content = "Saya senang mengobrol dengan Anda, jadi Anda tidak perlu memperlakukan saya sebagai senior Anda.",
  ui_story_5038_50380201_20_dialog_content = "Aku harap kita bisa menjadi teman. Mari kita singkirkan formalitas, oke?",
  ui_story_5038_50380201_21_dialog_content = "Seperti dengan Liqing, kita setara.",
  ui_story_5038_50380201_22_dialog_content = "Besar! Saya merasa terhormat, dan senang...",
  ui_story_5038_50380201_23_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5038_50380201_24_dialog_content = "Woah!",
  ui_story_5038_50380201_25_dialog_content = "Apa itu tadi?! Aku baru saja basah kuyup!",
  ui_story_5038_50380201_26_dialog_content = "Itu adalah sekolah ikan.",
  ui_story_5038_50380201_27_dialog_content = "Jika Anda melihat satu dengan ekor seperti ular, maka itu a <color=#FFB400>ikan ular</color>!",
  ui_story_5038_50380201_28_dialog_content = "T-Mereka datang entah dari mana... Aku heran air memercik ke wajahku dari bawah sana!",
  ui_story_5038_50380201_29_dialog_content = "Yah, itu karena musim dingin adalah saat mereka paling aktif, karena musim kawin mereka.",
  ui_story_5038_50380201_30_dialog_content = "Mereka berkelompok di sekolah dan berenang di laut dalam segera setelah mereka lahir.",
  ui_story_5038_50380201_31_dialog_content = "Tidak peduli seberapa jauh mereka berenang, pada musim dingin mereka selalu bergabung dengan sekolah terdekat lainnya.",
  ui_story_5038_50380201_32_dialog_content = "Kemudian mereka bermigrasi kembali ke pelabuhan Longzhou, tempat mereka bertelur di perairan dangkal... Dan siklus itu dimulai lagi.",
  ui_story_5038_50380201_33_dialog_content = "Kenapa kamu tahu banyak tentang ikan ini?",
  ui_story_5038_50380201_34_dialog_content = "Hehe! Karena ikan ular adalah spesies suci bagi Lin Guild.",
  ui_story_5038_50380201_35_dialog_content = "Seperti totem?",
  ui_story_5038_50380201_36_dialog_content = "Ya, sesuatu seperti itu. Lins berharap untuk menjadi seperti ikan itu, kembali dengan selamat ke tanah air setelah setiap pelayaran.",
  ui_story_5038_50380201_37_dialog_content = "Guru Bu berkata, kecambah dengan potensi bisa dibudidayakan. Cerdik PlayerName!",
  ui_story_5038_50380201_38_dialog_content = "Jangan terlalu menggurui seperti Anda orang dewasa di sini!",
  ui_story_5038_50380201_39_dialog_content = "Jangan menilai buku dari sampulnya, PlayerName. Siapa tahu, saya bisa menjadi yang lebih tua di sini.",
  ui_story_5038_50380201_40_dialog_content = "Jadi lebih baik kamu memanggilku dengan hormat karena seniorku, hehe.",
  ui_story_5038_50380201_41_dialog_content = "Hm? *Mengendus mengendus* Aku mencium bau ikan!",
  ui_story_5038_50380201_42_dialog_content = "Mungkin karena ini jam makan siang.",
  ui_story_5038_50380201_43_dialog_content = "Ini hari pertama kita di laut, jadi kita perlu sedikit dorongan semangat.",
  ui_story_5038_50380201_44_dialog_content = "Ayo coba beberapa, PlayerName. Ini adalah <color=#FFB400>ikan tupai</color>, spesialisasi Longzhou.",
  ui_story_5038_50380201_45_dialog_content = "Kami membuang tulang ikan yang baru ditangkap, lalu mencetak dagingnya dengan cara menyilang. Kemudian digoreng hingga garing dan berwarna keemasan, sebelum akhirnya diberi saus asam manis...",
  ui_story_5038_50380201_46_dialog_content = "Tunggu! A-Ikan apa yang kamu buat dengan itu?!",
  ui_story_5038_50380201_47_dialog_content = "Seekor ikan ular. Rasanya cukup enak dan empuk.",
  ui_story_5038_50380201_48_dialog_content = "Apa?!!",
  ui_story_5038_50380201_49_dialog_content = "Haha, mengerti! Saya bercanda, itu hanya ikan komersial biasa dari palka.",
  ui_story_5038_50380201_50_dialog_content = "Ikutlah denganku ke area penumpang. Yang lain sudah ada di sana.",
  ui_story_5038_50380201_51_dialog_content = "<color=#e8d9bb>Kabin Penumpang Shadowind</color>",
  ui_story_5038_50380201_52_dialog_content = "Wow! Kamu sangat berbakat, Putri Dantang. Ikan ini dimasak dengan sempurna, dan rasanya seperti di rumah sendiri!",
  ui_story_5038_50380201_53_dialog_content = "Pujian penipu hampir tidak layak diterima.",
  ui_story_5038_50380201_54_dialog_content = "Ngomong-ngomong, Jiu menyiapkan semua hidangan ini.",
  ui_story_5038_50380201_55_dialog_content = "Nona banyak membantu.",
  ui_story_5038_50380201_56_dialog_content = "Saya ragu Anda bisa menemukan hubungan majikan-karyawan lain di semua Ji yang sama terhormatnya dengan keduanya!",
  ui_story_5038_50380201_57_dialog_content = "...",
  ui_story_5038_50380201_58_dialog_content = "Oh, maafkan aku, tapi kurasa Putri lebih baik tidak membicarakan tempat itu.",
  ui_story_5038_50380201_59_dialog_content = "Mengapa kita tidak meminta dua anggota Lin Guild di sini untuk menghibur kita dengan apa yang terjadi <color=#FFB400>hari itu</color>.",
  ui_story_5038_50380201_60_dialog_content = "Om nom nom nom... Lezat!",
  ui_story_5038_50380201_61_dialog_content = "Sini, Tinytail. Anda juga dapat memilikinya!",
  ui_story_5038_50380201_62_dialog_content = "Meong!",
  ui_story_5038_50380201_63_dialog_content = "Yah, itu akan membuatnya sibuk untuk sementara waktu.",
  ui_story_5038_50380201_64_dialog_content = "Jika Anda mau, Tuan Zhong.",
  ui_story_5038_50380201_65_dialog_content = "Aku ingin sekali, Kapten. Tapi ingat ini sudah lebih dari setengah tahun, jadi beberapa detailnya mungkin sedikit kabur.",
  ui_story_5038_50380201_66_dialog_content = "Namun demikian, izinkan saya untuk menceritakan seluruh cobaan, dari awal hingga akhir.",
  ui_story_5038_50380201_67_dialog_content = "Apa yang saya tunggu-tunggu! Ke mana pun perjalanan saya membawa saya, hal favorit saya adalah mendengarkan cerita orang.",
  ui_story_5038_50380201_68_dialog_content = "Ah, tapi cerita yang akan saya ceritakan mungkin lebih gelap dari yang biasa Anda dengar.",
  ui_story_5038_50380201_69_dialog_content = "Secara teknis, Liqing dan saya secara teknis bukan Lins, meskipun kapten kami yang baik tentu saja.",
  ui_story_5038_50380201_70_dialog_content = "Tidak perlu formalitas seperti itu, Tuanku.",
  ui_story_5038_50380201_71_dialog_content = "Dengan nama belakang seperti Mu, Lin seperti apa aku sebenarnya?",
  ui_story_5038_50380201_72_dialog_content = "Oh, maaf! Saya tidak berpikir. Aku tidak bermaksud menarik perhatian pada nama belakangmu.",
  ui_story_5038_50380201_73_dialog_content = "Bagaimanapun, saya hanyalah teman lama keluarga Lin, di mana Liqing adalah tamu lama.",
  ui_story_5038_50380201_74_dialog_content = "Sebenarnya, identitas kami adalah satu-satunya yang menyelamatkan hidup kami setelah kejadian itu.",
  ui_story_5038_50380201_75_dialog_content = "Jadi, apa yang terjadi enam bulan lalu?",
  ui_story_5038_50380201_76_dialog_content = "Semuanya dimulai dan diakhiri dengan The Compass.",
  ui_story_5038_50380201_77_dialog_content = "Kompas inilah yang memungkinkan Lins mendominasi perdagangan maritim, yang secara alami menarik perhatian jahat.",
  ui_story_5038_50380201_78_dialog_content = "Beberapa kelompok kecil bersatu di bawah pimpinan salah satu guild, dengan maksud untuk menjatuhkan Lins.",
  ui_story_5038_50380201_79_dialog_content = "Mereka tahu mereka tidak bisa menandingi kekuatan Lins, tetapi tidak takut untuk melakukan trik kotor dan taktik yang tidak tahu malu.",
  ui_story_5038_50380201_80_dialog_content = "Suatu hari, Liqing dan saya sedang dalam perjalanan ke perjamuan di Lin Manor, dihadiri oleh banyak teman terdekat keluarga.",
  ui_story_5038_50380201_81_dialog_content = "Saat malam tiba, perampok masuk dengan niat membunuh ...",
  ui_story_5038_50380202_1_dialog_content = "Zhong Xu! Disini!",
  ui_story_5038_50380202_2_dialog_content = "Kau baik-baik saja?",
  ui_story_5038_50380202_3_dialog_content = "Hanya goresan, tidak apa-apa.",
  ui_story_5038_50380202_4_dialog_content = "Kami setidaknya berhasil mengeluarkan Guildmaster Lin dengan aman.",
  ui_story_5038_50380202_5_dialog_content = "Guildmaster baik-baik saja?! Apa yang lega!",
  ui_story_5038_50380202_6_dialog_content = "Dia melarikan diri, tetapi yang lain ...",
  ui_story_5038_50380202_7_dialog_content = "Saya khawatir, setelah malam ini, keluarga Lin tidak lagi hadir di dunia pedagang.",
  ui_story_5038_50380202_8_dialog_content = "Bagaimana mereka bisa menyerbu manor dengan begitu berani?",
  ui_story_5038_50380202_9_dialog_content = "Mereka adalah preman bayaran. Mereka tidak peduli dengan bahaya.",
  ui_story_5038_50380202_10_dialog_content = "Seseorang pasti telah membayar mahal untuk mempertaruhkan nyawa mereka.",
  ui_story_5038_50380202_11_dialog_content = "Kalau tidak salah, mereka datang untuk The Compass.",
  ui_story_5038_50380202_12_dialog_content = "Kompas? Tapi itu bahkan tidak di Lin Manor ...",
  ui_story_5038_50380202_13_dialog_content = "Mereka masih belum tahu.",
  ui_story_5038_50380202_14_dialog_content = "Guildmaster Lin memiliki rencana darurat untuk memastikan keamanan The Compass.",
  ui_story_5038_50380202_15_dialog_content = "Jika gagal... Aku akan membalas Lins.",
  ui_story_5038_50380202_16_dialog_content = "Ikuti aku, Liqing.",
  ui_story_5038_50380202_17_dialog_content = "Setelah itu... Kami nyaris lolos dengan nyawa kami.",
  ui_story_5038_50380202_18_dialog_content = "Baru pada saat itulah kami menyadari target mereka malam itu bukanlah guildmaster.",
  ui_story_5038_50380202_19_dialog_content = "Untuk melindungi The Compass dan mencegahnya dari kehancuran atau pencurian, Guildmaster Lin memutuskan untuk meminta kerabat dekat membuangnya.",
  ui_story_5038_50380202_20_dialog_content = "Kompas dimuat ke kapal tua, yang segera meninggalkan pelabuhan dan menuju laut lepas. Kami pergi dengan itu.",
  ui_story_5038_50380202_21_dialog_content = "Mereka berlayar DENGAN Kompas? Saya tidak mengerti... Tentunya lebih berbahaya di laut?",
  ui_story_5038_50380202_22_dialog_content = "Bukankah lebih baik menguncinya di lemari besi atau semacamnya?",
  ui_story_5038_50380202_23_dialog_content = "Untuk sesuatu yang lahir dari laut, laut adalah tempat yang paling aman.",
  ui_story_5038_50380202_24_dialog_content = "Hah? Apa maksudmu?",
  ui_story_5038_50380202_25_dialog_content = "Selama Kompas memandu sebuah kapal, kapal itu tidak akan pernah tersesat, dan akan selalu ada angin yang cerah, perairan yang tenang, dan tidak ada kecelakaan.",
  ui_story_5038_50380202_26_dialog_content = "Namun…",
  ui_story_5038_50380202_27_dialog_content = "Ah, tapi Kompas masih hilang, bukan? Apakah itu yang akan Anda tanyakan, Kapten?",
  ui_story_5038_50380202_28_dialog_content = "Itu tidak hilang karena unsur-unsurnya.",
  ui_story_5038_50380202_29_dialog_content = "...",
  ui_story_5038_50380202_30_dialog_content = "Bajak laut sedang mengejar Shadowind.",
  ui_story_5038_50380202_31_dialog_content = "Kami berdua jatuh ke laut dalam semua keributan, dan kami tidak pernah berhasil kembali.",
  ui_story_5038_50380202_32_dialog_content = "Seperti yang Anda ketahui, para bajingan itu tidak pernah mendapatkan The Compass. Jalur laut tidak akan terputus selama ini.",
  ui_story_5038_50380202_33_dialog_content = "Segera setelah itu, baik para perompak maupun kami ditangkap di sebuah <color=#FFB400>badai dahsyat</color>.",
  ui_story_5038_50380202_34_dialog_content = "Semua jiwa di dalamnya hilang, kecuali Liqing muda di sini dan aku.",
  ui_story_5038_50380202_35_dialog_content = "Saat itu juga kaki saya terluka.",
  ui_story_5038_50380202_36_dialog_content = "Di mana semua ini terjadi?",
  ui_story_5038_50380202_37_dialog_content = "Saya tidak punya ide. Saya tidak memiliki indera arah pelaut.",
  ui_story_5038_50380202_38_dialog_content = "Ngomong-ngomong, mungkin itu sifat spiritual fiendling, tapi Liqing membawaku ke Astra.",
  ui_story_5038_50380202_39_dialog_content = "Tunggu... Benda apa itu <color=#FFB400>fiendling</color>?",
  ui_story_5038_50380202_40_dialog_content = "Yah, itu tidak sopan, PlayerName. fiendlings bukanlah benda.",
  ui_story_5038_50380202_41_dialog_content = "Biarkan saya mencerahkan Anda. Singkatnya, fiendlings adalah Aurorian seperti saya yang memiliki karakteristik binatang.",
  ui_story_5038_50380202_42_dialog_content = "Sementara kita membahasnya, Tinytail sebenarnya adalah kakak laki-laki saya.",
  ui_story_5038_50380202_43_dialog_content = "Mendesis-!",
  ui_story_5038_50380202_44_dialog_content = "Oh. Saya pikir saya mengerti.",
  ui_story_5038_50380202_45_dialog_content = "(Mereka pada dasarnya Aurorian dengan darah demi-human, bukan? Mungkin ini yang mereka sebut demi-human di Longzhou.)",
  ui_story_5038_50380202_46_dialog_content = "Menurut catatan keluarga Lin, kehilangan The Compass adalah peristiwa yang belum pernah terjadi sebelumnya.",
  ui_story_5038_50380202_47_dialog_content = "Meskipun saya belum pernah melihatnya dengan mata kepala sendiri, saya pernah mendengar bahwa itu adalah harta karun <color=#FFB400>hidup dan mati dengan kapalnya</color>.",
  ui_story_5038_50380202_48_dialog_content = "Saya masih ingin mencoba, semuanya. Bahkan jika kita hanya menemukan bangkai kapal, setidaknya aku tahu di mana jatuhnya.",
  ui_story_5038_50380202_49_dialog_content = "Saya tidak ingin kita mengalami bahaya seperti yang dibicarakan Zhong Xu.",
  ui_story_5038_50380202_50_dialog_content = "Saya mengerti. Demi semua orang yang ada di kapal, kami tidak dapat melepaskan harapan bahwa kami akan menemukannya.",
  ui_story_5038_50380202_51_dialog_content = "Bahkan jika Kapten tidak mengatakannya, saya tetap ingin menemukan benda itu.",
  ui_story_5038_50380202_52_dialog_content = "Sudah larut, jadi mari kita cari tempat untuk berlabuh di malam hari.",
  ui_story_5038_50380202_53_dialog_content = "Silakan istirahat malam yang baik. Aku akan tetap berjaga dengan kru.",
  ui_story_5038_50380202_54_dialog_content = "Iya, aku juga!",
  ui_story_5038_50380202_55_dialog_content = "Anak-anak harus tidur nyenyak.",
  ui_story_5038_50380202_56_dialog_content = "Aku sudah bilang, aku bukan anak kecil!",
  ui_story_5038_50380202_57_dialog_content = "Lagi pula, Tinytail dan aku tidak mudah tertidur di malam hari.",
  ui_story_5038_50380202_58_dialog_content = "Biarkan dia ikut. Kalau tidak, dia hanya akan mengganggu semua orang.",
  ui_story_5038_50380202_59_dialog_content = "Ayo! Saya tidak akan melakukan itu!",
  ui_story_5038_50380202_60_dialog_content = "Baik. Kalau begitu, ikuti aku ke geladak sebentar lagi, Liqing.",
  ui_story_5038_50380202_61_dialog_content = "Tempat tidur telah disiapkan di kabin penumpang; setiap orang mendapatkan ruang mereka sendiri. Jika Anda mengikuti saya, silakan.",
  ui_story_5038_50380301_1_dialog_content = "<color=#e8d9bb>Tengah malam</color>",
  ui_story_5038_50380301_2_dialog_content = "Zzz...",
  ui_story_5038_50380301_3_dialog_content = "<color=#e8d9bb>*Gemuruh*</color>",
  ui_story_5038_50380301_4_dialog_content = "(Hah? Apakah itu guntur...?)",
  ui_story_5038_50380301_5_dialog_content = "(Itu hujan...?)",
  ui_story_5038_50380301_6_dialog_content = "<color=#e8d9bb>GEDEBUK!!!</color>",
  ui_story_5038_50380301_7_dialog_content = "Waaaaah?!",
  ui_story_5038_50380301_8_dialog_content = "...?! Apa yang terjadi?",
  ui_story_5038_50380301_9_dialog_content = "<color=#e8d9bb>Meong!</color>",
  ui_story_5038_50380301_10_dialog_content = "<color=#e8d9bb>Meong!!</color>",
  ui_story_5038_50380301_11_dialog_content = "Disana disana. Tidak ada yang perlu ditakutkan.",
  ui_story_5038_50380301_12_dialog_content = "Maaf membangunkanmu, teman muda.",
  ui_story_5038_50380301_13_dialog_content = "Yixin, Yimeng, dan Yinuo... Mereka telah bersamaku sepanjang hidup mereka, dan bahkan selamat dari insiden di bekas Shadowind...",
  ui_story_5038_50380301_14_dialog_content = "Cuaca seperti ini membawa kembali kenangan buruk bagi mereka.",
  ui_story_5038_50380301_15_dialog_content = "Lupakan tangisan kucing! Apa kau tidak mendengar suara itu?!",
  ui_story_5038_50380301_16_dialog_content = "<color=#e8d9bb>GEDEBUK!!!</color>",
  ui_story_5038_50380301_17_dialog_content = "Semua orang bangun? Kalian semua baik-baik saja?",
  ui_story_5038_50380301_18_dialog_content = "Jiu mendengarnya lebih dulu. Aku sudah berkeliling dengannya, membangunkan siapa pun yang berhasil tidur karena keributan.",
  ui_story_5038_50380301_19_dialog_content = "Jadi apa yang sebenarnya terjadi?",
  ui_story_5038_50380301_20_dialog_content = "Saya tidak tahu, tapi rasanya ada sesuatu yang menabrak lambung kapal!",
  ui_story_5038_50380301_21_dialog_content = "Dan... Saya tidak berpikir itu <color=#FFB400>satu hal</color>.",
  ui_story_5038_50380301_22_dialog_content = "(Itu tidak mungkin Eclipsites, kan? Jauh-jauh ke laut, di tengah malam?!!)",
  ui_story_5038_50380301_23_dialog_content = "Aku akan pergi melihat apa yang terjadi di geladak!",
  ui_story_5038_50380301_24_dialog_content = "Izinkan aku pergi bersamamu, PlayerName.",
  ui_story_5038_50380301_25_dialog_content = "Tuan Zhong Xu, mungkin Anda ingin bergabung dengan Dantang dan saya mencari perlindungan?",
  ui_story_5038_50380301_26_dialog_content = "Jika saya ingat dengan benar, seharusnya ada perosotan di antara kabin penumpang di lantai bawah ini.",
  ui_story_5038_50380301_27_dialog_content = "Eh? Bagaimana kabarmu...",
  ui_story_5038_50380301_28_dialog_content = "Shadowind ini memiliki struktur yang sama dengan yang lama.",
  ui_story_5038_50380301_29_dialog_content = "Ayo, ayo cepat.",
  ui_story_5038_50380301_30_dialog_content = "Saya hanya punya satu hal untuk dikatakan, teman muda. Jika kalian berdua tidak bisa membantu Liqing dan Yuebai,",
  ui_story_5038_50380301_31_dialog_content = "kemudian keluar dari sana, dan berlindung di bawah geladak. Jangan jadi pahlawan.",
  ui_story_5038_50380301_32_dialog_content = "Aku akan, jangan khawatir.",
  ui_story_5038_50380301_33_dialog_content = "<color=#e8d9bb>Di Dek</color>",
  ui_story_5038_50380301_34_dialog_content = "Hujannya deras sekali...",
  ui_story_5038_50380301_35_dialog_content = "Yuebai! Liqing!",
  ui_story_5038_50380301_36_dialog_content = "Kapten Yuebai! Kucing kucing!",
  ui_story_5038_50380301_37_dialog_content = "Yah, ini tidak bekerja. Mereka tidak akan pernah mendengar kita selama hujan ini.",
  ui_story_5038_50380301_38_dialog_content = "Menurutmu kau bisa menemukan mereka secara fisik, Tn. Caelestite Legendaris?",
  ui_story_5038_50380301_39_option_content = "Force Boost",
  ui_story_5038_50380301_40_dialog_content = "Urgh... Tidak bagus. Saya hanya mendapatkan jejak samar Lumina dan Darkflow.",
  ui_story_5038_50380301_41_dialog_content = "Hah?!",
  ui_story_5038_50380301_42_dialog_content = "Ada hal lain... sesuatu yang belum pernah kutemui sebelumnya...",
  ui_story_5038_50380301_43_dialog_content = "Petugas Dantang benar... Ada banyak kelompok apapun mereka!",
  ui_story_5038_50380301_44_dialog_content = "Dan bukan hanya itu... Aku bisa merasakan energi yang kuat...",
  ui_story_5038_50380301_45_dialog_content = "Coba temukan mereka lagi!",
  ui_story_5038_50380301_46_dialog_content = "Tidak berguna. Aku tidak bisa merasakan mereka sama sekali...",
  ui_story_5038_50380301_47_dialog_content = "<color=#e8d9bb>MEMBANTING!!!</color>",
  ui_story_5038_50380301_48_dialog_content = "<size=50><color=#e8d9bb>GEDEBUK!!!</color></size>",
  ui_story_5038_50380301_49_dialog_content = "Wah, hati-hati!",
  ui_story_5038_50380301_50_dialog_content = "Ayo cari tahu apa yang membuat suara itu!",
  ui_story_5038_50380301_51_dialog_content = "Baiklah…",
  ui_story_5038_50380301_52_dialog_content = "I-Ini...",
  ui_story_5038_50380301_53_dialog_content = "Tinytail! Hentikan! Berhenti menggeliat!",
  ui_story_5038_50380301_54_dialog_content = "Aku tidak bisa bertahan!",
  ui_story_5038_50380301_55_dialog_content = "Kapten! Anda baik-baik saja di sana ?!",
  ui_story_5038_50380301_56_dialog_content = "Jaga dirimu dulu, Liqing! Pegang sesuatu! Cobalah untuk tidak bergerak!",
  ui_story_5038_50380301_57_dialog_content = "Liqing! Yuebai!",
  ui_story_5038_50380301_58_dialog_content = "Wah! Dia PlayerName dan Tianxian!",
  ui_story_5038_50380301_59_dialog_content = "Apa yang kalian lakukan di sini?!",
  ui_story_5038_50380301_60_dialog_content = "Bawa Liqing dan selamatkan dirimu, cepat!",
  ui_story_5038_50380301_61_dialog_content = "<size=50><color=#e8d9bb>GEDEBUK!!!</color></size>",
  ui_story_5038_50380301_62_dialog_content = "Nya... <color=#FFB400>ikan ular</color>!",
  ui_story_5038_50380301_63_dialog_content = "Mereka menabrak lambung kapal kita! Pembuat kapal!!",
  ui_story_5038_50380301_64_dialog_content = "Ya, cap'n?",
  ui_story_5038_50380301_65_dialog_content = "Bawa seseorang ke bawah geladak dan mulai protokol darurat untuk mencegah kerusakan dan kebocoran lambung kapal!",
  ui_story_5038_50380301_66_dialog_content = "Iya!",
  ui_story_5038_50380301_67_dialog_content = "Ikan ular...",
  ui_story_5038_50380301_68_dialog_content = "Tapi kenapa...? Mengapa mereka menabrak Shadowind?",
  ui_story_5038_50380301_69_dialog_content = "(Ini adalah ikan yang dibicarakan Liqing...)",
  ui_story_5038_50380301_70_dialog_content = "(Mereka tidak dapat disangkal cantik saat berkumpul... Tapi kekuatan gabungan mereka menakutkan!)",
  ui_story_5038_50380301_71_dialog_content = "<size=50><color=#e8d9bb>GEDEBUK!!!</color></size>",
  ui_story_5038_50380301_72_dialog_content = "Fokus, kucing! Jauhi rel, atau Anda bisa jatuh ke laut!",
  ui_story_5038_50380301_73_dialog_content = "Bagaimana kita bisa menghentikan mereka, Liqing?!",
  ui_story_5038_50380301_74_dialog_content = "Kami... Kami tidak bisa. Tanpa Kompas, tidak ada yang bisa kita lakukan...",
  ui_story_5038_50380301_75_dialog_content = "<size=50><color=#e8d9bb>MEMBANTING!</color></size>",
  ui_story_5038_50380301_76_dialog_content = "Oh, tidak...",
  ui_story_5038_50380301_77_dialog_content = "Keluar dari sini! Saya akan mencoba untuk menahannya dan mengulur waktu!",
  ui_story_5038_50380301_78_dialog_content = "Kami mulai daftar! Dapatkan ke sekoci!",
  ui_story_5038_50380301_79_dialog_content = "Tunggu!",
  ui_story_5038_50380301_80_dialog_content = "Apa??",
  ui_story_5038_50380301_81_dialog_content = "Sesuatu yang lain sedang membuat daftar Shadowind! Aku bisa merasakannya! Itu seperti...",
  ui_story_5038_50380301_82_dialog_content = "Sesuatu datang dalam jumlah besar...",
  ui_story_5038_50380301_83_dialog_content = "Grah...",
  ui_story_5038_50380301_84_dialog_content = "Graaagh!",
  ui_story_5038_50380301_85_dialog_content = "Tentu saja itu Eclipsites!",
  ui_story_5038_50380301_86_dialog_content = "... Kami beruntung memiliki Anda bersama kami, PlayerName.",
  ui_story_5038_50380301_87_dialog_content = "Ayo urus mereka!",
  ui_story_5038_50380302_1_dialog_content = "Kami akan memusnahkan mereka sekaligus!",
  ui_story_5038_50380302_2_dialog_content = "Saya berterima kasih atas bantuan Anda, PlayerName.",
  ui_story_5038_50380302_3_dialog_content = "Sepertinya kapalnya masih terdaftar, meskipun...",
  ui_story_5038_50380302_4_dialog_content = "<color=#e8d9bb>Kriek—</color>",
  ui_story_5038_50380302_5_dialog_content = "Bawa barang dan barang berat ke buritan untuk menyeimbangkan kapal, pelaut!",
  ui_story_5038_50380302_6_dialog_content = "Iya!",
  ui_story_5038_50380302_7_dialog_content = "Ikan menarik tali di haluan, begitulah Eclipsites bisa naik ke kapal.",
  ui_story_5038_50380302_8_dialog_content = "PlayerName, Liqing, Tianxian! Jika bisa, ikuti tukang perahu di belakang.",
  ui_story_5038_50380302_9_dialog_content = "Oke!",
  ui_story_5038_50380302_10_dialog_content = "Di Sini, PlayerName, ambil ini!",
  ui_story_5038_50380302_11_dialog_content = "Wah, berat!! Apa itu?",
  ui_story_5038_50380302_12_dialog_content = "Peti berisi pemberat besi dari Longzhou!",
  ui_story_5038_50380302_13_dialog_content = "... Apa-apaan yang dilakukan orang seperti ini di atas kapal?!",
  ui_story_5038_50380302_14_dialog_content = "Untuk pembukuan, penimbangan barang, dan sebagainya. Anda akan terkejut betapa seringnya mereka berguna.",
  ui_story_5038_50380302_15_dialog_content = "Maksudku, ternyata, kita membutuhkan mereka sekarang.",
  ui_story_5038_50380302_16_dialog_content = "Aku akan ambil dada juga. Ayo bawa mereka ke buritan, untuk memperbaiki daftar kapal.",
  ui_story_5038_50380302_17_dialog_content = "Anda tidak perlu membawa apapun, kitty. Anda mungkin akan menyakiti diri sendiri.",
  ui_story_5038_50380302_18_dialog_content = "Aku tinggal di sini.",
  ui_story_5038_50380302_19_dialog_content = "Apakah Anda mencoba untuk menjadi lucu? Ayo, bergerak.",
  ui_story_5038_50380302_20_dialog_content = "Aku berkata, aku tinggal di sini.",
  ui_story_5038_50380302_21_dialog_content = "(Liqing telah meneliti air selama berabad-abad, hampir seperti sedang mencari sesuatu...)",
  ui_story_5038_50380302_22_dialog_content = "Pernahkah Anda memikirkan sesuatu, Liqing? Apakah Anda tahu mengapa serpentfish menyerang?",
  ui_story_5038_50380302_23_dialog_content = "Tidak. Bukan petunjuk...",
  ui_story_5038_50380302_24_dialog_content = "Tapi ikan ular tidak pernah menyerang orang tanpa alasan!",
  ui_story_5038_50380302_25_dialog_content = "Mereka harus mengikuti perintah pemimpin sekolah mereka, ikan alfa.",
  ui_story_5038_50380302_26_dialog_content = "Tapi kenapa dia ingin menyerang kapal kita? Apa yang diinginkannya...?",
  ui_story_5038_50380302_27_dialog_content = "Apakah Anda mencoba menemukan ikan alfa ini?",
  ui_story_5038_50380302_28_dialog_content = "Setidaknya... Aku perlu melihat dengan jelas dari mana <color=#FFB400>arah</color> mereka datang.",
  ui_story_5038_50380302_29_dialog_content = "<color=#e8d9bb>MEMBANTING!!!</color>",
  ui_story_5038_50380302_30_dialog_content = "(Ikan ular semakin banyak bekerja. Jika ini berlangsung lebih lama lagi...)",
  ui_story_5038_50380302_31_option_content = "Force Boost!",
  ui_story_5038_50380302_32_dialog_content = "Apakah itu akan berhasil?!",
  ui_story_5038_50380302_33_dialog_content = "Saya tidak begitu tahu! Tapi tidak ada salahnya untuk mencoba!",
  ui_story_5038_50380302_34_dialog_content = "(Saya akan mencoba melakukan apa yang saya lakukan sebelumnya...)",
  ui_story_5038_50380302_35_dialog_content = "(Makhluk-makhluk ini sepertinya datang dari timur... Biarkan aku mencoba menenangkan mereka...)",
  ui_story_5038_50380302_36_dialog_content = "(Sial, kali ini tidak berfungsi!)",
  ui_story_5038_50380302_37_dialog_content = "Mereka sepertinya akan berhenti. Lihat!",
  ui_story_5038_50380302_38_dialog_content = "Dengan serius? Ide gilaku berhasil?!",
  ui_story_5038_50380302_39_dialog_content = "Mereka tiba-tiba berbalik sekaligus, membentuk sabuk panjang ikan ...",
  ui_story_5038_50380302_40_dialog_content = "... Tidak, tunggu! Ada yang salah!!",
  ui_story_5038_50380302_41_dialog_content = "A-Apa maksudmu?",
  ui_story_5038_50380302_42_dialog_content = "Teman-teman! Raih rel dan naik ke lantai!",
  ui_story_5038_50380302_43_dialog_content = "Mereka... menagih kita!",
  ui_story_5038_50380302_44_dialog_content = "Kapten! Putar kapalnya, cepat!",
  ui_story_5038_50380302_45_dialog_content = "(Ikan ular itu sudah menyebabkan kerusakan serius. Belum lagi badai ini...)",
  ui_story_5038_50380302_46_dialog_content = "(Saya hampir tidak bisa menggerakkan kemudi...)",
  ui_story_5038_50380302_47_dialog_content = "Bersiaplah, semuanya! Tahan dan lindungi kepalamu!",
  ui_story_5038_50380302_48_dialog_content = "(Apakah Shadowind akan menyerah pada kekuatan lautan sekali lagi?)",
  ui_story_5038_50380302_49_dialog_content = "<size=45><color=#e8d9bb>GEDEBUK!!!</color></size>",
  ui_story_5038_50380402_1_dialog_content = "Aduh!",
  ui_story_5038_50380402_2_dialog_content = "(Seluruh tubuhku sakit... Punggungku kesakitan...)",
  ui_story_5038_50380402_3_dialog_content = "(Tapi aku masih hidup... adil.)",
  ui_story_5038_50380402_4_dialog_content = "Kau tidak apa-apa, PlayerName?",
  ui_story_5038_50380402_5_dialog_content = "Yuebai! Kamu hidup!",
  ui_story_5038_50380402_6_dialog_content = "Bagaimana dengan... orang lain?",
  ui_story_5038_50380402_7_dialog_content = "Bangunlah sebelum matahari membakar kulitmu, PlayerName.",
  ui_story_5038_50380402_8_dialog_content = "Anda tampaknya relatif tidak terluka, anak muda.",
  ui_story_5038_50380402_9_dialog_content = "Anda membuat kami khawatir sejenak di sana.",
  ui_story_5038_50380402_10_dialog_content = "Kepalaku masih sakit... Sebenarnya apa yang terjadi tadi malam?",
  ui_story_5038_50380402_11_dialog_content = "Kami kehilangan kendali atas Shadowind setelah ditabrak dengan keras.",
  ui_story_5038_50380402_12_dialog_content = "Kami akhirnya menabrak beberapa karang.",
  ui_story_5038_50380402_13_dialog_content = "Angin dan ombak berangsur-angsur mereda, setelah ikan ular bubar.",
  ui_story_5038_50380402_14_dialog_content = "Anda dan Tianxian pingsan dalam semua kekacauan, jadi Anda dibawa ke kabin penumpang oleh kru.",
  ui_story_5038_50380402_15_dialog_content = "Untungnya, dokter kecil kami Liqing ada di sana. Dia sudah meresepkan obat yang sesuai untuk kalian berdua.",
  ui_story_5038_50380402_16_dialog_content = "Mengangkut kalian kembali ke sini untuk berjemur adalah ideku juga.",
  ui_story_5038_50380402_17_dialog_content = "Di sini enak dan hangat...",
  ui_story_5038_50380402_18_dialog_content = "Hah?!",
  ui_story_5038_50380402_19_dialog_content = "Eww! A-Apa yang ada di mulutku? Ini benar-benar pahit!",
  ui_story_5038_50380402_20_dialog_content = "Hei, jangan dimuntahkan dulu. Ini sedikit sesuatu untuk mabuk laut.",
  ui_story_5038_50380402_21_dialog_content = "Napas Setan, honeysuckle, dan sedikit mint.",
  ui_story_5038_50380402_22_dialog_content = "Jika pahit maka itu baik untukmu, PlayerName. Tetap bertahan!",
  ui_story_5038_50380402_23_dialog_content = "B-baiklah…",
  ui_story_5038_50380402_24_dialog_content = "Karena Anda bisa bangun dan bergerak dengan baik, maka tidak banyak yang perlu dikhawatirkan.",
  ui_story_5038_50380402_25_dialog_content = "Lebih penting lagi, bagaimana kabar Shadowind? Setelah semua yang dia lalui tadi malam.",
  ui_story_5038_50380402_26_dialog_content = "Tidak terlalu baik.",
  ui_story_5038_50380402_27_dialog_content = "Badai mematahkan tiang kapal, dan pegangannya bocor.",
  ui_story_5038_50380402_28_dialog_content = "Bisa dibilang dia sedang dalam dukungan hidup. Saya akan berhati-hati saat membawanya keluar di perairan yang berombak ringan.",
  ui_story_5038_50380402_29_dialog_content = "Seburuk itu?!",
  ui_story_5038_50380402_30_dialog_content = "Terlalu berisiko untuk berlayar, bukan?",
  ui_story_5038_50380402_31_dialog_content = "... Sejarah terulang kembali. Inilah yang terjadi terakhir kali.",
  ui_story_5038_50380402_32_dialog_content = "Saya dengan keras kepala ingin melanjutkan jalur laut, dan cukup bodoh untuk percaya bahwa saya dapat mencapai Astra dengan keterampilan pelayaran saya sendiri.",
  ui_story_5038_50380402_33_dialog_content = "Saya sangat yakin bahkan tanpa The Compass, saya akan cukup beruntung untuk kembali hidup.",
  ui_story_5038_50380402_34_dialog_content = "Melihat hal-hal sekarang ... Saya kira Lins benar-benar membutuhkan perlindungannya.",
  ui_story_5038_50380402_35_dialog_content = "Memikirkan kembali tadi malam, ikan ular itu benar-benar aneh.",
  ui_story_5038_50380402_36_dialog_content = "Kapten, Anda adalah anggota Lin, Anda pasti tahu bagaimana perilaku ikan ular.",
  ui_story_5038_50380402_37_dialog_content = "Mereka adalah hewan yang sangat sosial, dan tidak akan pernah menyerang tanpa perintah dari beberapa pemimpin.",
  ui_story_5038_50380402_38_dialog_content = "Itu yang dulu kami pikirkan.",
  ui_story_5038_50380402_39_dialog_content = "Temperamen para pengembara lautan ini telah berubah selama setengah tahun terakhir.",
  ui_story_5038_50380402_40_dialog_content = "Mereka mulai menyerang kapal tanpa provokasi apapun, tidak membiarkan sampai kapal dan semua orang di dalamnya binasa.",
  ui_story_5038_50380402_41_dialog_content = "Sekarang, saya dikenal terpaku pada tujuan tunggal saya, tetapi saya tidak akan mengambil risiko dengan banyak nyawa.",
  ui_story_5038_50380402_42_dialog_content = "Aku takut bahwa sisa perjalanan...",
  ui_story_5038_50380402_43_dialog_content = "A-Apa? Jika kita tidak bisa terus berjalan, kita juga tidak bisa duduk di sini selamanya...",
  ui_story_5038_50380402_44_dialog_content = "Bukankah kita hanya duduk bebek menunggu mati?",
  ui_story_5038_50380402_45_dialog_content = "...",
  ui_story_5038_50380402_46_dialog_content = "Kapten...",
  ui_story_5038_50380402_47_dialog_content = "Ini hampir tengah hari, ada apa dengan semua malapetaka dan kesuraman?",
  ui_story_5038_50380402_48_dialog_content = "Saya punya tiga keberuntungan di sini untuk diceritakan. Siapa yang siap untuk itu?",
  ui_story_5038_50380402_49_dialog_content = "Tidak ada yang ingin mendengar omong kosong takhayulmu di saat seperti ini.",
  ui_story_5038_50380402_50_dialog_content = "Itu pasti bukan omong kosong. Yang lain mungkin tidak tertarik, Kapten, tapi saya pikir Anda harus mendengarkan saya.",
  ui_story_5038_50380402_51_dialog_content = "Kenapa harus aku?",
  ui_story_5038_50380402_52_dialog_content = "Saya terbangun dari mimpi yang paling aneh, lalu mendapat firasat bahwa sesuatu akan terjadi.",
  ui_story_5038_50380402_53_dialog_content = "Setiap kali saya mengingat peristiwa tadi malam, saya diingatkan bahwa wahyu cenderung datang di tengah kesulitan.",
  ui_story_5038_50380402_54_dialog_content = "Bisakah Anda langsung ke intinya.",
  ui_story_5038_50380402_55_dialog_content = "Baik. Pada dasarnya, saya mengambil sendiri untuk mengintip ke dalam kabut masa depan Shadowind.",
  ui_story_5038_50380402_56_dialog_content = "Alat sederhana Ramalan Hexagram Surgawi saya, simbol yin-yang dan hewan zodiak, berbicara kebijaksanaan bagi mereka yang peduli untuk mendengarkan.",
  ui_story_5038_50380402_57_dialog_content = "Sayangnya, meskipun saya terampil memprediksi masa depan dan menghitung takdir, saya tidak terbiasa dengan kapal itu.",
  ui_story_5038_50380402_58_dialog_content = "Jadi saya membutuhkan bimbingan Kapten kami yang baik, untuk membantu saya menguraikan jawaban yang diberikan.",
  ui_story_5038_50380402_59_dialog_content = "Cukup dengan sandiwara. Langsung saja ke intinya.",
  ui_story_5038_50380402_60_dialog_content = "Situasi Shadowind sangat parah. Kami hanya bisa melakukan apa yang kami bisa dan berdoa semoga rejeki ada di pihak kami.",
  ui_story_5038_50380402_61_dialog_content = "Saya dihadapkan dengan kelompok tiga hewan yang sangat aneh: tikus yang ragu-ragu, monyet yang bodoh, dan kelinci yang cerdik.",
  ui_story_5038_50380402_62_dialog_content = "Selama bertahun-tahun saya meramal jauh dan luas, saya belum pernah menemukan kombinasi yang begitu membingungkan.",
  ui_story_5038_50380402_63_dialog_content = "Ketiganya muncul dengan kombinasi heksagram yin-yang yang sama, yang tampaknya mengisyaratkan hal yang sama.",
  ui_story_5038_50380402_64_dialog_content = "Seekor tikus, monyet, dan kelinci...?",
  ui_story_5038_50380402_65_dialog_content = "Lalu apa interpretasi Anda?",
  ui_story_5038_50380402_66_dialog_content = "Saya bukan ahli, tetapi kesimpulan saya adalah bahwa mereka merujuk pada sesuatu yang berkaitan dengan pertukaran satu komoditas dengan komoditas lainnya.",
  ui_story_5038_50380402_67_dialog_content = "\"Yang ilusi menjadi nyata, ketika yang nyata menjadi ilusi.\" Pada dasarnya, itu memberitahu kita untuk <color=#FFB400>mengganti</color> yang telah kita hilangkan.",
  ui_story_5038_50380402_68_dialog_content = "Mengganti...?",
  ui_story_5038_50380402_69_dialog_content = "Oh! Saya pikir saya mengerti!",
  ui_story_5038_50380402_70_dialog_content = "Kebiasaan tanah air kita adalah menamai bagian-bagian penting lambung kapal dengan nama 12 hewan zodiak.",
  ui_story_5038_50380402_71_dialog_content = "Kami berdoa ini membawa keberuntungan bagi kami, agar kami dapat mengarungi lautan dengan mantap seperti makhluk yang menginjak daratan.",
  ui_story_5038_50380402_72_dialog_content = "Banyak bagian lambung rusak akibat badai tadi malam.",
  ui_story_5038_50380402_73_dialog_content = "Termasuk ekor tikus di buritan, dan kepala monyet di haluan. Yang pertama hilang total, dan yang lainnya rusak.",
  ui_story_5038_50380402_74_dialog_content = "Tapi pagar samping, telinga kelinci, baik-baik saja.",
  ui_story_5038_50380402_75_dialog_content = "Hmm... Kalau begitu saya akan bermeditasi lebih jauh pada telinga kelinci.",
  ui_story_5038_50380402_76_dialog_content = "Tetapi jika Anda menemukan sesuatu untuk menggantikan dua yang pertama, apakah Shadowind setidaknya bisa berlayar?",
  ui_story_5038_50380402_77_dialog_content = "Ini akan membantu membuatnya layak berlayar, tapi itu tidak cukup.",
  ui_story_5038_50380402_78_dialog_content = "Lambungnya rusak di beberapa tempat, jadi kami tidak bisa mengambil jalan pintas. Kami harus memperbaiki kapal, bagian demi bagian.",
  ui_story_5038_50380402_79_dialog_content = "Juga, di mana tepatnya saya harus mencari pengganti suku cadang ini?",
  ui_story_5038_50380402_80_dialog_content = "Saya mungkin punya ide.",
  ui_story_5038_50380402_81_dialog_content = "Tepat di bawah kami terletak salah satu gudang harta terbesar—laut.",
  ui_story_5038_50380501_1_dialog_content = "(Zhong Xu dan Yuebai pada akhirnya memutuskan untuk tidak menggunakan sekoci, dan tetap berada di Shadowind.)",
  ui_story_5038_50380501_2_dialog_content = "(Mereka bahkan mengangkat jangkar.)",
  ui_story_5038_50380501_3_dialog_content = "(... Apakah tidak apa-apa berlayar lagi secepat ini?)",
  ui_story_5038_50380501_4_dialog_content = "Kami membuat pilihan yang berisiko.",
  ui_story_5038_50380501_5_dialog_content = "Namun, lautan telah menelan kapal yang tak terhitung jumlahnya. Jika kita bisa sampai ke tempat para perompak menyerang kita setengah tahun yang lalu...",
  ui_story_5038_50380501_6_dialog_content = "Kami mungkin dapat menyelamatkan beberapa bagian yang berguna.",
  ui_story_5038_50380501_7_dialog_content = "Padahal aku tahu ini sama saja dengan mencari jarum di tumpukan jerami.",
  ui_story_5038_50380501_8_dialog_content = "Namun, kami turun ke pilihan terakhir kami.",
  ui_story_5038_50380501_9_dialog_content = "Aku setuju.",
  ui_story_5038_50380501_10_dialog_content = "Sekoci di atas kapal tidak akan mampu menahan badai.",
  ui_story_5038_50380501_11_dialog_content = "Kita juga tidak bisa hanyut di atas air selamanya.",
  ui_story_5038_50380501_12_dialog_content = "Lebih baik setidaknya mendayung dalam cuaca baik daripada duduk dan membusuk.",
  ui_story_5038_50380501_13_dialog_content = "Baiklah, kru. Bawa masuk layar yang rusak, dan rentangkan dayung.",
  ui_story_5038_50380501_14_dialog_content = "Kami akan mengikuti peta bahari dan mendayung menuju lokasi kapal karam.",
  ui_story_5038_50380501_15_dialog_content = "Meskipun ini adalah perintah Kapten, saya masih berpikir itu terlalu berisiko...",
  ui_story_5038_50380501_16_dialog_content = "Jaga lidahmu, nak. Lebih baik tidak mengatakan hal-hal seperti itu saat masih di atas kapal.",
  ui_story_5038_50380501_17_dialog_content = "Bahkan jika kita mengalami bencana, itu bukan seolah-olah kita memiliki kendali atas hidup kita.",
  ui_story_5038_50380501_18_dialog_content = "Apakah Kapten Yuebai seseorang yang penilaiannya harus Anda pertanyakan?",
  ui_story_5038_50380501_19_dialog_content = "P-Putri Dantang...",
  ui_story_5038_50380501_20_dialog_content = "Jika Anda memiliki keluhan, pintunya selalu terbuka. Saya yakin dia akan senang bekerja sama untuk menemukan solusi.",
  ui_story_5038_50380501_21_dialog_content = "Di atas air yang bergejolak ini, jika seseorang bahkan tidak takut mati, ketakutan apa yang Anda miliki untuk menghina seseorang secara langsung?",
  ui_story_5038_50380501_22_dialog_content = "Apa yang terjadi di sini?",
  ui_story_5038_50380501_23_dialog_content = "Ah, Yuebai. Orang-orang ini memiliki sesuatu yang ingin mereka katakan kepada Anda.",
  ui_story_5038_50380501_24_dialog_content = "T-Tidak, aku tidak. Tidak. Tidak ada apa-apa.",
  ui_story_5038_50380501_25_dialog_content = "Aku juga tidak. Tolong, Putri... Lepaskan kami.",
  ui_story_5038_50380501_26_dialog_content = "...",
  ui_story_5038_50380501_27_dialog_content = "<color=#e8d9bb>Desir—Swash!</color>",
  ui_story_5038_50380501_28_dialog_content = "K-Kasihanilah kami, Kapten! Kita...",
  ui_story_5038_50380501_29_dialog_content = "Berputar.",
  ui_story_5038_50380501_30_dialog_content = "Hah…?",
  ui_story_5038_50380501_31_dialog_content = "Graah...",
  ui_story_5038_50380501_32_dialog_content = "Naik kapal di siang bolong? Sangat kasar!",
  ui_story_5038_50380501_33_dialog_content = "Anda tidak bisa mengajarkan sopan santun untuk hal-hal itu.",
  ui_story_5038_50380501_34_dialog_content = "Dapatkan di belakangku, kalian berdua.",
  ui_story_5038_50380501_35_dialog_content = "Aku tidak akan membiarkanmu mati begitu saja.",
  ui_story_5038_50380501_36_dialog_content = "A-Aye, cap'n!",
  ui_story_5038_50380602_1_dialog_content = "Ekor tikus, kepala monyet, telinga kelinci...",
  ui_story_5038_50380602_2_dialog_content = "Sangat samar. Nama-nama itu tidak benar-benar menawarkan banyak petunjuk tentang apa itu, meong.",
  ui_story_5038_50380602_3_dialog_content = "Sederhananya, mereka mewakili baling-baling angin, katrol, dan papan.",
  ui_story_5038_50380602_4_dialog_content = "<color=#FFB400>Baling-baling angin</color> perlu dipasang tepat di atas tiang.",
  ui_story_5038_50380602_5_dialog_content = "Tali yang diikatkan ke buritan terlihat seperti ekor tikus.",
  ui_story_5038_50380602_6_dialog_content = "Itu mengapung, karena sangat ringan.",
  ui_story_5038_50380602_7_dialog_content = "<color=#FFB400>Katrol</color> cukup standar, mengingat mereka dibutuhkan untuk mengelola layar.",
  ui_story_5038_50380602_8_dialog_content = "Mereka disebut \"kepala monyet\" karena ukuran dan bentuknya.",
  ui_story_5038_50380602_9_dialog_content = "Jika kita bisa menemukan pengganti untuk keduanya, kita akan bisa menggunakan layar kita lagi.",
  ui_story_5038_50380602_10_dialog_content = "Wow, Anda membuatnya terdengar sangat mudah!",
  ui_story_5038_50380602_11_dialog_content = "Lalu bagaimana dengan telinga kelinci?",
  ui_story_5038_50380602_12_dialog_content = "... Itu istimewa, dan tidak mudah diganti.",
  ui_story_5038_50380602_13_dialog_content = "Untungnya telinga kelinci kita tidak rusak, jadi mari kita berkonsentrasi pada dua lainnya dulu.",
  ui_story_5038_50380602_14_dialog_content = "Siap!",
  ui_story_5038_50380602_15_dialog_content = "Bisakah Anda meminjamkan kami tangan, PlayerName, Dantang?",
  ui_story_5038_50380602_16_dialog_content = "Tentu saja!",
  ui_story_5038_50380602_17_dialog_content = "(A-aku tidak tahu apa yang terjadi...!)",
  ui_story_5038_50380602_18_dialog_content = "Anda tidak perlu berpura-pura, Yang Mulia. Di rumah, Anda jarang berkelana ke luar pekarangan.",
  ui_story_5038_50380602_19_dialog_content = "Wajar jika Anda tidak memahami hal-hal ini.",
  ui_story_5038_50380602_20_dialog_content = "... Mungkin seperti yang Anda katakan, tapi saya masih ingin membantu.",
  ui_story_5038_50380602_21_dialog_content = "Nah, mengingat Anda tidak berpikir saya perlu membuktikan diri, maka saya pikir Anda tidak perlu mengikuti saya kemana-mana.",
  ui_story_5038_50380602_22_dialog_content = "P-Putri...",
  ui_story_5038_50380602_23_dialog_content = "Betapa keras kepala, meong!",
  ui_story_5038_50380602_24_dialog_content = "Harap hindari penilaian yang tidak sopan terhadap Putri.",
  ui_story_5038_50380602_25_dialog_content = "Baiklah baiklah! Ayo bergerak, PlayerName.",
  ui_story_5038_50380602_26_dialog_content = "Tapi... aku tidak tahu kemana kita harus pergi, atau bagaimana kita harus mulai mencari.",
  ui_story_5038_50380602_27_dialog_content = "Hm, mari kita lihat...",
  ui_story_5038_50380602_28_dialog_content = "Tinytail dan aku akan mengendus dulu. Mari kita mengendus-endus di sekitar geladak!",
  ui_story_5038_50380602_29_dialog_content = "Kami, kucing, dapat mencium bau ekor tikus dari jarak satu mil!",
  ui_story_5038_50380602_30_dialog_content = "Um, aku tidak yakin kita membicarakan hal yang sama...!",
  ui_story_5038_50380602_31_dialog_content = "<color=#e8d9bb>Kabin Penumpang Shadowind</color>",
  ui_story_5038_50380602_32_dialog_content = "Hrrgh...",
  ui_story_5038_50380602_33_dialog_content = "(Harus mencari di mana-mana ...)",
  ui_story_5038_50380602_34_dialog_content = "Apa yang kamu cari, Putri?",
  ui_story_5038_50380602_35_dialog_content = "Tidak ada yang menjadi urusanmu.",
  ui_story_5038_50380602_36_dialog_content = "Hei, jangan terlalu cepat menolakku! Daripada melihat secara membabi buta, kenapa tidak biarkan aku meramal untukmu, hmm?",
  ui_story_5038_50380602_37_dialog_content = "... Anda benar-benar berkomitmen pada penipuan Anda.",
  ui_story_5038_50380602_38_dialog_content = "Nah sekarang, pasti kejadian baru-baru ini membuktikan bahwa ini bukan penipuan.",
  ui_story_5038_50380602_39_dialog_content = "Aku akui itu... Meskipun itu bisa jadi tebakan yang beruntung.",
  ui_story_5038_50380602_40_dialog_content = "Aku mencari ekor tikus yang menurut Kapten hilang.",
  ui_story_5038_50380602_41_dialog_content = "Anda sedang mencari di kapal?",
  ui_story_5038_50380602_42_dialog_content = "Ya, semua hal dipertimbangkan, itulah kesimpulan tentatif saya.",
  ui_story_5038_50380602_43_dialog_content = "Kapten mengatakan bahwa ekor tikus ini sangat ringan, dan akan mengapung jika dilempar ke air.",
  ui_story_5038_50380602_44_dialog_content = "Para kru terus berpatroli di kapal sejak kejadian tadi malam.",
  ui_story_5038_50380602_45_dialog_content = "Pelaut Lin Guild sangat legendaris dalam apa yang mereka lakukan. Mereka bahkan akan melihat pin yang jatuh ke laut.",
  ui_story_5038_50380602_46_dialog_content = "Jadi, apapun benda ini, harus tetap ada di kapal.",
  ui_story_5038_50380602_47_dialog_content = "Sangat perseptif, Putri! Saya setuju dengan garis pemikiran Anda.",
  ui_story_5038_50380602_48_dialog_content = "Karena itu, mari kita cari kapalnya.",
  ui_story_5038_50380602_49_dialog_content = "Mengomel! Mengoceh!",
  ui_story_5038_50380602_50_dialog_content = "Aku tahu, aku tahu.",
  ui_story_5038_50380602_51_dialog_content = "Berhenti mendorong, berhenti mendorong.",
  ui_story_5038_50380602_52_dialog_content = "Jalak berbicara?!",
  ui_story_5038_50380602_53_dialog_content = "Saya melatih mereka untuk meniru ucapan manusia.",
  ui_story_5038_50380602_54_dialog_content = "Pergilah sekarang, Squawk dan Jabber, coba temukan baling-baling angin misterius seperti tikus ini.",
  ui_story_5038_50380602_55_dialog_content = "Aku punya suguhan menunggumu.",
  ui_story_5038_50380602_56_dialog_content = "<color=#e8d9bb>*Kepak*... *Kepak*...</color>",
  ui_story_5038_50380602_57_dialog_content = "Tidak akan bergantung pada ramalan terpercaya Anda kali ini?",
  ui_story_5038_50380602_58_dialog_content = "Burung yang baik memilih tuan yang baik. Lagi pula, pada saat-saat seperti ini, pandangan mata burung lebih baik daripada ramalan.",
  ui_story_5038_50380602_59_dialog_content = "Ayo, Putri. Ayo ikuti dua pemburu harta karun kita.",
  ui_story_5038_50380602_60_dialog_content = "Ekor tikus kecil ini tidak akan tersembunyi lebih lama lagi.",
  ui_story_5038_50380602_61_dialog_content = "<color=#e8d9bb>Caw! Caw!</color>",
  ui_story_5038_50380602_62_dialog_content = "Beri aku kurma yang montok dan manis, caw!",
  ui_story_5038_50380602_63_dialog_content = "Beri aku biji melon manis yang enak, caw!",
  ui_story_5038_50380602_64_dialog_content = "Saya tahu saya tahu. Anda akan mendapatkan hadiah Anda. Apakah kamu menemukannya?",
  ui_story_5038_50380602_65_dialog_content = "Itu…?",
  ui_story_5038_50380602_66_dialog_content = "Memang terlihat seperti ekor... Ini pasti itu!",
  ui_story_5038_50380602_67_dialog_content = "Ya! Sepertinya Anda benar sekali.",
  ui_story_5038_50380602_68_dialog_content = "Beruntung kalian berdua bisa menemukannya di tengah semua kotoran itu.",
  ui_story_5038_50380602_69_dialog_content = "Anda akan segera mendapatkan kurma dan biji melon yang lezat!",
  ui_story_5038_50380602_70_dialog_content = "Ambillah, Putri.",
  ui_story_5038_50380602_71_dialog_content = "Pergi bawa ke Kapten Yuebai.",
  ui_story_5038_50380701_1_dialog_content = "(Setelah Dantang memberikan \"ekor tikus\" ke Yuebai...)",
  ui_story_5038_50380701_2_dialog_content = "(Perbaikan kapal berjalan dengan baik, dan tiang kapal hampir pulih.)",
  ui_story_5038_50380701_3_dialog_content = "(Ini berlayar jauh lebih mulus, hampir seperti kecelakaan itu tidak pernah terjadi.)",
  ui_story_5038_50380701_4_dialog_content = "(Hanya saja...)",
  ui_story_5038_50380701_5_dialog_content = "Anginnya berubah. Bersiaplah untuk berhenti mendayung dan membuang jangkar!",
  ui_story_5038_50380701_6_dialog_content = "Iya!",
  ui_story_5038_50380701_7_dialog_content = "(Kecuali kita masih harus berhenti tiba-tiba sesekali.)",
  ui_story_5038_50380701_8_dialog_content = "Kau terlihat khawatir, anak muda.",
  ui_story_5038_50380701_9_dialog_content = "Saya tidak. Saya kira ... Saya percaya penilaian Yuebai.",
  ui_story_5038_50380701_10_dialog_content = "Tidak perlu menyembunyikan perasaanmu. Saya curiga kita memikirkan hal yang sama.",
  ui_story_5038_50380701_11_dialog_content = "(Dia melihat melalui saya ...)",
  ui_story_5038_50380701_12_dialog_content = "Kami sedang menuju ke lokasi terakhir Kompas dengan bantuan peta bahari.",
  ui_story_5038_50380701_13_dialog_content = "Namun kapal tersebut masih dalam kondisi genting, dan perbaikan sementara lebih merupakan plester daripada penyembuhan.",
  ui_story_5038_50380701_14_dialog_content = "Berlayar adalah keterampilan yang sangat tepat dengan sedikit ruang untuk kesalahan.",
  ui_story_5038_50380701_15_dialog_content = "Doa saja tidak akan memastikan segala sesuatunya berjalan lancar.",
  ui_story_5038_50380701_16_dialog_content = "... Namun, itu hanya kekhawatiran kecil saya.",
  ui_story_5038_50380701_17_dialog_content = "Jangan dimasukkan ke dalam hati.",
  ui_story_5038_50380701_18_dialog_content = "Tentu. Saya akan mencoba mengumpulkan diri. Dan Zhong Xu, kamu juga ingat untuk tidak terlalu khawatir!",
  ui_story_5038_50380701_19_dialog_content = "Shadowind mengalami segala macam rintangan, namun berhasil tiba dengan selamat di Astra; tidak mungkin dia membiarkan kita binasa di laut.",
  ui_story_5038_50380701_20_dialog_content = "Kesunyian!",
  ui_story_5038_50380701_21_dialog_content = "A-Apa?!",
  ui_story_5038_50380701_22_dialog_content = "... Maaf, saya bereaksi berlebihan.",
  ui_story_5038_50380701_23_dialog_content = "Di kampung halaman saya, mengatakan hal-hal seperti itu dianggap tabu ketika datangnya tahun baru sudah di depan mata.",
  ui_story_5038_50380701_24_dialog_content = "Saya tahu itu hanya kebiasaan kecil yang tidak berbahaya, tapi saya harap Anda mengerti.",
  ui_story_5038_50380701_25_dialog_content = "Sekarang permisi, saya akan pergi.",
  ui_story_5038_50380701_26_dialog_content = "(Apakah maksudnya... berbicara tentang kematian itu tabu?)",
  ui_story_5038_50380701_27_dialog_content = "Anda tidak sering melihat Zhong Xu begitu bersemangat.",
  ui_story_5038_50380701_28_dialog_content = "Saya kira dia khawatir membuat kesalahan yang sama seperti yang dia lakukan enam bulan lalu.",
  ui_story_5038_50380701_29_dialog_content = "PlayerName, bisakah Anda membantu saya?",
  ui_story_5038_50380701_30_dialog_content = "Aku diam-diam memindahkan sekoci kayu kecil ini ke rel.",
  ui_story_5038_50380701_31_dialog_content = "Hah? Tunggu sebentar! Bukankah ini pada dasarnya adil <color=#FFB400>pencurian</color>?",
  ui_story_5038_50380701_32_dialog_content = "Ayolah, jangan dramatis, meong.",
  ui_story_5038_50380701_33_dialog_content = "Lihat, Kapten dan Zhong Xu sedang mendiskusikan rembesan dan pencegahan kebocoran.",
  ui_story_5038_50380701_34_dialog_content = "Saya tidak mungkin mengganggu mereka untuk ini.",
  ui_story_5038_50380701_35_dialog_content = "Tapi apa yang ingin Anda lakukan dengan sekoci?",
  ui_story_5038_50380701_36_dialog_content = "Menyelamatkan \"kepala monyet\", tentu saja!",
  ui_story_5038_50380701_37_dialog_content = "Mustahil! Itu terlalu berbahaya!",
  ui_story_5038_50380701_38_dialog_content = "Dengarkan aku, PlayerName. Jika Shadowind adalah manusia, dia pasti sedang sakit sekarang.",
  ui_story_5038_50380701_39_dialog_content = "Penyakit perlu diobati dengan obat yang tepat. Beberapa herbal cukup sederhana untuk didapatkan.",
  ui_story_5038_50380701_40_dialog_content = "Sementara beberapa tumbuh di tengah permukaan tebing vertikal, jauh dari jangkauan siapa pun.",
  ui_story_5038_50380701_41_dialog_content = "Kepala monyet rusak, dan tidak ada pengganti yang cocok di pesawat.",
  ui_story_5038_50380701_42_dialog_content = "Untuk menyembuhkan penyakit, saya harus melaut.",
  ui_story_5038_50380701_43_dialog_content = "Laut?? Anda pikir Anda akan menemukan sesuatu di luar sana ketika Anda bahkan tidak dapat menemukannya?",
  ui_story_5038_50380701_44_dialog_content = "Saya tidak tahu apakah Anda menyadarinya, tetapi ada banyak hal yang mengambang di sekitar sini.",
  ui_story_5038_50380701_45_dialog_content = "Sisa-sisa ini adalah sisa-sisa kapal masa lalu yang tidak diketahui, hilang di laut entah kapan.",
  ui_story_5038_50380701_46_dialog_content = "Jika saya dapat menemukan \"kepala monyet\" lain dari salah satu kapal ini, tentunya itu akan menyelesaikan masalah Shadowind.",
  ui_story_5038_50380701_47_dialog_content = "Kami akan bergerak lebih cepat setelah kami dapat mengangkat layar! Kita bisa khawatir tentang \"telinga kelinci\" itu!",
  ui_story_5038_50380701_48_dialog_content = "Anda ada benarnya, tetapi apakah ini benar-benar layak?",
  ui_story_5038_50380701_49_dialog_content = "Ini seperti mencari jarum di tumpukan jerami di lautan.",
  ui_story_5038_50380701_50_dialog_content = "Itu layak jika saya katakan itu, PlayerName. Lagipula, akulah yang bermain di sini.",
  ui_story_5038_50380701_51_dialog_content = "-ku <color=#FFB400>sobat bahari</color> akan memberi saya tanda dan sinyal.",
  ui_story_5038_50380701_52_dialog_content = "Apakah kamu nyata?",
  ui_story_5038_50380701_53_dialog_content = "Tentu saja. Saya sering berbicara dengan mereka ketika saya berada di laut.",
  ui_story_5038_50380701_54_dialog_content = "Jika saya meminta bantuan, mereka akan memberikannya.",
  ui_story_5038_50380701_55_dialog_content = "Termasuk membantu Anda menemukan \"kepala monyet\" kapal lain?",
  ui_story_5038_50380701_56_dialog_content = "Tapi... bagaimana mereka tahu seperti apa benda itu?",
  ui_story_5038_50380701_57_dialog_content = "Jangan khawatir tentang itu. Saya bisa menggambarkannya kepada mereka.",
  ui_story_5038_50380701_58_dialog_content = "Bagaimanapun, terima kasih telah membantu, PlayerName! Saya bisa mengambilnya dari sini!",
  ui_story_5038_50380701_59_dialog_content = "Aku masih sedikit khawatir. Aku akan mengawasimu melalui telepati.",
  ui_story_5038_50380701_60_dialog_content = "Jika Anda mengalami masalah, sebaiknya beri tahu saya melalui tautan kami, mengerti?",
  ui_story_5038_50380701_61_dialog_content = "Baiklah baiklah. Bertahanlah dan tunggu kabar baik saya!",
  ui_story_5038_50380701_62_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50380701_63_dialog_content = "Yaaaaa!!!",
  ui_story_5038_50380701_64_dialog_content = "Apa? Apa itu?! Liqing!",
  ui_story_5038_50380701_65_option_content = "Force Boost!",
  ui_story_5038_50380701_66_dialog_content = "(Begitu banyak air! Terlalu banyak air! Air, air, di mana-mana...!)",
  ui_story_5038_50380701_67_dialog_content = "Wah... PlayerName! Ada, seperti, air DI MANA SAJA!",
  ui_story_5038_50380701_68_dialog_content = "Anda berada di laut, apa yang Anda harapkan ?!",
  ui_story_5038_50380701_69_dialog_content = "Tunggu, kamu tidak bilang kamu takut air, kan?",
  ui_story_5038_50380701_70_dialog_content = "Nah, duh! Kucing yang tidak menyukai air bukanlah berita!",
  ui_story_5038_50380701_71_dialog_content = "(Oh, Liqing yang malang gemetar hebat. Kecelakaan enam bulan lalu pasti sangat melukainya.)",
  ui_story_5038_50380701_72_dialog_content = "K-kembali, cepat! Cobalah untuk tidak bergerak terlalu banyak, dan aku akan mengangkatmu dan perahunya kembali...",
  ui_story_5038_50380701_73_dialog_content = "Huff... Huff",
  ui_story_5038_50380701_74_dialog_content = "Meong...",
  ui_story_5038_50380701_75_dialog_content = "Apa sih yang kamu pikirkan? Mengapa Anda bersikeras untuk turun ketika Anda begitu takut pada air?",
  ui_story_5038_50380701_76_dialog_content = "Saya pikir saya bisa melakukannya sendiri ...",
  ui_story_5038_50380701_77_dialog_content = "Um... Bagaimanapun, PlayerName, sekarang kita di sini, saya khawatir saya harus meminta bantuan.",
  ui_story_5038_50380701_78_dialog_content = "Biarkan saya menebak: Anda akan baik-baik saja jika saya pergi dengan Anda?",
  ui_story_5038_50380701_79_dialog_content = "Nah, semua orang sibuk memperbaiki kapal. Mari kita cepat tentang hal itu.",
  ui_story_5038_50380701_80_dialog_content = "Oke!",
  ui_story_5038_50380701_81_dialog_content = "(Sebelum keluar, saya mungkin harus menyegarkan ingatan saya tentang protokol keamanan...)",
  ui_story_5038_50380701_82_dialog_content = "Astaga!!",
  ui_story_5038_50380701_83_dialog_content = "Anda pasti bercanda dengan saya...",
  ui_story_5038_50380701_84_dialog_content = "Mereka memilih sekarang, sepanjang waktu, untuk memanjat tali itu?!",
  ui_story_5038_50380702_1_dialog_content = "Dengarkan aku, teman-teman! Saya mencari objek yang terlihat seperti siluet kepala monyet.",
  ui_story_5038_50380702_2_dialog_content = "Sesuatu yang besar, bulat, dan kokoh.",
  ui_story_5038_50380702_3_dialog_content = "Mungkin terjerat dengan beberapa tali.",
  ui_story_5038_50380702_X3_dialog_content = "Jadi, temanmu adalah... ikan ini?",
  ui_story_5038_50380702_4_dialog_content = "Urgh... *Batuk*...",
  ui_story_5038_50380702_5_dialog_content = "Apa kamu baik baik saja? Merasa mual?",
  ui_story_5038_50380702_6_dialog_content = "Buzi mengatakan bahwa dokter tidak boleh merawat diri mereka sendiri. Saya pikir inilah yang dia bicarakan.",
  ui_story_5038_50380702_7_dialog_content = "Dapatkah saya melakukan sesuatu untuk Anda?",
  ui_story_5038_50380702_8_dialog_content = "Karena kamu bertanya... Goresan dagu yang bagus akan bagus—",
  ui_story_5038_50380702_9_dialog_content = "TETAPI! *Uhuk*... Goresan dagu dan lebih banyak gaya Tinytail!",
  ui_story_5038_50380702_10_dialog_content = "Saya bukan hanya seekor kucing lagi, jadi jelas saya tidak akan menyukai hal-hal seperti itu!",
  ui_story_5038_50380702_11_dialog_content = "(Lucunya...)",
  ui_story_5038_50380702_12_dialog_content = "Omong-omong, apakah ada fiendlings dari mana Anda berasal, PlayerName?",
  ui_story_5038_50380702_13_dialog_content = "Yah, aku punya beberapa teman Aurorian yang setengah manusia.",
  ui_story_5038_50380702_14_dialog_content = "Kebanyakan dari mereka adalah keturunan demi-human dan Aurorian, dan mereka cukup langka.",
  ui_story_5038_50380702_15_dialog_content = "Saya mengerti. Kedengarannya sedikit berbeda dengan fiendlings.",
  ui_story_5038_50380702_16_dialog_content = "Kau tahu Tinytail adalah kakakku?",
  ui_story_5038_50380702_17_dialog_content = "K-Kamu apa...?!",
  ui_story_5038_50380702_18_dialog_content = "Itu sebabnya Tianxian selalu memanggilmu kitty?? Karena kamu sebenarnya adalah satu?",
  ui_story_5038_50380702_19_dialog_content = "I-Itu benar-benar kasar dia memanggilku seperti itu.",
  ui_story_5038_50380702_20_dialog_content = "Tapi kau benar. Di tanah air saya, fiendling adalah hewan yang telah dibudidayakan menjadi Aurorian.",
  ui_story_5038_50380702_21_dialog_content = "Keluarga-keluarga berpengaruh di Longzhou yang mengadvokasi perdamaian sering mengundang orang-orang jahat ke rumah mereka sebagai tamu.",
  ui_story_5038_50380702_22_dialog_content = "Mereka berfungsi seperti pengikut.",
  ui_story_5038_50380702_23_dialog_content = "Itulah sebenarnya bagaimana saya mengenal Lin Guildmaster.",
  ui_story_5038_50380702_24_dialog_content = "Dia tampaknya menjadi orang yang sangat menghargai persahabatan.",
  ui_story_5038_50380702_25_dialog_content = "Ehh... Sejujurnya, saya hampir tidak mengerti sepatah kata pun tentang bisnis yang dicelotehkan oleh orang-orang tua itu.",
  ui_story_5038_50380702_26_dialog_content = "Keluarga Lin mengundang saya ke manor mereka karena mereka ingin saya membantu mereka <color=#FFB400>merawat ikan mereka</color>.",
  ui_story_5038_50380702_27_dialog_content = "Saya tahu semua orang mengira kucing makan ikan, tetapi ikan laut adalah teman saya.",
  ui_story_5038_50380702_28_dialog_content = "Maksud Anda, Anda dapat berkomunikasi dengan ikan ular?",
  ui_story_5038_50380702_29_dialog_content = "Lebih atau kurang. Memang benar, tapi lihatlah malam itu. Saya tidak bisa berbuat apa-apa untuk membantu, di tengah krisis...",
  ui_story_5038_50380702_30_dialog_content = "Oh! Teman akuatik kita telah menjawab.",
  ui_story_5038_50380702_31_dialog_content = "\"Kepala monyet\" tepat di bawah kita, PlayerName!",
  ui_story_5038_50380702_32_dialog_content = "Sungguh?",
  ui_story_5038_50380702_33_dialog_content = "Ya. Mungkin terjerat rumput laut.",
  ui_story_5038_50380702_34_dialog_content = "Tunggu, biarkan aku mengaduk-aduk jaringku...",
  ui_story_5038_50380702_35_dialog_content = "Hei... Ho—",
  ui_story_5038_50380702_36_dialog_content = "Saksikan berikut ini, PlayerName.",
  ui_story_5038_50380702_37_dialog_content = "I-Itu luar biasa!",
  ui_story_5038_50380702_38_dialog_content = "Hampir seperti sihir!",
  ui_story_5038_50380702_39_dialog_content = "Sudah kubilang teman lautku akan datang.",
  ui_story_5038_50380702_40_dialog_content = "Sekarang kami memiliki \"kepala monyet\" baru, kami dapat berkontribusi untuk perbaikan kapal!",
  ui_story_5038_50380702_41_dialog_content = "Yap, meskipun kita harus kembali dulu!",
  ui_story_5038_50380702_42_dialog_content = "Ini pasti akan mengangkat semangat semua orang di kapal.",
  ui_story_5038_50380702_43_dialog_content = "Baiklah.",
  ui_story_5038_50380702_44_dialog_content = "(Aku ingin tahu bagaimana kabarnya...)",
  ui_story_5038_50380702_45_dialog_content = "<color=#e8d9bb>Di Dek</color>",
  ui_story_5038_50380702_46_dialog_content = "Hai! Liqing dan PlayerName kembali!",
  ui_story_5038_50380702_47_dialog_content = "Sudah kubilang mereka berdua akan baik-baik saja.",
  ui_story_5038_50380702_48_dialog_content = "Hehe, pasti kamu pernah. Tapi Anda juga sepertinya tidak nafsu makan sebelumnya.",
  ui_story_5038_50380702_49_dialog_content = "PlayerName, Liqing! Apa yang Anda lakukan sangat berisiko!",
  ui_story_5038_50380702_50_dialog_content = "Apakah Anda bahkan memikirkan konsekuensinya sebelum Anda pergi?",
  ui_story_5038_50380702_51_dialog_content = "Lihat, Kapten.",
  ui_story_5038_50380702_52_dialog_content = "…!",
  ui_story_5038_50380702_53_dialog_content = "Sebuah katrol?!",
  ui_story_5038_50380702_54_dialog_content = "Ini jelas terendam dalam air laut, tetapi harus bisa diservis setelah dibersihkan dengan baik.",
  ui_story_5038_50380702_55_dialog_content = "Di mana Anda menemukannya?",
  ui_story_5038_50380702_56_dialog_content = "Di laut!",
  ui_story_5038_50380702_57_dialog_content = "Apakah kalian berdua menyelinap dari kapal?",
  ui_story_5038_50380702_58_dialog_content = "Itu adalah hal yang sangat berbahaya untuk dilakukan. Dengan semua orang asyik dengan pekerjaan mereka, apa yang akan terjadi jika Anda mendapat masalah? Tidak ada yang bisa membantu.",
  ui_story_5038_50380702_59_dialog_content = "Tapi kita baik-baik saja, bukan? Tidak ada hal buruk yang terjadi sama sekali!",
  ui_story_5038_50380702_60_dialog_content = "Ini mungkin sedikit berisiko, tetapi berakhir dengan baik.",
  ui_story_5038_50380702_61_dialog_content = "Anda mengatakannya sendiri, Yuebai. Perjalanan ini pasti berisiko.",
  ui_story_5038_50380702_62_dialog_content = "Berkat Liqing, kami memiliki katrol \"kepala monyet\". Dia harus dipuji!",
  ui_story_5038_50380702_63_dialog_content = "Kalian...",
  ui_story_5038_50380702_64_dialog_content = "Baik. Saya tidak memungkiri bahwa memiliki ini akan sangat membantu kemajuan perbaikan kapal. Maka untuk itu, saya berterima kasih.",
  ui_story_5038_50380702_65_dialog_content = "Tapi sebaiknya aku tidak menangkapmu menyelinap dari kapal tanpa izin lagi.",
  ui_story_5038_50380702_66_dialog_content = "Dibubarkan. Pergi makan malam.",
  ui_story_5038_50380702_67_dialog_content = "Kemarilah, kalian.",
  ui_story_5038_50380702_68_dialog_content = "Sementara semua orang sibuk, Jiu kembali memasak beberapa masakan tradisional dari kampung halamannya.",
  ui_story_5038_50380702_69_dialog_content = "Nyam! Saya tidak menyadari betapa laparnya saya!",
  ui_story_5038_50380702_70_dialog_content = "Baunya harum, Putri Dantan! Jangan bilang kita makan daging babi rebus?!",
  ui_story_5038_50380702_71_dialog_content = "Indera penciuman yang tajam! Makan siang hari ini memang <color=#FFB400>daging babi rebus</color>!",
  ui_story_5038_50380702_72_dialog_content = "Anda mendapatkan potongan daging yang bagus dan padat dan mengikatnya, memasukkannya ke dalam panci berisi berbagai bumbu, dan membiarkannya mendidih ...",
  ui_story_5038_50380702_73_dialog_content = "Bahan-bahan di kapal mungkin agak terbatas, tapi menurutku rasanya cukup mirip.",
  ui_story_5038_50380702_74_dialog_content = "Pergi dan makan. Saya masih memiliki beberapa pekerjaan yang harus dilakukan.",
  ui_story_5038_50380702_75_dialog_content = "Dengan katrol pengganti, saya seharusnya dapat menyelesaikan perbaikan tiang dengan cukup cepat.",
  ui_story_5038_50380702_76_dialog_content = "Kami akan segera dapat melanjutkan kecepatan normal.",
  ui_story_5038_50380702_77_dialog_content = "Saya dapat membantu!",
  ui_story_5038_50380702_78_dialog_content = "<color=#e8d9bb>Menggeram-</color>",
  ui_story_5038_50380702_79_dialog_content = "Haha... Kedengarannya kau harus pergi bersama mereka dulu.",
  ui_story_5038_50380702_80_dialog_content = "Tidak akan pernah dikatakan bahwa tamu keluarga Lins disuruh bekerja dengan perut kosong.",
  ui_story_5038_50380801_1_dialog_content = "(Kecepatan kapal mungkin sudah kembali normal, tapi keadaan lambung kapal masih sedikit mengkhawatirkan.)",
  ui_story_5038_50380801_2_dialog_content = "(Semua orang bekerja tanpa henti, seolah-olah Shadowind akan tenggelam jika mereka berhenti sejenak.)",
  ui_story_5038_50380801_3_dialog_content = "(Sepertinya kita berpikir bahwa melelahkan diri sendiri adalah penangkal rasa khawatir.)",
  ui_story_5038_50380801_4_dialog_content = "Berlayar sedikit lagi ke pelabuhan, kru. Anginnya berubah.",
  ui_story_5038_50380801_5_dialog_content = "Iya!",
  ui_story_5038_50380801_6_dialog_content = "Bagaimana tampilan ruang kargo?",
  ui_story_5038_50380801_7_dialog_content = "Masih bocor, jadi kami harus terus mengirim seseorang untuk mengeluarkan air.",
  ui_story_5038_50380801_8_dialog_content = "Untungnya tidak bertambah parah, dan kami masih bisa menanganinya.",
  ui_story_5038_50380801_9_dialog_content = "Dipahami. Buatlah jadwal dan bergiliran untuk beristirahat.",
  ui_story_5038_50380801_10_dialog_content = "Kami tidak tahu berapa lama keadaan ini akan berlangsung, jadi kami perlu mengatur kecepatan diri sendiri.",
  ui_story_5038_50380801_11_dialog_content = "Iya!",
  ui_story_5038_50380801_12_dialog_content = "Saya harap kursus kami bertahan. Aku pergi ke jembatan untuk memeriksa sesuatu.",
  ui_story_5038_50380801_13_dialog_content = "(Yuebai terus bergerak. Dia bahkan tidak berhenti ketika berbicara.)",
  ui_story_5038_50380801_14_dialog_content = "(Dia memiliki lebih banyak hal untuk dipikirkan daripada kita semua, dan itu jelas membuatnya lebih tertekan.)",
  ui_story_5038_50380801_15_dialog_content = "(Mungkin langkah kakinya bisa menyumbat beberapa lubang di The Shadowind.)",
  ui_story_5038_50380801_16_dialog_content = "Penampakan lain...",
  ui_story_5038_50380801_17_dialog_content = "Berapa jumlahnya sekarang, Jiu?",
  ui_story_5038_50380801_18_dialog_content = "42, Yang Mulia.",
  ui_story_5038_50380801_19_dialog_content = "Sudah banyak.",
  ui_story_5038_50380801_20_dialog_content = "Mereka terus datang dari arah yang kita tuju... Ini benar-benar mengkhawatirkan.",
  ui_story_5038_50380801_21_dialog_content = "(Banyak kayu apung telah terlihat sejak pagi.)",
  ui_story_5038_50380801_22_dialog_content = "(Kepala monyet kemarin hanyalah puncak gunung es. Sekarang kita melihat sisa-sisa bangkai kapal yang tak terhitung jumlahnya, semuanya hilang di laut di sini.)",
  ui_story_5038_50380801_23_dialog_content = "(Dantang terus-menerus bersandar di sisi kapal, menatap ke laut, menghitung setiap potongan kayu apung.)",
  ui_story_5038_50380801_24_dialog_content = "(Hanya kami yang menjadi saksi sisa-sisa orang-orang yang menyerah pada ombak ini.)",
  ui_story_5038_50380801_25_dialog_content = "Apa yang mengkhawatirkan? Saya pikir itu pertanda baik.",
  ui_story_5038_50380801_26_dialog_content = "Jika ada reruntuhan di jalur kami, itu berarti kami berada di jalur yang benar.",
  ui_story_5038_50380801_27_dialog_content = "Tidakkah menurut Anda lautan yang benar-benar sepi dan kosong jauh lebih menakutkan?",
  ui_story_5038_50380801_28_dialog_content = "(Liqing berjalan melewatinya, ikan kering menggantung dari mulutnya.)",
  ui_story_5038_50380801_29_dialog_content = "(Dia telah membantu, tetapi tampaknya selalu memiliki sikap acuh tak acuh.)",
  ui_story_5038_50380801_30_dialog_content = "(Mungkin dia mencoba membuat permainan dari semua pekerjaannya.)",
  ui_story_5038_50380801_31_dialog_content = "Ahhh... aku lelah.",
  ui_story_5038_50380801_32_dialog_content = "Air di ruang kargo terus mengalir, tidak peduli seberapa banyak Anda menjamin.",
  ui_story_5038_50380801_33_dialog_content = "Memutuskan untuk datang bergabung dengan kami, PlayerName?",
  ui_story_5038_50380801_34_dialog_content = "Ya. Saya disuruh istirahat.",
  ui_story_5038_50380801_35_dialog_content = "(Tianxian adalah dirinya yang biasa. Hanya kotak obrolan tanpa henti.)",
  ui_story_5038_50380801_36_dialog_content = "Dan benar sekali. Tidak baik melelahkan diri sendiri.",
  ui_story_5038_50380801_37_dialog_content = "Ketika jaminan hari ini selesai, akan ada lebih banyak besok.",
  ui_story_5038_50380801_38_dialog_content = "Kita harus lebih sabar daripada lautan itu sendiri dalam pelayaran ini.",
  ui_story_5038_50380801_39_dialog_content = "Anda tampaknya memiliki pepatah untuk semua kesempatan.",
  ui_story_5038_50380801_40_dialog_content = "Tentu saja. Saya harus meyakinkan diri sendiri untuk menghadapi hari-hari yang tak berkesudahan ini dengan keseimbangan batin.",
  ui_story_5038_50380801_41_dialog_content = "Tuan Kursi Roda di sana menjadi pilihan terakhir kami, jika dia belum bangun dan bekerja, maka situasinya tidak akan seburuk itu.",
  ui_story_5038_50380801_42_dialog_content = "Jangan salah mengartikan kecacatan dengan kemalasan.",
  ui_story_5038_50380801_43_dialog_content = "Hei, lihat siapa itu! Tuan Zhong!",
  ui_story_5038_50380801_44_dialog_content = "Jarang kami melihat Anda menghirup udara segar di geladak!",
  ui_story_5038_50380801_45_dialog_content = "Tidak perlu memperlakukan saya seperti bangsawan. Saya tidak memiliki kekuatan semacam itu di darat, apalagi di kapal.",
  ui_story_5038_50380801_46_dialog_content = "Anda terlalu rendah hati, Pak. Harimau tanpa giginya tetaplah makhluk yang tangguh, patut dihormati. Apalagi mantan Jenderal Besar.",
  ui_story_5038_50380801_47_dialog_content = "Anda benar-benar ahli dalam membujuk.",
  ui_story_5038_50380801_48_dialog_content = "Sebenarnya, saya punya ide yang mungkin bisa membantu meringankan beberapa kesulitan kita saat ini.",
  ui_story_5038_50380801_49_dialog_content = "Tapi aku butuh bantuanmu untuk membuatnya bekerja.",
  ui_story_5038_50380801_50_dialog_content = "Betulkah? Apa itu?",
  ui_story_5038_50380801_51_dialog_content = "Saya akan dengan senang hati membantu!",
  ui_story_5038_50380801_52_dialog_content = "Seseorang akan merasa terhormat untuk membantu seorang pria yang begitu bijaksana dan berbakat!",
  ui_story_5038_50380801_53_dialog_content = "Ini tidak terlalu sulit. Saya ingin meminta Anda untuk membantu saya mengumpulkan beberapa kayu apung.",
  ui_story_5038_50380801_54_dialog_content = "Kumpulkan kayu apung?",
  ui_story_5038_50380801_55_dialog_content = "Tidak bisakah kita menariknya dengan jaring?",
  ui_story_5038_50380801_56_dialog_content = "Benar? Jika ada satu hal yang kita tidak kekurangan di sini, itu adalah kayu apung.",
  ui_story_5038_50380801_57_dialog_content = "Tidak semua kayu apung bisa digunakan. Harap hanya kumpulkan yang saya tunjukkan.",
  ui_story_5038_50380801_58_dialog_content = "Hah? Bagaimana mereka berbeda?",
  ui_story_5038_50380801_59_dialog_content = "Sudahlah. Lakukan saja apa yang dia katakan untuk saat ini, saya yakin dia tahu apa yang dia bicarakan.",
  ui_story_5038_50380801_60_dialog_content = "Mari kita lihat apakah kita bisa mendapatkan jaring dari salah satu pelaut.",
  ui_story_5038_50380801_61_dialog_content = "Mengangkut!",
  ui_story_5038_50380801_62_dialog_content = "Hampir sampai! Satu tarikan lagi!",
  ui_story_5038_50380801_63_dialog_content = "Aduh!",
  ui_story_5038_50380801_64_dialog_content = "<color=#e8d9bb>Pukul, buk!</color>",
  ui_story_5038_50380801_65_dialog_content = "Fiuh! Kesuksesan!",
  ui_story_5038_50380801_66_dialog_content = "Sukses, ekorku.",
  ui_story_5038_50380801_67_dialog_content = "Saya bahkan tidak melihat setengah ikan di sana. Anda menyebut menangkap papan sukses?",
  ui_story_5038_50380801_68_dialog_content = "Liqing? Tidak, ini bukan untuk—",
  ui_story_5038_50380801_69_dialog_content = "Saya meminta mereka untuk membantu saya mengumpulkannya.",
  ui_story_5038_50380801_70_dialog_content = "Hah? Itu agak aneh. Apa istimewanya sepotong kayu?",
  ui_story_5038_50380801_71_dialog_content = "Lihatlah lebih dekat potongan yang mereka kumpulkan. Itu bukan papan biasa.",
  ui_story_5038_50380801_72_dialog_content = "Di kapal, potongan ini umumnya dikenal sebagai \"telinga kelinci\".",
  ui_story_5038_50380801_73_dialog_content = "Ah! Sekarang Anda menyebutkannya, itu benar-benar menyerupai telinga kelinci.",
  ui_story_5038_50380801_74_dialog_content = "Itu masuk akal! Tuan Zhong, Anda benar-benar berhasil!",
  ui_story_5038_50380801_75_dialog_content = "\"Telinga kelinci\" adalah yang terakhir dari tiga hal yang saya hitung dengan heksagram.",
  ui_story_5038_50380801_76_dialog_content = "Untuk apa itu digunakan?",
  ui_story_5038_50380801_77_dialog_content = "Itu adalah papan khusus yang ditempel di bagian luar. Biasanya hanya ada dua per kapal.",
  ui_story_5038_50380801_78_dialog_content = "Itu dibuat lebih cermat daripada papan lainnya, dan tahan air.",
  ui_story_5038_50380801_79_dialog_content = "Oleh karena itu mengapa saya meminta untuk dikumpulkan.",
  ui_story_5038_50380801_80_dialog_content = "Anda... tertarik karena tahan air?",
  ui_story_5038_50380801_81_dialog_content = "Benar.",
  ui_story_5038_50380801_82_dialog_content = "Anda mungkin bertanya-tanya mengapa. Sesuatu yang kedap air memastikan bahwa air tidak mengalir ke tempat yang tidak semestinya.",
  ui_story_5038_50380801_83_dialog_content = "Menahan air...",
  ui_story_5038_50380801_84_dialog_content = "Ah! Saya mengerti! Ini untuk ruang kargo, kan?",
  ui_story_5038_50380801_85_dialog_content = "Anda berencana menggunakan papan ini untuk menghentikan kebocoran!",
  ui_story_5038_50380801_86_dialog_content = "Sangat cerdas, teman muda.",
  ui_story_5038_50380801_87_dialog_content = "Paku saja \"telinga kelinci\" ke kebocoran.",
  ui_story_5038_50380801_88_dialog_content = "Ini hanya sementara, tetapi itu akan membantu menghilangkan beberapa tekanan, jadi kita semua tidak kewalahan.",
  ui_story_5038_50380801_89_dialog_content = "Hebat! Seperti membuat bunga palsu ke pohon asli.",
  ui_story_5038_50380801_90_dialog_content = "Jadi ITULAH yang dimaksud dengan tongkat keberuntungan!",
  ui_story_5038_50380801_91_dialog_content = "Kedengarannya seperti rencana yang bagus!",
  ui_story_5038_50380801_92_dialog_content = "Jika itu benar-benar berfungsi untuk menghentikan kebocoran, itu akan membebaskan semua orang untuk membantu hal-hal lain.",
  ui_story_5038_50380801_93_dialog_content = "Cepat, mari kita lihat apakah kita bisa menemukan yang lain!",
  ui_story_5038_50380801_94_dialog_content = "Sudah mencari, PlayerName.",
  ui_story_5038_50380801_95_dialog_content = "Lihat ke sana! Salah satu dari papan telinga kelinci itu.",
  ui_story_5038_50380801_96_dialog_content = "Jaring! Buru-buru!",
  ui_story_5038_50380801_97_dialog_content = "Air masih datang?",
  ui_story_5038_50380801_98_dialog_content = "Ya. Kita tidak bisa menyerah, bahkan untuk sedetik pun.",
  ui_story_5038_50380801_99_dialog_content = "Jangan hanya berdiri di sana! Bantuan jaminan.",
  ui_story_5038_50380801_100_dialog_content = "Oh maaf...",
  ui_story_5038_50380801_101_dialog_content = "Hei, bisakah seseorang membantuku?",
  ui_story_5038_50380801_102_dialog_content = "Hah? Bukan Liqing?",
  ui_story_5038_50380801_103_dialog_content = "Cepat, ini terlalu berat!",
  ui_story_5038_50380801_104_dialog_content = "Yang akan datang! Apa yang kamu...",
  ui_story_5038_50380801_105_dialog_content = "<color=#e8d9bb>Pukul, buk!</color>",
  ui_story_5038_50380801_106_dialog_content = "Eh?!",
  ui_story_5038_50380801_107_dialog_content = "Aduh! Itu terlalu berat.",
  ui_story_5038_50380801_108_dialog_content = "Tapi mendapatkannya di sini dianggap sebagai misi yang tercapai.",
  ui_story_5038_50380801_109_dialog_content = "Apa yang kamu lakukan di sini dengan papan, Liqing?",
  ui_story_5038_50380801_110_dialog_content = "Itu semua salah Zhong Xu karena membuatku bekerja.",
  ui_story_5038_50380801_111_dialog_content = "Dia mengatakan papan ini bisa menutup kebocoran.",
  ui_story_5038_50380801_112_dialog_content = "Apakah Anda mengeruknya dari laut?",
  ui_story_5038_50380801_113_dialog_content = "Mungkin terlalu terkikis untuk berguna.",
  ui_story_5038_50380801_114_dialog_content = "Saya rasa tidak, rasanya cukup berat bagi saya.",
  ui_story_5038_50380801_115_dialog_content = "Silakan, rasakan.",
  ui_story_5038_50380801_116_dialog_content = "Saya pikir itu adalah kurangnya kekuatan Anda yang menjadi masalah.",
  ui_story_5038_50380801_117_dialog_content = "Biar kulihat...",
  ui_story_5038_50380801_118_dialog_content = "Tunggu sebentar, ini telinga kelinci!",
  ui_story_5038_50380801_119_dialog_content = "Ah-ha, terkesan sekarang?",
  ui_story_5038_50380801_120_dialog_content = "Telinga kelinci... Kau tahu, ini mungkin berhasil.",
  ui_story_5038_50380801_121_dialog_content = "Beri aku palu!",
  ui_story_5038_50380801_122_dialog_content = "Tiga dua satu!",
  ui_story_5038_50380801_123_dialog_content = "<color=#e8d9bb>Pukul, buk!</color>",
  ui_story_5038_50380801_124_dialog_content = "Yay, satu lagi!",
  ui_story_5038_50380801_125_dialog_content = "Mudah sekali.",
  ui_story_5038_50380801_126_dialog_content = "K-Kamu tidak bilang? Aku perlu mengatur napas...",
  ui_story_5038_50380801_127_dialog_content = "Sedang apa kau?",
  ui_story_5038_50380801_128_dialog_content = "Kami mengumpulkan kayu apung dari laut, Kapten.",
  ui_story_5038_50380801_129_dialog_content = "Lord Zhong berkata bahwa bufet dari kapal yang tenggelam ini mungkin bisa membantu menambal kebocoran.",
  ui_story_5038_50380801_130_dialog_content = "Telinga kelinci...",
  ui_story_5038_50380801_131_dialog_content = "Kita berhasil! Telinga kelinci menutup kebocoran!",
  ui_story_5038_50380801_132_dialog_content = "Liqing kembali! Jadi itu benar-benar berhasil?",
  ui_story_5038_50380801_133_dialog_content = "Ya. Kami menggunakan telinga kelinci yang baru kami temukan untuk menutup kebocoran.",
  ui_story_5038_50380801_134_dialog_content = "Tapi masih banyak lagi kebocoran di lambung kapal dan kru membutuhkan lebih banyak telinga kelinci.",
  ui_story_5038_50380801_135_dialog_content = "Jangan hanya berdiri di sana, orang-orang. Dapatkan lebih banyak lagi!",
  ui_story_5038_50380801_136_dialog_content = "Oke, oke, aku akan pergi sekarang ...",
  ui_story_5038_50380801_137_dialog_content = "Tolong, jangan repot-repot dengan ini.",
  ui_story_5038_50380801_138_dialog_content = "Karena berhasil, saya akan mengirim pekerja kelasi untuk memulihkan telinga kelinci.",
  ui_story_5038_50380801_139_dialog_content = "Tidak ada tamu di Shadowind yang harus bekerja keras.",
  ui_story_5038_50380801_140_dialog_content = "Oke, tarik!",
  ui_story_5038_50380801_141_dialog_content = "Hei-ya!",
  ui_story_5038_50380801_142_dialog_content = "<color=#e8d9bb>Pukul, buk!</color>",
  ui_story_5038_50380801_143_dialog_content = "Punya satu di sini!",
  ui_story_5038_50380801_144_dialog_content = "<color=#e8d9bb>Pukul, buk!</color>",
  ui_story_5038_50380801_145_dialog_content = "Dapatkan ini di sana!",
  ui_story_5038_50380801_146_dialog_content = "Kami kehabisan paku, saya datang untuk mendapatkan lebih banyak.",
  ui_story_5038_50380801_147_dialog_content = "Mudah di sana, satu per satu!",
  ui_story_5038_50380801_148_dialog_content = "Pekerjaan menjadi jauh lebih efisien setelah semua orang mulai membantu.",
  ui_story_5038_50380801_149_dialog_content = "Saya tidak bisa menghitung berapa banyak papan yang telah mereka kumpulkan.",
  ui_story_5038_50380801_150_dialog_content = "Sepertinya kita bisa memperbaiki lambung bawah hari ini.",
  ui_story_5038_50380801_151_dialog_content = "Hei, telinga kelinci ini...",
  ui_story_5038_50380801_152_dialog_content = "Ayo lihat ini, Liu.",
  ui_story_5038_50380801_153_dialog_content = "Apa, apakah ada masalah dengan itu?",
  ui_story_5038_50380801_154_dialog_content = "Tidak. Sepertinya tidak asing.",
  ui_story_5038_50380801_155_dialog_content = "Kau tahu, sekarang setelah kau menyebutkannya...",
  ui_story_5038_50380801_156_dialog_content = "Bukankah ini dari perahu nelayan Liu Ge?",
  ui_story_5038_50380801_157_dialog_content = "Ya. Dia pergi pada suatu hari di musim semi untuk menangkap ikan di laut dan tidak pernah terdengar kabarnya lagi.",
  ui_story_5038_50380801_158_dialog_content = "Saya tidak berharap untuk melihat ini di sini ...",
  ui_story_5038_50380801_159_dialog_content = "Mereka... mengenali reruntuhannya?",
  ui_story_5038_50380801_160_dialog_content = "Ya.",
  ui_story_5038_50380801_161_dialog_content = "Dari hanya papan?",
  ui_story_5038_50380801_162_dialog_content = "Telinga kelinci adalah perlengkapan kapal yang sangat istimewa.",
  ui_story_5038_50380801_163_dialog_content = "Hanya ada dua di setiap kapal dan di posisi yang agak menonjol.",
  ui_story_5038_50380801_164_dialog_content = "Pemilik kapal suka mengukir pola pada mereka untuk membedakan satu kapal dari yang lain.",
  ui_story_5038_50380801_165_dialog_content = "Jadi begitulah cara mereka mengenalinya!",
  ui_story_5038_50380801_166_dialog_content = "Ini adalah praktik umum bagi pelaut Longzhou.",
  ui_story_5038_50380801_167_dialog_content = "Saya perhatikan Anda, Kapten Yuebai, juga mengamati \"telinga kelinci\" yang kami angkat.",
  ui_story_5038_50380801_168_dialog_content = "Anda pasti telah mengidentifikasi lebih banyak kapal ini daripada awak Anda.",
  ui_story_5038_50380801_169_dialog_content = "Ya…",
  ui_story_5038_50380801_170_dialog_content = "Beberapa adalah kapal penumpang yang dilanda badai di musim panas dan tidak pernah kembali.",
  ui_story_5038_50380801_171_dialog_content = "\"Telinga kelinci\" mereka yang mencolok membuat mereka mudah dikenali.",
  ui_story_5038_50380801_172_dialog_content = "Kapal penangkap ikan sangat sedikit, karena nelayan tahu bahaya yang ditimbulkan oleh lautan.",
  ui_story_5038_50380801_173_dialog_content = "Namun mengingat penurunan ekonomi tahun ini, beberapa masih memilih untuk mengambil risiko.",
  ui_story_5038_50380801_174_dialog_content = "Namun, sebagian besar bagian ini berasal dari kapal dagang.",
  ui_story_5038_50380801_175_dialog_content = "Mereka mendambakan kekayaan benua di sisi lain dan mencoba mengikuti Shadowind yang asli.",
  ui_story_5038_50380801_176_dialog_content = "Namun hingga saat ini, Shadowind tetap menjadi satu-satunya kapal yang melintasi dua daratan dengan aman.",
  ui_story_5038_50380801_177_dialog_content = "Aah…",
  ui_story_5038_50380801_178_dialog_content = "Saya baru menyadari gawatnya situasi.",
  ui_story_5038_50380801_179_dialog_content = "Hanya ada dua \"telinga kelinci\" di kapal.",
  ui_story_5038_50380801_180_dialog_content = "Dengan kata lain, untuk setiap dua telinga kelinci yang kami temukan, ada satu lagi kapal yang tenggelam.",
  ui_story_5038_50380801_181_dialog_content = "Mereka yang dikenali memicu serangan kenangan.",
  ui_story_5038_50380801_182_dialog_content = "Mereka yang bukan hanya umpan untuk angka.",
  ui_story_5038_50380801_183_dialog_content = "Dan kami sudah mengeruk begitu banyak telinga kelinci...",
  ui_story_5038_50380801_184_dialog_content = "Inilah yang kami warisi saat mengarungi lautan.",
  ui_story_5038_50380801_185_dialog_content = "Laut tidak menyayangkan siapa pun. Kami membangun berdasarkan pengalaman mereka yang berlayar sebelumnya.",
  ui_story_5038_50380801_186_dialog_content = "Perbaikan hampir selesai.",
  ui_story_5038_50380801_187_dialog_content = "Kapal dagang, perahu nelayan, yang ini juga kapal dagang...",
  ui_story_5038_50380801_188_dialog_content = "Sebuah kapal dagang, kapal dagang lain ...",
  ui_story_5038_50380801_189_dialog_content = "Apa yang kamu tulis, Dantang?",
  ui_story_5038_50380801_190_dialog_content = "Oh, saya sedang memilah asal usul telinga kelinci ini.",
  ui_story_5038_50380801_191_dialog_content = "Kapten berkata kita harus melaporkan mereka saat kita kembali ke Longzhou.",
  ui_story_5038_50380801_192_dialog_content = "Oh, begitu…",
  ui_story_5038_50380801_193_dialog_content = "Saya selesai menghitung semua yang ada di palka. Apakah ada yang baru?",
  ui_story_5038_50380801_194_dialog_content = "Tidak. Kami baru saja berlayar keluar dari area yang penuh dengan kayu apung.",
  ui_story_5038_50380801_195_dialog_content = "Plus, apa yang kita miliki harus cukup.",
  ui_story_5038_50380801_196_dialog_content = "Pegangannya hampir diperbaiki. Semua orang hanya membungkus hal-hal sekarang.",
  ui_story_5038_50380801_197_dialog_content = "Itu keren. Saya kira saya bisa melakukan hal yang sama.",
  ui_story_5038_50380801_198_dialog_content = "Sayang sekali saya tidak menemukan petunjuk...",
  ui_story_5038_50380801_199_dialog_content = "Memimpin?",
  ui_story_5038_50380801_200_dialog_content = "Ya, saya akan mencari petunjuk tentang The Compass.",
  ui_story_5038_50380801_201_dialog_content = "Banyak dari kapal yang tenggelam ini berlayar dengan armada yang sama dengan Shadowind asli.",
  ui_story_5038_50380801_202_dialog_content = "Karena mereka semua tenggelam, saya pikir \"telinga kelinci\" Shadowind tua bisa diangkat ke atas di beberapa titik.",
  ui_story_5038_50380801_203_dialog_content = "Kecuali itu tidak sesederhana yang saya kira.",
  ui_story_5038_50380801_204_dialog_content = "Itu masuk akal. Petunjuk keberadaan Shadowind tua mungkin hanya terletak di antara reruntuhan.",
  ui_story_5038_50380801_205_dialog_content = "Kita harus melakukan pencarian menyeluruh karena Kompas sangat penting.",
  ui_story_5038_50380801_206_dialog_content = "Haruskah kita berbicara dengan kapten?",
  ui_story_5038_50380801_207_dialog_content = "Tapi setelah dipikir-pikir, Zhong Xu tampaknya tidak terlalu peduli dengan telinga kelinci.",
  ui_story_5038_50380801_208_dialog_content = "Mungkin dia yakin tak satu pun dari mereka yang berasal dari Shadowind.",
  ui_story_5038_50380801_209_dialog_content = "Bagaimana dia bisa begitu yakin?",
  ui_story_5038_50380801_210_dialog_content = "Mungkinkah mereka memiliki bentuk yang unik, mudah dikenali dari kejauhan?",
  ui_story_5038_50380801_211_dialog_content = "Kedengarannya agak hiperbolik.",
  ui_story_5038_50380801_212_dialog_content = "Tidak ada yang bisa melihat sesuatu sekecil itu dari jarak jauh di laut.",
  ui_story_5038_50380801_213_dialog_content = "Tunggu sebentar, bagaimana jika Shadowind tua tidak memiliki telinga kelinci?",
  ui_story_5038_50380801_214_dialog_content = "Tidak, meskipun tidak, bagian-bagiannya yang lain seharusnya masih berada di antara reruntuhan.",
  ui_story_5038_50380801_215_dialog_content = "Tapi Zhong Xu sama sekali tidak tertarik pada reruntuhan mana pun ...",
  ui_story_5038_50380801_216_dialog_content = "Apa mungkin...",
  ui_story_5038_50380801_217_dialog_content = "Wajar jika tidak menemukan sisa-sisa Shadowind lama!",
  ui_story_5038_50380801_218_dialog_content = "Itu tidak pernah menjadi reruntuhan sejak awal.",
  ui_story_5038_50380801_219_dialog_content = "Apa... Dari mana asalmu, Liqing?!",
  ui_story_5038_50380801_220_dialog_content = "Itu tidak merusak ...",
  ui_story_5038_50380801_221_dialog_content = "Kapal yang hilang dan bangkai kapal adalah dua hal yang berbeda.",
  ui_story_5038_50380801_222_dialog_content = "Ada Kompas di dalamnya untuk menjaganya tetap aman, jadi bagaimana bisa tenggelam?",
  ui_story_5038_50380801_223_dialog_content = "Kompas sekuat itu?",
  ui_story_5038_50380801_224_dialog_content = "Tentu saja. Kalau tidak, Anda tidak akan memiliki begitu banyak orang yang mengejarnya.",
  ui_story_5038_50380801_225_dialog_content = "Lagi pula, sekarang bukan waktunya untuk membahas ini.",
  ui_story_5038_50380801_226_dialog_content = "Makan malam akan segera dimulai. Semua orang menunggumu.",
  ui_story_5038_50380801_227_dialog_content = "Ikuti aku.",
  ui_story_5038_50380801_228_dialog_content = "Setiap orang? Maksudmu semua orang di seluruh kapal?",
  ui_story_5038_50380801_229_dialog_content = "Ya. Kapal sudah diperbaiki, jadi kita semua mendapatkan momen langka untuk sekali ini.",
  ui_story_5038_50380801_230_dialog_content = "Jangan menahan kami. Bahkan lelaki tua Zhong Xu datang.",
  ui_story_5038_50380801_231_dialog_content = "Cepatlah!",
  ui_story_5038_50380801_232_dialog_content = "Itu dia, akhirnya!",
  ui_story_5038_50380801_233_dialog_content = "Apakah aroma makanan akhirnya memikat Anda?",
  ui_story_5038_50380801_234_dialog_content = "Ambil tempat dudukmu di sini!",
  ui_story_5038_50380801_235_dialog_content = "Wah, meriah sekali di sini!",
  ui_story_5038_50380801_236_dialog_content = "Wow, baunya enak!",
  ui_story_5038_50380801_237_dialog_content = "Tentu saja. Mereka habis-habisan di dapur.",
  ui_story_5038_50380801_238_dialog_content = "Sekarang inilah yang Anda sebut pesta perayaan!",
  ui_story_5038_50380801_239_dialog_content = "Pesta perayaan?",
  ui_story_5038_50380801_240_dialog_content = "Ya, merayakan kami memperbaiki Shadowind dan melanjutkan perjalanan.",
  ui_story_5038_50380801_241_dialog_content = "Tapi tunggu, aku seharusnya tidak mencuri kata-kata dari kapten sekarang. Kapten, lanjutkan!",
  ui_story_5038_50380801_242_dialog_content = "A-aku?",
  ui_story_5038_50380801_243_dialog_content = "Maaf, tapi saya bukan orang yang suka kata-kata.",
  ui_story_5038_50380801_244_dialog_content = "Semuanya... nikmati saja pestanya, kurasa.",
  ui_story_5038_50380801_245_dialog_content = "Jangan ragu untuk meminta hidangan apa pun yang Anda inginkan. Selama kami memilikinya, Anda akan mendapatkannya.",
  ui_story_5038_50380801_246_dialog_content = "Betulkah? Kalau begitu, ham yang diawetkan di dapur untukku!",
  ui_story_5038_50380801_247_dialog_content = "Aku muak makan ikan setiap hari!",
  ui_story_5038_50380801_248_dialog_content = "Hei, ada apa dengan ikan?",
  ui_story_5038_50380801_249_dialog_content = "Saya akan mengambil semuanya jika Anda tidak menginginkannya!",
  ui_story_5038_50380801_250_dialog_content = "Anda cukup jauh dari orang lain, Tuan Zhong.",
  ui_story_5038_50380801_251_dialog_content = "Haruskah aku membawakanmu makanan?",
  ui_story_5038_50380801_252_dialog_content = "Ya, benar. Tempat sepi ini cocok untukku.",
  ui_story_5038_50380801_253_dialog_content = "Anda tidak suka pertemuan yang berisik?",
  ui_story_5038_50380801_254_dialog_content = "Justru sebaliknya, saya lakukan.",
  ui_story_5038_50380801_255_dialog_content = "Ketika saya menjadi pejabat, saya menghadiri acara sosial saya.",
  ui_story_5038_50380801_256_dialog_content = "Baru setelah saya pensiun saya menyadari bahwa jauh lebih baik untuk mengamati dari jauh.",
  ui_story_5038_50380801_257_dialog_content = "Saya menikmati mengambil semua emosi lebih dari yang benar-benar bersenang-senang di dalamnya.",
  ui_story_5038_50380801_258_dialog_content = "Saya melihat ... Itu sangat mendalam ...",
  ui_story_5038_50380801_259_dialog_content = "Ini dia, Jiu!",
  ui_story_5038_50380801_260_dialog_content = "Anda mengagetkan saya, Nona...",
  ui_story_5038_50380801_261_dialog_content = "Para kru di sana ingin menari. Apakah kamu datang?",
  ui_story_5038_50380801_262_dialog_content = "Anda adalah penari terbaik yang saya tahu!",
  ui_story_5038_50380801_263_dialog_content = "Aku tersanjung, tapi aku tidak sebaik itu...",
  ui_story_5038_50380801_264_dialog_content = "Kalau begitu mari kita ambil sesuatu untuk dimakan! Mereka menyajikan hidangan baru sekarang!",
  ui_story_5038_50380801_265_dialog_content = "Makanan enak akan cepat habis!",
  ui_story_5038_50380801_266_dialog_content = "Anda tampak sangat bersemangat!",
  ui_story_5038_50380801_267_dialog_content = "Karena aku sangat bahagia!",
  ui_story_5038_50380801_268_dialog_content = "Kami mengangkat layar di sana sendiri, dan memperbaiki kapal di bawah kaki kami dengan tangan kami sendiri.",
  ui_story_5038_50380801_269_dialog_content = "Bukankah itu sangat menakjubkan?",
  ui_story_5038_50380801_270_dialog_content = "Kami memulai perjalanan ini, dan semuanya berakhir di perahu yang sama.",
  ui_story_5038_50380801_271_dialog_content = "Ya kamu benar. Shadowind mulai terasa seperti rumah sendiri.",
  ui_story_5038_50380801_272_dialog_content = "Lihat, itu adalah sesuatu yang hanya dirasakan oleh penumpang seperti kami.",
  ui_story_5038_50380801_273_dialog_content = "Tentu saja, ada jenis kebahagiaan lain yang bisa dinikmati semua orang.",
  ui_story_5038_50380801_274_dialog_content = "Periksa mereka.",
  ui_story_5038_50380801_275_dialog_content = "Akhirnya, setelah bekerja begitu lama!",
  ui_story_5038_50380801_276_dialog_content = "Kami akhirnya akan tidur nyenyak malam ini.",
  ui_story_5038_50380801_277_dialog_content = "Ya, kita tidak perlu memperbaiki tiang atau air jaminan lagi.",
  ui_story_5038_50380801_278_dialog_content = "Akhirnya kami akan kembali ke Longzhou.",
  ui_story_5038_50380901_1_dialog_content = "<color=#e8d9bb>5 Hari Kemudian...</color>",
  ui_story_5038_50380901_2_dialog_content = "Semuanya berfungsi dan bekerja dengan baik, Kapten.",
  ui_story_5038_50380901_3_dialog_content = "Masih ada sedikit kebocoran di palka, tapi tidak bertambah parah dalam semalam.",
  ui_story_5038_50380901_4_dialog_content = "Terima kasih atas laporannya.",
  ui_story_5038_50380901_5_dialog_content = "Apakah bekal yang lembab sudah dibuang?",
  ui_story_5038_50380901_6_dialog_content = "Ya. Kami membuang yang benar-benar rusak, dan menjemur yang dalam kondisi lumayan di geladak.",
  ui_story_5038_50380901_7_dialog_content = "Namun, sekarang kami tidak punya banyak makanan tersisa.",
  ui_story_5038_50380901_8_dialog_content = "Makanan...",
  ui_story_5038_50380901_9_dialog_content = "Berapa banyak air bersih yang tersisa?",
  ui_story_5038_50380901_10_dialog_content = "Cukup untuk sekitar setengah bulan.",
  ui_story_5038_50380901_11_dialog_content = "Seberapa jauh kita dari pantai, Kapten?",
  ui_story_5038_50380901_12_dialog_content = "Maaf, tapi itu masih belum ditentukan sekarang.",
  ui_story_5038_50380901_13_dialog_content = "Grafik tidak lengkap untuk wilayah ini, dan kami mengalami serangan.",
  ui_story_5038_50380901_14_dialog_content = "Kami sendirian di wilayah yang belum dipetakan.",
  ui_story_5038_50380901_15_dialog_content = "Beri tahu semua orang untuk menyimpan persediaan kami untuk saat ini dan mencoba memancing lebih sering.",
  ui_story_5038_50380901_16_dialog_content = "Sama dengan air tawar. Gunakan dengan bijaksana di luar konsumsi normal.",
  ui_story_5038_50380901_17_dialog_content = "Kau diberhentikan.",
  ui_story_5038_50380901_18_dialog_content = "Ya, Kapten.",
  ui_story_5038_50380901_19_dialog_content = "<color=#e8d9bb>5 Hari Lagi Kemudian</color>",
  ui_story_5038_50380901_20_dialog_content = "Makan siang cukup langka lagi.",
  ui_story_5038_50380901_21_dialog_content = "Ya, tapi tidak ada yang bisa kita lakukan.",
  ui_story_5038_50380901_22_dialog_content = "Apa kamu sudah kenyang?",
  ui_story_5038_50380901_23_dialog_content = "Bahkan tidak dekat. Saya bahkan hampir tidak mendapat gigitan.",
  ui_story_5038_50380901_24_dialog_content = "Saya memberikan porsi saya ke Tinytail.",
  ui_story_5038_50380901_25_dialog_content = "Apa? Anda tidak bisa melakukan itu, Anda masih tumbuh!",
  ui_story_5038_50380901_26_dialog_content = "I-Hanya itu yang kau khawatirkan?!",
  ui_story_5038_50380901_27_dialog_content = "Aku akan pergi memeriksa bagaimana keadaan di geladak.",
  ui_story_5038_50380901_28_dialog_content = "Jika Anda beruntung, Anda akan mendapatkan ikan untuk makan malam.",
  ui_story_5038_50380901_29_dialog_content = "Ikan? Sungguh, meong?",
  ui_story_5038_50380901_30_dialog_content = "Jika Anda beruntung.",
  ui_story_5038_50380901_31_dialog_content = "Aku tidak... pandai memancing...",
  ui_story_5038_50380901_32_dialog_content = "Pokoknya... tunggu disini...",
  ui_story_5038_50380901_33_dialog_content = "Anda goyah... Ada apa?",
  ui_story_5038_50380901_34_dialog_content = "Apa? Tidak, saya...",
  ui_story_5038_50380901_35_dialog_content = "Biarkan saya mengambil pulsa Anda.",
  ui_story_5038_50380901_36_dialog_content = "Aku…",
  ui_story_5038_50380901_37_dialog_content = "Kamu sakit.",
  ui_story_5038_50380901_38_dialog_content = "<color=#e8d9bb>5 Hari Lagi Kemudian</color>",
  ui_story_5038_50380901_39_dialog_content = "Berhenti berlarian, Tinytail!",
  ui_story_5038_50380901_40_dialog_content = "Aku tidak ingin melihatmu jatuh ke laut!",
  ui_story_5038_50380901_41_dialog_content = "Meong.",
  ui_story_5038_50380901_42_dialog_content = "Adalah urusanku untuk menjagamu. Apakah kamu tidak menyadari betapa beranginnya itu?",
  ui_story_5038_50380901_43_dialog_content = "Satu hembusan bisa membuat Anda pergi ke siapa-tahu-di mana.",
  ui_story_5038_50380901_44_dialog_content = "Kembalilah ke kabin bersamaku.",
  ui_story_5038_50380901_45_dialog_content = "Meeoong!",
  ui_story_5038_50380901_46_dialog_content = "*Terengah-engah* Ya ampun, itu benar-benar bisa lari.",
  ui_story_5038_50380901_47_dialog_content = "Jangan khawatir. Hewan memiliki naluri yang jauh lebih tajam daripada kita.",
  ui_story_5038_50380901_48_dialog_content = "Kitalah yang harus mengandalkan mereka ketika bahaya yang sebenarnya muncul.",
  ui_story_5038_50380901_49_dialog_content = "Senang melihatmu di sini, Yuebai!",
  ui_story_5038_50380901_50_dialog_content = "Pernahkah Anda melihat Liqing? Aku tidak melihatnya sama sekali hari ini.",
  ui_story_5038_50380901_51_dialog_content = "Saya tidak perlu khawatir tentang Tinytail jika dia ada.",
  ui_story_5038_50380901_52_dialog_content = "Dia sibuk dengan pasien.",
  ui_story_5038_50380901_53_dialog_content = "Dua awak lagi terserang demam hari ini.",
  ui_story_5038_50380901_54_dialog_content = "Dia pasti sibuk.",
  ui_story_5038_50380901_55_dialog_content = "Lebih banyak penyakit...",
  ui_story_5038_50380901_56_dialog_content = "Berapa lama lagi sampai kita mencapai Longzhou, Yuebai?",
  ui_story_5038_50380901_57_dialog_content = "...",
  ui_story_5038_50380901_58_dialog_content = "Entahwah...",
  ui_story_5038_50380901_59_dialog_content = "(Dia terdengar sedikit sedih...)",
  ui_story_5038_50380901_60_dialog_content = "(Mungkin karena dia tidak tahu bagaimana menjawabnya.)",
  ui_story_5038_50380901_61_dialog_content = "(Kita bisa beralih ke Yuebai, tapi dia bisa berpaling ke siapa?)",
  ui_story_5038_50380901_62_dialog_content = "Lautnya sangat besar. Longzhou jauh melampaui cakrawala, jauh dari pandanganku.",
  ui_story_5038_50380901_63_dialog_content = "Saya hanya bisa mengurus hal-hal dalam jangkauan saya, yang bisa saya lihat.",
  ui_story_5038_50380901_64_dialog_content = "Kau harus kembali ke kabinmu. Badai akan datang.",
  ui_story_5038_50380901_65_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5038_50380901_66_dialog_content = "Kapten, kami mengikat semua yang ada di geladak dan semua kru juga sudah siap.",
  ui_story_5038_50380901_67_dialog_content = "Apakah kita memiliki cukup pemberat?",
  ui_story_5038_50380901_68_dialog_content = "Ya. Beratnya harus menahan gelombang.",
  ui_story_5038_50380901_69_dialog_content = "Oke, kalau begitu kita harus melakukan tindakan pencegahan.",
  ui_story_5038_50380901_70_dialog_content = "Tunggu perintahku di buritan.",
  ui_story_5038_50380901_71_dialog_content = "Um, bukankah kita harus menggulung layarnya, Kapten?",
  ui_story_5038_50380901_72_dialog_content = "No Kami akan berlayar penuh.",
  ui_story_5038_50380901_73_dialog_content = "Dalam badai?",
  ui_story_5038_50380901_74_dialog_content = "Itu terlalu berbahaya! Kami tidak akan bisa mengendalikan kapal!",
  ui_story_5038_50380901_75_dialog_content = "Belum lagi Eclipsites bisa menaiki kapal seperti sebelumnya!",
  ui_story_5038_50380901_76_dialog_content = "Aku tahu, tapi kita tidak bisa menunggu lebih lama lagi.",
  ui_story_5038_50380901_77_dialog_content = "Waktu juga menjadi musuh sekarang.",
  ui_story_5038_50380901_78_dialog_content = "Kita akan kehilangan kesempatan untuk mencapai pantai jika kita berhenti sekarang.",
  ui_story_5038_50380901_79_dialog_content = "Namun…",
  ui_story_5038_50380901_80_dialog_content = "Kita harus memanfaatkan setiap hembusan angin yang kita miliki, bahkan di dalam badai sekalipun.",
  ui_story_5038_50380901_81_dialog_content = "Adapun Eclipsites, penyusuplah yang seharusnya takut menginjakkan kaki di kapal ini, bukan kita.",
  ui_story_5038_50380901_82_dialog_content = "Kami tidak kekurangan tamu di pesawat yang mencari tindakan.",
  ui_story_5038_50380901_83_dialog_content = "Karena Anda mengatakannya seperti itu ...",
  ui_story_5038_50380901_84_dialog_content = "Ah, apapun! Saya hanya seorang kelasi. Ini perintah kapten.",
  ui_story_5038_50380901_85_dialog_content = "Baik. Ambil posisi di buritan.",
  ui_story_5038_50380901_86_dialog_content = "Lonjakan akan segera datang. Bersiaplah untuk pesanan saya.",
  ui_story_5038_50380901_87_dialog_content = "Ya!",
  ui_story_5038_50381001_1_dialog_content = "(Badai telah mengguncang Shadowind sepanjang hari.)",
  ui_story_5038_50381001_2_dialog_content = "(Kami telah mengalami begitu banyak masalah, mulai dari mabuk laut, hingga kawanan ikan yang menyerang, hingga Eclipsites.)",
  ui_story_5038_50381001_3_dialog_content = "(Tapi barusan, suara angin kencang yang merobek layar akhirnya mulai mereda.)",
  ui_story_5038_50381001_4_dialog_content = "(Begitulah cara kami tahu kami berhasil melewatinya.)",
  ui_story_5038_50381001_5_dialog_content = "Dek tampaknya aman sekarang.",
  ui_story_5038_50381001_6_dialog_content = "Itu akan terlihat seperti itu. Sudahkah kita berhasil melewati badai?",
  ui_story_5038_50381001_7_dialog_content = "Ya, bagian tersulit dari perjalanan telah berakhir.",
  ui_story_5038_50381001_8_dialog_content = "Hanya turbulensi kecil mulai saat ini, tidak ada tindakan pencegahan yang tidak dapat diselesaikan.",
  ui_story_5038_50381001_9_dialog_content = "Syukurlah sudah berakhir.",
  ui_story_5038_50381001_10_dialog_content = "Aku akan memuntahkan semua organku jika kapal terus bergoyang.",
  ui_story_5038_50381001_11_dialog_content = "Apakah kamu baik-baik saja, Tianxian? Kamu terlihat sangat kasar.",
  ui_story_5038_50381001_12_dialog_content = "Aku tergantung di sana. Mendapatkan udara segar di geladak sangat membantu.",
  ui_story_5038_50381001_13_dialog_content = "Bukankah sudah waktunya makan, Kapten?",
  ui_story_5038_50381001_14_dialog_content = "Kita harus mendapatkan sesuatu dalam diri kita setelah seharian dalam badai yang kacau balau itu.",
  ui_story_5038_50381001_15_dialog_content = "Ya, kau benar.",
  ui_story_5038_50381001_16_dialog_content = "Kelasi, beri tahu juru masak di dapur untuk menyiapkan makan malam.",
  ui_story_5038_50381001_17_dialog_content = "Ya.",
  ui_story_5038_50381001_18_dialog_content = "Namun, Kapten, kami kekurangan perbekalan jadi kami harus menjatahnya.",
  ui_story_5038_50381001_19_dialog_content = "Aku perlu tahu berapa hari lagi kita akan berlayar.",
  ui_story_5038_50381001_20_dialog_content = "... Itu saat ini belum ditentukan.",
  ui_story_5038_50381001_21_dialog_content = "Biar perut semua orang kenyang dulu.",
  ui_story_5038_50381001_22_dialog_content = "Tidak, mungkin hanya setengah penuh.",
  ui_story_5038_50381001_23_dialog_content = "Hei, berapa jatah yang tersisa?",
  ui_story_5038_50381001_24_dialog_content = "...",
  ui_story_5038_50381001_25_dialog_content = "Aku tahu kau tahu, jadi beritahu aku.",
  ui_story_5038_50381001_26_dialog_content = "Saya mengerti situasinya sangat mengerikan, tetapi saya ingin tahu seberapa mengerikannya.",
  ui_story_5038_50381001_27_dialog_content = "Kita tidak bisa terus seperti ini.",
  ui_story_5038_50381001_28_dialog_content = "Apa?",
  ui_story_5038_50381001_29_dialog_content = "Datang. Panggil semua orang untuk mulai memancing.",
  ui_story_5038_50381001_30_dialog_content = "Sekarang? Tapi ada pekerjaan yang harus dilakukan—",
  ui_story_5038_50381001_31_dialog_content = "Yang tidak penting bisa menunggu.",
  ui_story_5038_50381001_32_dialog_content = "Beri tahu semua orang untuk meluangkan waktu untuk memancing.",
  ui_story_5038_50381001_33_dialog_content = "Kalau tidak, kita tidak akan punya apa pun untuk dimakan dalam beberapa hari.",
  ui_story_5038_50381001_34_dialog_content = "Serius itu...?",
  ui_story_5038_50381001_35_dialog_content = "Baiklah, aku akan mengumpulkan kru.",
  ui_story_5038_50381001_36_dialog_content = "Jaring ini penuh!",
  ui_story_5038_50381001_37_dialog_content = "Cepat, bantu aku menariknya!",
  ui_story_5038_50381001_38_dialog_content = "Hei, hai!",
  ui_story_5038_50381001_39_dialog_content = "Mengapa seluruh kru menangkap ikan di geladak?",
  ui_story_5038_50381001_40_dialog_content = "Apakah ada ... masalah dengan persediaan makanan kita?",
  ui_story_5038_50381001_41_dialog_content = "Tentu saja. Makanan adalah kebutuhan yang paling mendasar dan utama.",
  ui_story_5038_50381001_42_dialog_content = "Kapalnya baik-baik saja sekarang, tapi bagaimana dengan kita? Bisakah kita bertahan?",
  ui_story_5038_50381001_43_dialog_content = "Huh...",
  ui_story_5038_50381001_44_dialog_content = "Setidaknya kita berada di lautan di mana banyak ikan.",
  ui_story_5038_50381001_45_dialog_content = "Tidak sesederhana itu.",
  ui_story_5038_50381001_46_dialog_content = "Meski setiap orang tidak keberatan makan ikan setiap saat, kita tetap mengonsumsi air tawar setiap hari.",
  ui_story_5038_50381001_47_dialog_content = "Saat itu hilang, berarti akhir perjalanan kita.",
  ui_story_5038_50381001_48_dialog_content = "Bagaimanapun, kita adalah makhluk darat.",
  ui_story_5038_50381001_49_dialog_content = "Begitu kita berada di laut, hitungan mundur dimulai.",
  ui_story_5038_50381001_50_dialog_content = "Hitung mundur, ya...",
  ui_story_5038_50381001_51_dialog_content = "Bertanya-tanya berapa banyak waktu yang tersisa.",
  ui_story_5038_50381001_52_dialog_content = "Tertangkap satu lagi! Ini juga besar!",
  ui_story_5038_50381001_53_dialog_content = "Baiklah, kita membutuhkan semua orang untuk ini!",
  ui_story_5038_50381001_54_dialog_content = "Tiga dua satu!",
  ui_story_5038_50381001_55_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5038_50381001_56_dialog_content = "Wow, ini sangat besar!",
  ui_story_5038_50381001_57_dialog_content = "Ya, jackpot!",
  ui_story_5038_50381001_58_dialog_content = "Seharusnya cukup untuk lima atau enam orang!",
  ui_story_5038_50381001_59_dialog_content = "Ya, itu sangat besar!",
  ui_story_5038_50381001_60_dialog_content = "Aku belum pernah melihat ikan sebesar ini sebelumnya!",
  ui_story_5038_50381001_61_dialog_content = "Ayo, kita angkut ke dapur.",
  ui_story_5038_50381001_62_dialog_content = "Ini harus menebus sedikit yang kita miliki malam ini!",
  ui_story_5038_50381001_63_dialog_content = "<size=50>Ya!</size>",
  ui_story_5038_50381001_64_dialog_content = "Lepaskan.",
  ui_story_5038_50381001_65_dialog_content = "Apa? Siapa yang bilang?",
  ui_story_5038_50381001_66_dialog_content = "Itu aku, dan aku berkata, lepaskan.",
  ui_story_5038_50381001_67_dialog_content = "Tuan Zhong? Tapi kenapa?",
  ui_story_5038_50381001_68_dialog_content = "Dia benar. Lepaskan sekaligus.",
  ui_story_5038_50381001_69_dialog_content = "Perhatikan baik-baik, itu adalah ikan ular!",
  ui_story_5038_50381001_70_dialog_content = "Ikan ular!?",
  ui_story_5038_50381001_X70_dialog_content = "Sial, aku tidak memperhatikan sekarang. Bukankah itu yang menyerang kita sebelumnya...",
  ui_story_5038_50381001_71_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5038_50381001_72_dialog_content = "Aduh...",
  ui_story_5038_50381001_73_dialog_content = "Woah!",
  ui_story_5038_50381001_74_dialog_content = "Apa yang sedang terjadi? Apakah kita bertabrakan dengan sesuatu?",
  ui_story_5038_50381001_75_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5038_50381001_76_dialog_content = "T-Itu dia lagi!",
  ui_story_5038_50381001_77_dialog_content = "Lihat ke bawah!",
  ui_story_5038_50381001_78_dialog_content = "Sekolah ikan! Mereka menabrak kita!",
  ui_story_5038_50381001_79_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5038_50381001_80_dialog_content = "Mencari! Mereka melompat ke geladak!",
  ui_story_5038_50381002_1_dialog_content = "<color=#e8d9bb>Plak!</color>",
  ui_story_5038_50381002_2_dialog_content = "Ahhhh!",
  ui_story_5038_50381002_3_dialog_content = "Apa sekarang? Mereka masih menabrak kita...",
  ui_story_5038_50381002_4_dialog_content = "Kami baru saja memperbaiki lambung bawah. Jika mereka melanggarnya...",
  ui_story_5038_50381002_5_dialog_content = "Beri aku ikan besar itu!",
  ui_story_5038_50381002_6_dialog_content = "Hah?",
  ui_story_5038_50381002_7_dialog_content = "Silakan kembali ke tempat asalmu, Yang Mulia!",
  ui_story_5038_50381002_8_dialog_content = "Ini dia!",
  ui_story_5038_50381002_9_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5038_50381002_10_dialog_content = "Oke, semuanya harus baik-baik saja sekarang.",
  ui_story_5038_50381002_11_dialog_content = "Apakah itu memanggil ikan lain?",
  ui_story_5038_50381002_12_dialog_content = "Ya. Serpentfish selalu berkelompok, dan rasa persatuan mereka kuat.",
  ui_story_5038_50381002_13_dialog_content = "Seluruh sekolah akan membantu setiap anggota yang bermasalah.",
  ui_story_5038_50381002_14_dialog_content = "Tidak bijaksana membuat marah ikan ular di laut.",
  ui_story_5038_50381002_15_dialog_content = "Mentalitas kemas... Sungguh sifat yang unik.",
  ui_story_5038_50381002_16_dialog_content = "Terima kasih atas peringatannya, Liqing, Tuan Zhong.",
  ui_story_5038_50381002_17_dialog_content = "Kami mohon maaf atas kecerobohan kami.",
  ui_story_5038_50381002_18_dialog_content = "Tidak masalah. Kita semua berada di perahu yang sama. Secara harfiah.",
  ui_story_5038_50381002_19_dialog_content = "Tidak ada salahnya keluar dari itu, jadi mari kita lupakan saja itu terjadi.",
  ui_story_5038_50381002_20_dialog_content = "Tidak percaya serpentfish ada di perairan ini. Jangan bilang mereka akan menyerang kita lagi...",
  ui_story_5038_50381002_21_dialog_content = "Kami tidak akan mampu menahan gelombang lain...",
  ui_story_5038_50381002_22_dialog_content = "<color=#e8d9bb>Keesokan harinya</color>",
  ui_story_5038_50381002_23_dialog_content = "Ikan ular lain! Lepaskan sekarang!",
  ui_story_5038_50381002_24_dialog_content = "Saya tahu saya tahu. Ini tidak seperti ini adalah pertama kalinya.",
  ui_story_5038_50381002_25_dialog_content = "Sigh... Tidak bisakah mereka berhenti merusak peluang kita untuk menangkap ikan?",
  ui_story_5038_50381002_26_dialog_content = "Yang ketujuh...",
  ui_story_5038_50381002_27_dialog_content = "Itu dia, Yuebai!",
  ui_story_5038_50381002_28_dialog_content = "Mereka mengirim saya untuk memberi tahu Anda bahwa makan siang sudah siap.",
  ui_story_5038_50381002_29_dialog_content = "Tebak apa? Kita akan makan enak hari ini! Padahal semuanya dimasak dengan ikan.",
  ui_story_5038_50381002_30_dialog_content = "Kalian pergilah. Saya akan menahannya untuk saat ini.",
  ui_story_5038_50381002_31_dialog_content = "Apa? Bagaimana bisa?",
  ui_story_5038_50381002_32_dialog_content = "Apakah ada sesuatu yang mengganggumu?",
  ui_story_5038_50381002_33_dialog_content = "Ada, dan saya ingin mengetahuinya, untuk meredakan kekhawatiran saya.",
  ui_story_5038_50381002_34_dialog_content = "Ada apa?",
  ui_story_5038_50381002_35_dialog_content = "Serpentfish ini berperilaku sangat tidak biasa.",
  ui_story_5038_50381002_36_dialog_content = "Mereka adalah spesies migrasi yang melakukan perjalanan antara pantai Astra dan Longzhou dalam kelompok.",
  ui_story_5038_50381002_37_dialog_content = "Mereka tidak pernah tinggal lama di bagian lautan mana pun selain sebentar saat berada di dekat pantai.",
  ui_story_5038_50381002_38_dialog_content = "Tapi sekarang, kelompok dari mereka tampaknya berkeliaran di daerah itu.",
  ui_story_5038_50381002_39_dialog_content = "Benar, para kru terus menangkap mereka hari ini.",
  ui_story_5038_50381002_40_dialog_content = "Mereka tidak menyerang kita lagi, kan?",
  ui_story_5038_50381002_41_dialog_content = "Sepertinya tidak demikian saat ini.",
  ui_story_5038_50381002_42_dialog_content = "Saya melakukan yang terbaik untuk menavigasi di sekitar mereka untuk menghindari terulangnya apa yang terjadi sebelumnya.",
  ui_story_5038_50381002_43_dialog_content = "Tetapi perilaku aneh mereka menunjukkan kondisi yang tidak biasa di masa depan.",
  ui_story_5038_50381002_44_dialog_content = "Sesuatu di sini lebih memikat ikan ular daripada Longzhou.",
  ui_story_5038_50381002_45_dialog_content = "Hmm…",
  ui_story_5038_50381002_46_dialog_content = "Pergi dan makan siang. Aku harus melihat grafiknya.",
  ui_story_5038_50381002_47_dialog_content = "Di dunia mana kita telah berlayar ke...?",
  ui_story_5038_50381002_48_dialog_content = "Arah dan kecepatan angin kemarin...",
  ui_story_5038_50381002_49_dialog_content = "Tidak, sedikit lebih ke utara.",
  ui_story_5038_50381002_50_dialog_content = "<color=#e8d9bb>Tok, tok.</color>",
  ui_story_5038_50381002_51_dialog_content = "Siapa itu?",
  ui_story_5038_50381002_52_dialog_content = "Ini aku, Zhong Xu.",
  ui_story_5038_50381002_53_dialog_content = "Apa yang membawamu ke sini, Tuan Zhong?",
  ui_story_5038_50381002_54_dialog_content = "Aku sudah terlalu lama berada di kapal goyang ini untuk mengetahui ke mana kita akan pergi.",
  ui_story_5038_50381002_55_dialog_content = "Bolehkah saya bertanya di mana kita sekarang?",
  ui_story_5038_50381002_56_dialog_content = "Ini...",
  ui_story_5038_50381002_57_dialog_content = "Terus terang, dengan bagan yang tidak lengkap ini, saya tidak dapat memberi tahu Anda lokasi persis kami.",
  ui_story_5038_50381002_58_dialog_content = "Tolong beri saya lebih banyak waktu untuk mengurai masalah ini.",
  ui_story_5038_50381002_59_dialog_content = "Tentu saja. Saya tidak tahu apa-apa tentang berlayar. Saya hanya ingin tahu.",
  ui_story_5038_50381002_60_dialog_content = "Anda adalah kaptennya, jadi saya yakin Anda punya rencana.",
  ui_story_5038_50381002_61_dialog_content = "...",
  ui_story_5038_50381002_62_dialog_content = "Kecuali, tentu saja, seperti saya, Anda tidak melakukannya.",
  ui_story_5038_50381002_63_dialog_content = "Huh...",
  ui_story_5038_50381002_64_dialog_content = "Saya khawatir saya tidak memiliki kesombongan untuk mengklaim bahwa saya tahu di mana kita berada, Tuanku.",
  ui_story_5038_50381002_65_dialog_content = "Satu-satunya hal yang bisa saya janjikan adalah bahwa saya akan melakukan yang terbaik.",
  ui_story_5038_50381002_66_dialog_content = "Tidak ada yang bisa memprediksi masa depan.",
  ui_story_5038_50381002_67_dialog_content = "Aku mengagumi tekadmu, Kapten.",
  ui_story_5038_50381002_68_dialog_content = "Tapi masa depan tidak sepenuhnya tidak dapat diprediksi di laut.",
  ui_story_5038_50381002_69_dialog_content = "...",
  ui_story_5038_50381002_70_dialog_content = "Apakah Anda mengacu pada The Compass, Pak?",
  ui_story_5038_50381002_71_dialog_content = "Ya. Saya mengerti bahwa prioritas Anda adalah menyelesaikan perjalanan.",
  ui_story_5038_50381002_72_dialog_content = "Namun kapal tersebut kehabisan perbekalan dan praktis hilang. Hanya Sang Kompas yang dapat mengarahkan kita ke jalan yang benar.",
  ui_story_5038_50381002_73_dialog_content = "Kompas...",
  ui_story_5038_50381002_74_dialog_content = "Bahkan jika itu sekuat yang Anda klaim, Tuanku ...",
  ui_story_5038_50381002_75_dialog_content = "Kami tidak memiliki sumber daya untuk mencarinya.",
  ui_story_5038_50381002_76_dialog_content = "Bagaimana jika kita tidak perlu mencari jauh-jauh untuk itu?",
  ui_story_5038_50381002_77_dialog_content = "Harta karun Lin itu ada di sekitar sini.",
  ui_story_5038_50381002_78_dialog_content = "Apa?!",
  ui_story_5038_50381002_79_dialog_content = "Huh...",
  ui_story_5038_50381002_80_dialog_content = "Kotak makanan basi lainnya...",
  ui_story_5038_50381002_81_dialog_content = "Mungkin seharusnya tidak membuangnya.",
  ui_story_5038_50381002_82_dialog_content = "Makanan manja lebih baik daripada tidak sama sekali.",
  ui_story_5038_50381002_83_dialog_content = "Bagaimana dengan air tawar...",
  ui_story_5038_50381002_84_dialog_content = "<color=#e8d9bb>Klang!</color>",
  ui_story_5038_50381002_85_dialog_content = "Kandang ini kosong.",
  ui_story_5038_50381002_86_dialog_content = "Kita bisa memanfaatkan hujan sekarang.",
  ui_story_5038_50381002_87_dialog_content = "Berapa banyak yang tersisa? Saya melihat satu, dua, tiga ...",
  ui_story_5038_50381002_88_dialog_content = "Anda disana!",
  ui_story_5038_50381002_89_dialog_content = "Sedang apa kau di sini?",
  ui_story_5038_50381002_90_dialog_content = "Ikuti saya, kapten ingin melihat Anda sekarang!",
  ui_story_5038_50381101_1_dialog_content = "Jangan hanya fokus pada ikan, perhatikan juga cakrawala!",
  ui_story_5038_50381101_2_dialog_content = "Kita harus menyisir area terdekat, perintah kapten!",
  ui_story_5038_50381101_3_dialog_content = "Laporkan kepada saya begitu Anda melihat sesuatu!",
  ui_story_5038_50381101_4_dialog_content = "Iya!",
  ui_story_5038_50381101_5_dialog_content = "Kami sedang mencari Kompas, bukan, Liqing?",
  ui_story_5038_50381101_6_dialog_content = "Tentu saja. Kenapa lagi seluruh kapal diperintahkan untuk menatap laut?",
  ui_story_5038_50381101_7_dialog_content = "Kompas seharusnya ada di kapal Lin lainnya...",
  ui_story_5038_50381101_8_dialog_content = "Itu benar, saya ingat Anda memberi tahu saya bahwa kapal tidak tenggelam.",
  ui_story_5038_50381101_9_dialog_content = "Setidaknya saat Zhong Xu dan aku pergi.",
  ui_story_5038_50381101_10_dialog_content = "Jadi selama ini bisa hanyut dengan sendirinya?",
  ui_story_5038_50381101_11_dialog_content = "Kedengarannya aneh...",
  ui_story_5038_50381101_12_dialog_content = "Bukankah itu hal yang baik? Membuatnya lebih mudah ditemukan.",
  ui_story_5038_50381101_13_dialog_content = "Tapi pasti akan mengalami gelombang besar dan angin kencang setelah sekian lama.",
  ui_story_5038_50381101_14_dialog_content = "Tanpa ada yang menjaganya, kemungkinan besar kapal itu sudah tenggelam sekarang.",
  ui_story_5038_50381101_15_dialog_content = "Tidak mungkin.",
  ui_story_5038_50381101_16_dialog_content = "Tidak saat membawa Kompas berharga yang kita cari!",
  ui_story_5038_50381101_17_dialog_content = "Sudah gelap...",
  ui_story_5038_50381101_18_dialog_content = "Haruskah kita berhenti untuk hari ini?",
  ui_story_5038_50381101_19_dialog_content = "Kita tidak bisa melihat apapun dalam kegelapan.",
  ui_story_5038_50381101_20_dialog_content = "Tapi kami tidak membuat kemajuan hari ini...",
  ui_story_5038_50381101_21_dialog_content = "Dan kita kehabisan waktu.",
  ui_story_5038_50381101_22_dialog_content = "Di sana!",
  ui_story_5038_50381101_23_dialog_content = "Apa itu? Di mana?!",
  ui_story_5038_50381101_24_dialog_content = "Lihat ke mana saya menunjuk!",
  ui_story_5038_50381101_25_dialog_content = "Ya, ada sesuatu yang mengambang seperti ini!",
  ui_story_5038_50381101_26_dialog_content = "Apakah itu... sebuah plakat?",
  ui_story_5038_50381101_27_dialog_content = "Lebih dekat... Lebih dekat...",
  ui_story_5038_50381101_28_dialog_content = "Saya pikir saya bisa melihatnya!",
  ui_story_5038_50381101_29_dialog_content = "Itu adalah sebuah plakat! Bunyinya...",
  ui_story_5038_50381101_30_dialog_content = "Lin!",
  ui_story_5038_50381101_31_dialog_content = "Ini dari Lin Guild!",
  ui_story_5038_50381101_32_dialog_content = "Serikat Lin? Mungkinkah itu Shadowind tua?",
  ui_story_5038_50381101_33_dialog_content = "Sepertinya baru saja jatuh ke air belum lama ini!",
  ui_story_5038_50381101_34_dialog_content = "Itu pertanda pasti bahwa kapal itu ada di dekatnya!",
  ui_story_5038_50381101_35_dialog_content = "Dimana sampannya? Saya mengambilnya!",
  ui_story_5038_50381101_36_dialog_content = "Sekarang?",
  ui_story_5038_50381101_37_dialog_content = "Bukankah seharusnya kamu membicarakannya dengan Yuebai terlebih dahulu—",
  ui_story_5038_50381101_38_dialog_content = "Tidak perlu berterima kasih.",
  ui_story_5038_50381101_39_dialog_content = "Yuebai...?",
  ui_story_5038_50381101_40_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5038_50381101_41_dialog_content = "D-Dia, dia langsung terjun ke air!",
  ui_story_5038_50381101_42_dialog_content = "Aku iri pada orang yang tidak takut air!",
  ui_story_5038_50381101_43_dialog_content = "Tidak mungkin, aku tidak bisa tertinggal!",
  ui_story_5038_50381101_44_dialog_content = "Cepat, turunkan sampannya!",
  ui_story_5038_50381101_45_dialog_content = "(Airnya memiliki bau kayu yang kuat.)",
  ui_story_5038_50381101_46_dialog_content = "(Datang dari bawah lebih dalam.)",
  ui_story_5038_50381101_47_dialog_content = "(Apakah Kapal Lin tenggelam di sini?)",
  ui_story_5038_50381101_48_dialog_content = "(Semoga Kompas tidak tergerus...)",
  ui_story_5038_50381101_49_dialog_content = "(Huh, lagipula aku hanya bisa bergantung pada hal lain pada akhirnya.)",
  ui_story_5038_50381101_50_dialog_content = "(Saya harus terus turun.)",
  ui_story_5038_50381101_51_dialog_content = "(Saya harus menyelam lebih dalam.)",
  ui_story_5038_50381101_52_dialog_content = "(Ke dasar laut...)",
  ui_story_5038_50381101_53_dialog_content = "(Tunggu, apakah itu...)",
  ui_story_5038_50381101_54_dialog_content = "(!!!)",
  ui_story_5038_50381101_55_dialog_content = "(Kapal tenggelam... banyak.)",
  ui_story_5038_50381101_56_dialog_content = "(Jadi seperti inilah tampilan kapal yang biasa saya lihat di dasar laut.)",
  ui_story_5038_50381101_57_dialog_content = "(Mereka terlihat sangat tenang, luar biasa.)",
  ui_story_5038_50381101_58_dialog_content = "(Tidak peduli apa yang mereka temui sebelumnya, di dasar lautan, hanya ada ketenangan.)",
  ui_story_5038_50381101_59_dialog_content = "(Keheningan berbatasan dengan ketakutan.)",
  ui_story_5038_50381101_60_dialog_content = "(Laut tidak hanya melahap kapal, tetapi juga awak kapal dan tangisan kesedihan mereka.)",
  ui_story_5038_50381101_61_dialog_content = "(Ia menyerap segala sesuatu dalam genggamannya yang tak berujung; bahkan ombak pun tidak terhindar.)",
  ui_story_5038_50381101_62_dialog_content = "(Ini seperti kuburan kapal karam, pelabuhan terakhir mereka.)",
  ui_story_5038_50381101_63_dialog_content = "(Setelah berlabuh di sini, mereka tidak akan pernah berlayar lagi.)",
  ui_story_5038_50381101_64_dialog_content = "(Haruskah saya memeriksanya?)",
  ui_story_5038_50381101_65_dialog_content = "(Tapi saya tidak melihat kapal Lin...)",
  ui_story_5038_50381101_66_dialog_content = "<color=#e8d9bb>Wuush!</color>",
  ui_story_5038_50381101_67_dialog_content = "Oke, sampan sudah siap untukmu.",
  ui_story_5038_50381101_68_dialog_content = "Apakah Anda akan pergi sekarang?",
  ui_story_5038_50381101_69_dialog_content = "Ya, sekarang!",
  ui_story_5038_50381101_70_dialog_content = "Biarkan aku ikut denganmu, Liqing.",
  ui_story_5038_50381101_71_dialog_content = "Kamu pergi sendirian membuatku sedikit...",
  ui_story_5038_50381101_72_dialog_content = "A-Apakah kamu tidak takut air?",
  ui_story_5038_50381101_73_dialog_content = "Mhm...",
  ui_story_5038_50381101_74_dialog_content = "Baik, kamu bisa ikut.",
  ui_story_5038_50381101_75_dialog_content = "Dayungnya terlalu panjang untuk aku mendayung sendiri.",
  ui_story_5038_50381101_76_dialog_content = "Sempurna, ayo pergi!",
  ui_story_5038_50381101_77_dialog_content = "Pindahkan sampan ke—",
  ui_story_5038_50381101_78_dialog_content = "Graah...",
  ui_story_5038_50381101_79_dialog_content = "...?! Apa yang terjadi?",
  ui_story_5038_50381101_80_dialog_content = "Ada sesuatu yang memegang kolek!",
  ui_story_5038_50381101_81_dialog_content = "Apa?!",
  ui_story_5038_50381101_82_dialog_content = "Siapa yang akan cukup bodoh ...",
  ui_story_5038_50381101_83_dialog_content = "Raawr!",
  ui_story_5038_50381101_84_dialog_content = "Wah, wah!",
  ui_story_5038_50381101_85_dialog_content = "Dari mana datangnya sampah seperti itu ?!",
  ui_story_5038_50381101_86_dialog_content = "Di sana! Tali diikat ke sampan!",
  ui_story_5038_50381101_87_dialog_content = "Eclipsites memanjatnya!",
  ui_story_5038_50381102_1_dialog_content = "Grah...",
  ui_story_5038_50381102_2_dialog_content = "Ini menyebalkan... Tanganku kotor sekarang.",
  ui_story_5038_50381102_3_dialog_content = "Ada Eclipsite lainnya?",
  ui_story_5038_50381102_4_dialog_content = "Tidak, mereka semua mati.",
  ui_story_5038_50381102_5_dialog_content = "Senang mendengarnya. Ayo, kita harus pergi!",
  ui_story_5038_50381102_6_dialog_content = "Apakah Anda yakin ingin pergi ke sana?",
  ui_story_5038_50381102_7_dialog_content = "Mungkin lebih berbahaya di laut.",
  ui_story_5038_50381102_8_dialog_content = "Yah, kaptenmu baru saja menukik lurus ke bawah.",
  ui_story_5038_50381102_9_dialog_content = "Anda harus lebih peduli tentang dia.",
  ui_story_5038_50381102_10_dialog_content = "Ayo, PlayerName.",
  ui_story_5038_50381102_11_dialog_content = "Tentu!",
  ui_story_5038_50381102_12_dialog_content = "Jangan ikuti kami, Tinytail.",
  ui_story_5038_50381102_13_dialog_content = "Meong?",
  ui_story_5038_50381102_14_dialog_content = "Anda tidak menyadari betapa luasnya lautan sampai Anda berada di perahu kecil.",
  ui_story_5038_50381102_15_dialog_content = "Apa menurutmu kita akan menemukan kapal tua Lin?",
  ui_story_5038_50381102_16_dialog_content = "Nah, petunjuk yang kita miliki menyiratkan bahwa itu tidak jauh.",
  ui_story_5038_50381102_17_dialog_content = "Namun…",
  ui_story_5038_50381102_18_dialog_content = "Anda khawatir itu tenggelam?",
  ui_story_5038_50381102_19_dialog_content = "Ya.",
  ui_story_5038_50381102_20_dialog_content = "Plakat itu melayang sendirian seperti semua reruntuhan yang kami lihat sebelumnya.",
  ui_story_5038_50381102_21_dialog_content = "Mungkin angin meniupnya.",
  ui_story_5038_50381102_22_dialog_content = "Atau dirobek oleh Eclipsites yang naik ke kapal.",
  ui_story_5038_50381102_23_dialog_content = "Apa pun itu, yang penting adalah fakta bahwa kita mengetahuinya di suatu tempat yang dekat.",
  ui_story_5038_50381102_24_dialog_content = "Kita harus menemukannya.",
  ui_story_5038_50381102_25_dialog_content = "Saya suka betapa percaya diri Anda di kapal itu.",
  ui_story_5038_50381102_26_dialog_content = "Tentu saja. Itu membawa Kompas.",
  ui_story_5038_50381102_27_dialog_content = "(Saya merasa Liqing secara khusus berinvestasi dalam menemukan The Compass.)",
  ui_story_5038_50381102_28_dialog_content = "(Tapi motifnya berbeda dari motif Yuebai.)",
  ui_story_5038_50381102_29_dialog_content = "(Saya bisa mengerti mengapa dia terburu-buru, tapi tidak seberapa serius Liqing tentang hal itu.)",
  ui_story_5038_50381102_30_dialog_content = "(Mungkin saya lebih terbiasa dengan betapa santainya dia biasanya.)",
  ui_story_5038_50381102_31_dialog_content = "Ada apa?",
  ui_story_5038_50381102_32_dialog_content = "Kabut?",
  ui_story_5038_50381102_33_dialog_content = "Ya, kami kehilangan visibilitas dengan cepat.",
  ui_story_5038_50381102_34_dialog_content = "Ini menjengkelkan. Di mana angin saat Anda membutuhkannya?",
  ui_story_5038_50381102_35_dialog_content = "Bagaimana kita bisa menemukan sesuatu dalam hal ini?",
  ui_story_5038_50381102_36_dialog_content = "Uh, tiba-tiba aku memikirkan sesuatu yang bahkan lebih mengkhawatirkan...",
  ui_story_5038_50381102_37_dialog_content = "Bagaimana kita akan kembali ke Shadowind jika kita tidak bisa melihat?",
  ui_story_5038_50381102_38_dialog_content = "D-Apakah kamu ingat ke arah mana kapal itu?",
  ui_story_5038_50381102_39_dialog_content = "Eh, kembali ke sana?",
  ui_story_5038_50381102_40_dialog_content = "Atau mungkin ke kiri?",
  ui_story_5038_50381102_41_dialog_content = "Jadi kamu tidak tahu.",
  ui_story_5038_50381102_42_dialog_content = "Jika kita ketinggalan kapal...",
  ui_story_5038_50381102_43_dialog_content = "Ayolah. Tidak seburuk itu.",
  ui_story_5038_50381102_44_dialog_content = "Kami memiliki pancing di sini. Kita bisa hidup dengan ikan selama beberapa hari.",
  ui_story_5038_50381102_45_dialog_content = "Saya ingin hidup lebih dari \"beberapa hari\", terima kasih banyak...",
  ui_story_5038_50381102_46_dialog_content = "Plus, jika kita sampai di kapal tua dan The Compass terlebih dahulu...",
  ui_story_5038_50381102_47_dialog_content = "Kami bahkan mungkin mengalahkan mereka ke Longzhou.",
  ui_story_5038_50381102_48_dialog_content = "Bagaimana kita bahkan mulai menemukan sesuatu dalam begitu banyak kabut?",
  ui_story_5038_50381102_49_dialog_content = "Bukankah kita harus tetap diam dan menunggu kabut berlalu?",
  ui_story_5038_50381102_50_dialog_content = "Kau benar.",
  ui_story_5038_50381102_51_dialog_content = "<color=#e8d9bb>Guyuran!</color>",
  ui_story_5038_50381102_52_dialog_content = "Aaaaaaaargh!!",
  ui_story_5038_50381102_53_dialog_content = "Ada apa?",
  ui_story_5038_50381102_54_dialog_content = "Aku semua basah kuyup!!!!!!",
  ui_story_5038_50381102_55_dialog_content = "Dapatkan di belakangku, Liqing—",
  ui_story_5038_50381102_56_dialog_content = "Berhenti berteriak, ini hanya aku.",
  ui_story_5038_50381102_57_dialog_content = "Yuebai?",
  ui_story_5038_50381102_58_dialog_content = "Anda keluar dari laut?",
  ui_story_5038_50381102_59_dialog_content = "Apakah Anda melihat hal lain di sini?",
  ui_story_5038_50381102_60_dialog_content = "D-Apakah kamu harus melanjutkan seperti ini?",
  ui_story_5038_50381102_61_dialog_content = "Ugh, aku sangat menjijikkan basah ...",
  ui_story_5038_50381102_62_dialog_content = "Maaf, saya tidak terbiasa melayani kebutuhan hidrofobik di atas air.",
  ui_story_5038_50381102_63_dialog_content = "Kenapa kamu...",
  ui_story_5038_50381102_64_dialog_content = "Mari serius sejenak.",
  ui_story_5038_50381102_65_dialog_content = "Aku baru saja menemukan kuburan kapal di bawah sana.",
  ui_story_5038_50381102_66_dialog_content = "Jadi benar-benar ada kapal yang tenggelam...",
  ui_story_5038_50381102_67_dialog_content = "Tunggu, Anda menyelam sampai ke dasar laut?",
  ui_story_5038_50381102_68_dialog_content = "Saya tidak akan melakukannya jika saya bukan perenang yang hebat.",
  ui_story_5038_50381102_69_dialog_content = "Omong-omong tentang kuburan, penuh dengan kapal dagang.",
  ui_story_5038_50381102_70_dialog_content = "Saya melihat sekeliling tetapi tidak menemukan kapal Lin.",
  ui_story_5038_50381102_71_dialog_content = "Jadi bukan disitu...",
  ui_story_5038_50381102_72_dialog_content = "Apakah Anda memperhatikan sesuatu di permukaan?",
  ui_story_5038_50381102_73_dialog_content = "Tidak.",
  ui_story_5038_50381102_74_dialog_content = "Sulit untuk melihat di malam hari, dan sekarang kabut menutupi segalanya.",
  ui_story_5038_50381102_75_dialog_content = "Lupakan kapal Lin, kita bahkan tidak tahu di mana Shadowind kita sekarang.",
  ui_story_5038_50381102_76_dialog_content = "Saya berharap sebanyak itu.",
  ui_story_5038_50381102_77_dialog_content = "Kami mungkin tidak akan menemukan apa pun dalam kabut ini.",
  ui_story_5038_50381102_78_dialog_content = "Mari kita kembali. Berikan aku dayung.",
  ui_story_5038_50381102_79_dialog_content = "Tentu! Anda tahu di mana Shadowind?",
  ui_story_5038_50381102_80_dialog_content = "Tentu saja. Bagaimana bisa seorang kapten kehilangan kapalnya?",
  ui_story_5038_50381102_81_dialog_content = "Hebat! Itu membuat saya merasa jauh lebih baik!",
  ui_story_5038_50381102_82_dialog_content = "R-Row lebih cepat, saya harus mengeringkan diri dengan tungku sesegera mungkin.",
  ui_story_5038_50381102_83_dialog_content = "Ya, saya tidak akan lengah.",
  ui_story_5038_50381102_84_dialog_content = "(Yuebai mendayung jauh lebih baik daripada Liqing atau aku.)",
  ui_story_5038_50381102_85_dialog_content = "(Dengan semua kabut tebal yang mengelilingi kami, saya tidak tahu apakah perahu benar-benar bergerak, apalagi arah mana yang akan kami tuju.)",
  ui_story_5038_50381102_86_dialog_content = "(Bisakah Yuebai benar-benar menemukan jalannya dalam kabut?)",
  ui_story_5038_50381102_87_dialog_content = "(Namun, aku memercayainya. Dia menemukan koleknya, bukan? Kapal besar seperti Shadowind seharusnya tidak menjadi masalah.)",
  ui_story_5038_50381102_88_dialog_content = "Hatsyiii!",
  ui_story_5038_50381102_89_dialog_content = "Saat aku kembali, aku harus menjadikan diriku—",
  ui_story_5038_50381102_90_dialog_content = "Hei, apakah itu...?",
  ui_story_5038_50381102_91_dialog_content = "Ya, kami pulang!",
  ui_story_5038_50381102_92_dialog_content = "Ya, benar. Aku tidak tahu sampai kami sedekat ini.",
  ui_story_5038_50381102_93_dialog_content = "Dan ini pertama kalinya aku melihat Shadowind dari sudut ini.",
  ui_story_5038_50381102_94_dialog_content = "Begitu megah dan megah...",
  ui_story_5038_50381102_95_dialog_content = "Mari kita minta seseorang untuk menarik kita.",
  ui_story_5038_50381102_96_dialog_content = "Hei, kru!",
  ui_story_5038_50381102_97_dialog_content = "Dibawah sini!",
  ui_story_5038_50381102_98_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_99_dialog_content = "Tidak ada jawaban... Apakah mereka semua di tempat tidur?",
  ui_story_5038_50381102_100_dialog_content = "Ya, mengapa begitu sepi?",
  ui_story_5038_50381102_101_dialog_content = "Hei, ada yang bisa mendengarku?",
  ui_story_5038_50381102_102_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5038_50381102_103_dialog_content = "Itu aneh, saya tidak bisa lebih keras lagi.",
  ui_story_5038_50381102_104_dialog_content = "Saya tahu sulit untuk melihat dalam kabut, tetapi seharusnya tidak sulit untuk mendengarnya, bukan?",
  ui_story_5038_50381102_105_dialog_content = "Kapal ini...",
  ui_story_5038_50381102_106_dialog_content = "Menurutmu apa yang sedang terjadi, Yuebai?",
  ui_story_5038_50381102_107_dialog_content = "Mari naik dan lihat.",
  ui_story_5038_50381102_108_dialog_content = "Aku melihat tali di sana. Kita bisa menarik diri.",
  ui_story_5038_50381201_1_dialog_content = "Dari mana semua kabut ini berasal?",
  ui_story_5038_50381201_2_dialog_content = "Kamu memberitahukan saya. Kapten, Liqing, dan PlayerName masih di luar sana. Jika mereka tersesat...",
  ui_story_5038_50381201_3_dialog_content = "Siapa yang tahu apakah kita akan pernah melihat mereka lagi?",
  ui_story_5038_50381201_4_dialog_content = "Mereka di luar sana? Untuk apa?",
  ui_story_5038_50381201_5_dialog_content = "Mereka menemukan petunjuk ke Shadowind yang asli dan mencarinya di perahu kecil.",
  ui_story_5038_50381201_6_dialog_content = "Tidak ada yang menyangka kabut yang tiba-tiba ini turun ke atas kami.",
  ui_story_5038_50381201_7_dialog_content = "Beri tahu semua orang untuk mengangkat obor dan tetap berjaga di haluan.",
  ui_story_5038_50381201_8_dialog_content = "Saya sudah melipat layar untuk meminimalkan kapal agar tidak bergerak.",
  ui_story_5038_50381201_9_dialog_content = "Kapten memiliki arah yang baik dan harus dapat menemukan jalan kembali.",
  ui_story_5038_50381201_10_dialog_content = "Tapi dua lainnya, bagaimanapun ...",
  ui_story_5038_50381201_11_dialog_content = "Jadi, Tuan Penipu, mengapa Anda memanggil Jiu dan saya ke sini?",
  ui_story_5038_50381201_12_dialog_content = "Ada tiga orang yang hilang dan saya ingin membantu menemukan mereka.",
  ui_story_5038_50381201_13_dialog_content = "Anda tidak akan dapat membuat perbedaan mengingat seberapa tebal kabutnya.",
  ui_story_5038_50381201_14_dialog_content = "Lebih baik Anda bergabung dengan saya di kabin untuk mendapatkan dukungan emosional.",
  ui_story_5038_50381201_15_dialog_content = "Bantuan emosional? Apa yang kamu lakukan?",
  ui_story_5038_50381201_16_dialog_content = "Aku akan menemui Tuan Zhong.",
  ui_story_5038_50381201_17_dialog_content = "Hah? Apakah dia menakut-nakuti Anda atau sesuatu?",
  ui_story_5038_50381201_18_dialog_content = "<color=#e8d9bb>Buk, Buk...</color>",
  ui_story_5038_50381201_19_dialog_content = "Maafkan saya, Tuan Zhong.",
  ui_story_5038_50381201_20_dialog_content = "Saya melihat ada kabut di luar. Apakah ada yang salah?",
  ui_story_5038_50381201_21_dialog_content = "Para kru mengatakan kapten, Liqing, dan PlayerName pergi mencari kapal tua, dan sekarang mereka hilang...",
  ui_story_5038_50381201_22_dialog_content = "Kabut ini sangat tidak tepat waktu...",
  ui_story_5038_50381201_23_dialog_content = "Jika mereka bisa menemukan kapal tua itu, mereka akan baik-baik saja.",
  ui_story_5038_50381201_24_dialog_content = "Jika tidak, laut penuh dengan bahaya.",
  ui_story_5038_50381201_25_dialog_content = "Itu benar, terutama dengan ikan ular yang bisa menyerang kapan saja.",
  ui_story_5038_50381201_26_dialog_content = "Mengingat masalah visibilitas kami, bahkan Shadowind dalam bahaya.",
  ui_story_5038_50381201_27_dialog_content = "Kita, bukan?",
  ui_story_5038_50381201_28_dialog_content = "Dan kapal tidak bisa selamat dari serangan lain.",
  ui_story_5038_50381201_29_dialog_content = "Mungkin aku harus meramal masa depan Shadowind.",
  ui_story_5038_50381201_30_dialog_content = "Jika saya bisa meramalkan apa yang akan menyerang kita, setidaknya kita bisa mencoba mempersiapkannya.",
  ui_story_5038_50381201_31_dialog_content = "Anda dapat menghitung hal semacam itu?",
  ui_story_5038_50381201_32_dialog_content = "Pengaturan waktu adalah segalanya, dan sekarang adalah saat yang paling tepat.",
  ui_story_5038_50381201_33_dialog_content = "Namun, saya hanyalah seorang amatir, jadi kemampuan saya terbatas.",
  ui_story_5038_50381201_34_dialog_content = "Semoga ini berhasil.",
  ui_story_5038_50381201_35_dialog_content = "<color=#e8d9bb>Gemerisik, gemerisik...</color>",
  ui_story_5038_50381201_36_dialog_content = "Jadi? Apa yang kamu punya?",
  ui_story_5038_50381201_37_dialog_content = "Saya berterima kasih kepada surga atas kebaikan mereka dalam memberi saya jawaban.",
  ui_story_5038_50381201_38_dialog_content = "Kebenaran akan terungkap di sini, dari mana benang takdir ini dimulai.",
  ui_story_5038_50381201_39_dialog_content = "Di sinilah Shadowind menghadapi bahayanya.",
  ui_story_5038_50381201_40_dialog_content = "Tuan Zhong, tongkat ini menunjukkan Anda sebagai penyebabnya!",
  ui_story_5038_50381201_41_dialog_content = "Hai...!",
  ui_story_5038_50381201_42_dialog_content = "Kamu seharusnya malu dengan dirimu sendiri, PlayerName, membutuhkan saya untuk menarik Anda ke atas tali.",
  ui_story_5038_50381201_43_dialog_content = "Maaf, tidak semua orang terbiasa mendaki di semua tempat.",
  ui_story_5038_50381201_44_dialog_content = "Oke, kita sudah di kapal, tapi...",
  ui_story_5038_50381201_45_dialog_content = "Saya tidak melihat siapa pun di sekitar.",
  ui_story_5038_50381201_46_dialog_content = "Apa yang sedang terjadi? Apakah mereka semua pergi mencari kita?",
  ui_story_5038_50381201_47_dialog_content = "Mari kita periksa kabinnya, mungkin mereka berlindung dari kabut.",
  ui_story_5038_50381201_48_dialog_content = "Tunggu, bukankah kita masuk ke kabin dari sini?",
  ui_story_5038_50381201_49_dialog_content = "Eh, saya pikir saya berbalik saat naik. Mungkin begini caranya...",
  ui_story_5038_50381201_50_dialog_content = "Tidak.",
  ui_story_5038_50381201_51_dialog_content = "Hah?",
  ui_story_5038_50381201_52_dialog_content = "Semuanya mati.",
  ui_story_5038_50381201_53_dialog_content = "Tiang, pagar, geladak...",
  ui_story_5038_50381201_54_dialog_content = "Kami tidak di Shadowind.",
  ui_story_5038_50381201_55_dialog_content = "Awas, di belakangmu!",
  ui_story_5038_50381201_56_dialog_content = "Ada Eclipsites di kapal...",
  ui_story_5038_50381201_57_dialog_content = "Banyak dari mereka.",
  ui_story_5038_50381201_58_dialog_content = "Oh tidak, kami dikelilingi...",
  ui_story_5038_50381201_59_dialog_content = "Tangani yang di kiri dulu, Yuebai!",
  ui_story_5038_50381201_60_dialog_content = "Saya ikut.",
  ui_story_5038_50381201_61_dialog_content = "Anda tampaknya memiliki bakat untuk menangani situasi seperti ini.",
  ui_story_5038_50381201_62_dialog_content = "Tidak mengherankan, mengingat saya bahkan bermimpi tentang Eclipsites muncul tiba-tiba.",
  ui_story_5038_50381201_63_dialog_content = "Sekarang kita harus berhati-hati untuk—",
  ui_story_5038_50381201_64_dialog_content = "Saya menemukan jawabannya!",
  ui_story_5038_50381201_65_dialog_content = "Apa yang kamu temukan?",
  ui_story_5038_50381201_66_dialog_content = "Saya mengenali ini! Saya pernah ke sini sebelumnya!",
  ui_story_5038_50381201_67_dialog_content = "Ini adalah Shadowind! Shadowind asli!!",
  ui_story_5038_50381201_68_dialog_content = "Apa?!",
  ui_story_5038_50381201_69_dialog_content = "Ya…",
  ui_story_5038_50381201_70_dialog_content = "Kami menemukannya melalui keberuntungan yang bodoh?",
  ui_story_5038_50381201_71_dialog_content = "Saya yakin itu! Ini adalah rel yang saya tekuk sebelumnya!",
  ui_story_5038_50381201_72_dialog_content = "Luar biasa, kami akhirnya menemukannya!",
  ui_story_5038_50381201_73_dialog_content = "Kami melakukannya, tetapi saya tidak akan menyebut situasi kami saat ini \"mengagumkan\"...",
  ui_story_5038_50381201_74_dialog_content = "Kompas ada di kabin. Aku tahu persis di mana itu!",
  ui_story_5038_50381201_75_dialog_content = "Ikuti aku. Aku akan membawamu ke sana!",
  ui_story_5038_50381201_76_dialog_content = "Hei, pelan-pelan, kamu tidak tahu apakah ada Eclipsites di dalamnya!",
  ui_story_5038_50381201_77_dialog_content = "Tunggu kami, setidaknya...",
  ui_story_5038_50381201_78_dialog_content = "Dan dia pergi.",
  ui_story_5038_50381201_79_dialog_content = "Teman-teman, kejar!",
  ui_story_5038_50381201_80_dialog_content = "Saya tidak berpikir dia akan mendengarkan Anda.",
  ui_story_5038_50381201_81_dialog_content = "Yuk, ikuti.",
  ui_story_5038_50381201_82_dialog_content = "Eclipsites tidak akan menghentikan saya.",
  ui_story_5038_50381202_1_dialog_content = "Apakah Anda mengatakan Lord Zhong menyebabkan Shadowind diserang? Bagaimana mungkin?",
  ui_story_5038_50381202_2_dialog_content = "Apakah ramalan Anda dapat dipercaya?",
  ui_story_5038_50381202_3_dialog_content = "Li Tianxian, kamu mengejarku selama ini.",
  ui_story_5038_50381202_4_dialog_content = "Anda melakukan pembacaan ini sebelumnya, bukan?",
  ui_story_5038_50381202_5_dialog_content = "Sangat tanggap, Tuan Zhong.",
  ui_story_5038_50381202_6_dialog_content = "Saya memeriksa tongkat saya ketika ikan ular muncul untuk kedua kalinya.",
  ui_story_5038_50381202_X6_dialog_content = "Ketika saya melakukannya, simbol yang diungkapkan kepada saya adalah Harimau Yin.",
  ui_story_5038_50381202_X7_dialog_content = "Saya tidak tahu apa artinya.",
  ui_story_5038_50381202_X8_dialog_content = "Sampai saya tiba-tiba teringat pepatah lama, \"Dia yang memiliki harimau, memimpin batalion.\"",
  ui_story_5038_50381202_X9_dialog_content = "Anda pernah memerintahkan ribuan tentara yang membawa harimau di atas bendera perang. Anda adalah orang yang tersirat oleh ramalan ini.",
  ui_story_5038_50381202_X10_dialog_content = "Menarik. Lanjutkan.",
  ui_story_5038_50381202_X11_dialog_content = "Kata \"Xu\" dalam nama Anda bisa berarti kupu-kupu.",
  ui_story_5038_50381202_7_dialog_content = "Mungkin Anda mengepakkan sayap Anda saat itu, yang mengakibatkan badai yang muncul hari ini.",
  ui_story_5038_50381202_8_dialog_content = "Anda pernah menceritakan kisah kesialan kapal tua itu kepada kami.",
  ui_story_5038_50381202_9_dialog_content = "Kapal Lin yang sarat harta dijarah oleh bajak laut.",
  ui_story_5038_50381202_10_dialog_content = "Namun entah bagaimana pada akhirnya, satu-satunya yang selamat adalah Anda dan Liqing, yang hanyalah tamu kehormatan.",
  ui_story_5038_50381202_11_dialog_content = "Peran apa yang Anda berdua mainkan dalam pertemuan itu?",
  ui_story_5038_50381202_12_dialog_content = "Saya harap Anda dapat menjawab ini dan pertanyaan lainnya.",
  ui_story_5038_50381202_13_dialog_content = "Anda di sini untuk menginterogasi saya; oleh karena itu, Anda dapat membuang formalitas.",
  ui_story_5038_50381202_14_dialog_content = "Anda membawa Dantang dan Jiu karena takut membuat saya marah, bukan?",
  ui_story_5038_50381202_15_dialog_content = "I-Itulah mengapa kamu meminta dukungan emosional...",
  ui_story_5038_50381202_16_dialog_content = "Terlepas dari kenyataan bahwa Anda terkurung di kursi roda, Anda tetap cukup mengintimidasi, Tuanku.",
  ui_story_5038_50381202_17_dialog_content = "Saya mungkin akan menjadi gagap seandainya saya sendirian di hadapan Anda.",
  ui_story_5038_50381202_18_dialog_content = "Baiklah, karena Anda bertanya, saya akan menjelaskannya.",
  ui_story_5038_50381202_19_dialog_content = "Saya sebenarnya juga curiga bahwa serpentfish datang karena saya.",
  ui_story_5038_50381202_20_dialog_content = "Atau lebih tepatnya, bahwa saya bertanggung jawab atas perilaku mereka yang tidak menentu.",
  ui_story_5038_50381202_21_dialog_content = "Apa maksudmu?",
  ui_story_5038_50381202_22_dialog_content = "Mari kita mulai dengan Shadowind lama.",
  ui_story_5038_50381202_23_dialog_content = "Memang benar bahwa Lins memiliki harta karun di kapal dan menarik bajak laut yang tamak.",
  ui_story_5038_50381202_24_dialog_content = "Namun, saya tidak berada di Shadowind saat itu. Saya mengikuti di kapal di belakang para perompak.",
  ui_story_5038_50381202_25_dialog_content = "Anda mengikuti mereka?",
  ui_story_5038_50381202_26_dialog_content = "Saya berjanji kepada Lin Guildmaster bahwa saya akan melindungi properti mereka.",
  ui_story_5038_50381202_27_dialog_content = "Oleh karena itu, saya mengikuti para perompak sepanjang perjalanan dan menaiki Shadowind beberapa saat setelah mereka melakukannya.",
  ui_story_5038_50381202_28_dialog_content = "Pikiran saya adalah untuk mengambil The Compass dari mereka dan kembali ke darat dengan perahu.",
  ui_story_5038_50381202_29_dialog_content = "Apa yang terjadi malam itu di kapal ternyata jauh lebih buruk dari yang saya bayangkan.",
  ui_story_5038_50381202_30_dialog_content = "Para perompak menyita kapal tersebut, tetapi tidak dapat menemukan The Compass.",
  ui_story_5038_50381202_31_dialog_content = "Mereka mulai menyiksa kru untuk keberadaannya.",
  ui_story_5038_50381202_32_dialog_content = "Tidak ada hukum atau keadilan di laut lepas, sesuatu yang dianggap bajingan seperti bebek di air.",
  ui_story_5038_50381202_33_dialog_content = "Ketika saya sampai di sana, tidak ada seorang pun dari keluarga Lin yang masih hidup.",
  ui_story_5038_50381202_34_dialog_content = "Saat itulah saya menyadari bahwa mengambil Kompas itu sia-sia.",
  ui_story_5038_50381202_35_dialog_content = "Lins sudah dalam situasi yang mengerikan. Memiliki Kompas hanya akan membawa lebih banyak masalah.",
  ui_story_5038_50381202_36_dialog_content = "Cara terbaik untuk melindungi harta karun itu adalah membiarkannya \"menghilang\".",
  ui_story_5038_50381202_37_dialog_content = "Lalu apakah Anda membuangnya?",
  ui_story_5038_50381202_38_dialog_content = "Tentu saja tidak. Itu adalah pusaka Lin, dan satu-satunya harapan mereka untuk menjadi terkenal sekali lagi.",
  ui_story_5038_50381202_39_dialog_content = "Kompas harus dirahasiakan, jadi saya harus memastikan tidak ada yang membicarakannya lagi.",
  ui_story_5038_50381202_40_dialog_content = "Tidak ada yang harus membicarakannya...",
  ui_story_5038_50381202_41_dialog_content = "Tunggu, apa kau memberitahuku bahwa kau...",
  ui_story_5038_50381202_42_dialog_content = "Ya, saya harus membunuh setiap hadiah bajak laut.",
  ui_story_5038_50381202_43_dialog_content = "Saya telah berjuang dalam banyak pertempuran selama bertahun-tahun, namun tidak pernah mengalami hal yang begitu menyedihkan seperti itu.",
  ui_story_5038_50381202_44_dialog_content = "Bajak laut itu bukan prajurit. Mereka bersifat oportunistik, dan ketika mereka telah dikalahkan, mereka berlutut memohon belas kasihan.",
  ui_story_5038_50381202_45_dialog_content = "Mereka mengutuk, meratap, dan mempermalukan diri mereka sendiri ketika situasi menjadi suram.",
  ui_story_5038_50381202_46_dialog_content = "Mereka tidak mencoba untuk mengalahkan saya, melainkan mencoba untuk bertahan hidup saya.",
  ui_story_5038_50381202_47_dialog_content = "Beberapa di antara mereka benar-benar tidak dapat ditebus, beberapa hanya berusaha mencari nafkah. Orang-orang berakhir sebagai penjahat karena berbagai alasan.",
  ui_story_5038_50381202_48_dialog_content = "Tetapi saya tidak punya waktu untuk mempertimbangkan alasan-alasan itu. Saya hanya bisa membunuh mereka semua.",
  ui_story_5038_50381202_49_dialog_content = "Untuk melestarikan Kompas?",
  ui_story_5038_50381202_50_dialog_content = "Itu yang saya katakan untuk meyakinkan diri saya sendiri.",
  ui_story_5038_50381202_51_dialog_content = "Ada saat-saat singkat di mana saya merasa melangkah terlalu jauh.",
  ui_story_5038_50381202_52_dialog_content = "Tapi begitu pedangku ternoda darah, sudah terlambat untuk kembali.",
  ui_story_5038_50381202_53_dialog_content = "Oh, begitu…",
  ui_story_5038_50381202_54_dialog_content = "Aku memang berbohong tentang kapal yang dihantam badai.",
  ui_story_5038_50381202_55_dialog_content = "Serpentfish adalah penyebab sebenarnya yang membuat Liqing dan saya terapung-apung di laut.",
  ui_story_5038_50381202_56_dialog_content = "Ikan ular lagi?",
  ui_story_5038_50381202_57_dialog_content = "Itu sebabnya saya merenungkan apakah mereka mengejar saya.",
  ui_story_5038_50381202_58_dialog_content = "Serangan mereka mengingatkan pada serangan di Shadowind tua.",
  ui_story_5038_50381202_59_dialog_content = "Tak satu pun dari hal-hal ini yang relevan dengan pencarian The Compass, jadi saya tidak melihat kebutuhan untuk mengungkitnya.",
  ui_story_5038_50381202_60_dialog_content = "Tapi karena kamu bersikeras, sekarang aku berterus terang.",
  ui_story_5038_50381202_61_dialog_content = "Tidak ada yang ingin meringankan pengalaman seperti itu. Saya minta maaf karena usil!",
  ui_story_5038_50381202_62_dialog_content = "Semuanya baik baik saja. Kita harus saling percaya dengan tegas untuk melewati kesulitan kita saat ini.",
  ui_story_5038_50381202_63_dialog_content = "Ya, kita harus bersatu.",
  ui_story_5038_50381202_64_dialog_content = "Saya harus menghabiskan lebih banyak waktu untuk mencari tahu bagaimana kita akan menyelesaikan masalah saat ini.",
  ui_story_5038_50381202_65_dialog_content = "Hampir tidak mungkin melakukan apa pun dalam kabut ini.",
  ui_story_5038_50381202_66_dialog_content = "Tapi Liqing sangat berdedikasi untuk menemukan The Compass, dan dia memiliki naluri fiendling khusus.",
  ui_story_5038_50381202_67_dialog_content = "Mengingat dia rela melaut sendiri, berarti kapalnya sudah dekat.",
  ui_story_5038_50381202_68_dialog_content = "Mungkin saat kabut terangkat, dia akan kembali dengan The Compass.",
  ui_story_5038_50381202_69_dialog_content = "Itu akan menjadi skenario kasus terbaik...",
  ui_story_5038_50381202_70_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5038_50381202_71_dialog_content = "Apa...",
  ui_story_5038_50381202_72_dialog_content = "<size=45><color=#e8d9bb>Gedebuk!</color></size>",
  ui_story_5038_50381202_73_dialog_content = "Ahhhhhhh!",
  ui_story_5038_50381202_74_dialog_content = "Apa yang terjadi? Mengapa kita melempar begitu buruk?",
  ui_story_5038_50381202_75_dialog_content = "Tuanku, apakah Anda—",
  ui_story_5038_50381202_76_dialog_content = "Saya baik-baik saja. Naik ke geladak untuk melihat apa yang terjadi!",
  ui_story_5038_50381202_77_dialog_content = "Sangat! Tolong tunggu disini...",
  ui_story_5038_50381202_78_dialog_content = "<size=45>Aaaaaahhhhhhhh!!!</size>",
  ui_story_5038_50381202_79_dialog_content = "Kenapa kelasi itu berteriak?!",
  ui_story_5038_50381202_80_dialog_content = "kapal AA...",
  ui_story_5038_50381202_81_dialog_content = "<size=50>Sebuah kapal baru saja menabrak kita!</size>",
  ui_story_5038_50381301_1_dialog_content = "<color=#e8d9bb>Bum!</color>",
  ui_story_5038_50381301_2_dialog_content = "Hey apa yang terjadi?!",
  ui_story_5038_50381301_3_dialog_content = "Busur itu pasti bertabrakan dengan sesuatu. Apakah kamu baik-baik saja?",
  ui_story_5038_50381301_4_dialog_content = "Aku baik-baik saja. Saya sudah terbiasa dengan lingkungan kapal yang tidak stabil sekarang.",
  ui_story_5038_50381301_5_dialog_content = "Apa yang kita pukul, karang?",
  ui_story_5038_50381301_6_dialog_content = "Ayo cepat, itu hanya di depan.",
  ui_story_5038_50381301_7_dialog_content = "Uh, omong-omong, adakah yang bisa mengambil kunci?",
  ui_story_5038_50381301_8_dialog_content = "Pintu itu sepertinya...",
  ui_story_5038_50381301_9_dialog_content = "Pedangku bisa.",
  ui_story_5038_50381301_10_dialog_content = "<color=#e8d9bb>Shiing!</color>",
  ui_story_5038_50381301_11_dialog_content = "Awas, kamu hampir memenggal kepalaku!",
  ui_story_5038_50381301_12_dialog_content = "Apakah kamu tidak akan masuk?",
  ui_story_5038_50381301_13_dialog_content = "Hmmm...",
  ui_story_5038_50381301_14_dialog_content = "Datang dan lihatlah harta karun yang telah kita semua nantikan.",
  ui_story_5038_50381301_15_dialog_content = "<color=#e8d9bb>*Berderak*</color>",
  ui_story_5038_50381301_16_dialog_content = "Waow…",
  ui_story_5038_50381301_17_dialog_content = "Sangat elegan di sini!",
  ui_story_5038_50381301_18_dialog_content = "Jadi seperti inilah klan Longzhou yang kaya, ya?",
  ui_story_5038_50381301_19_dialog_content = "Desain ini...",
  ui_story_5038_50381301_20_dialog_content = "Mereka sangat mirip dengan yang ditemukan di Lin Manor yang saya ingat.",
  ui_story_5038_50381301_21_dialog_content = "Mereka pasti menyembunyikan barang antik dan lukisan ini di sini setelah kejatuhan keluarga.",
  ui_story_5038_50381301_22_dialog_content = "Kediaman Lin? Apakah itu rumahmu?",
  ui_story_5038_50381301_23_dialog_content = "Saya tinggal di sana sebentar ketika saya masih muda.",
  ui_story_5038_50381301_24_dialog_content = "Sampai Persekutuan Lin jatuh ke dalam penurunan, kehilangan semua kekayaan mereka, dan dipaksa untuk menyerahkan tanah itu.",
  ui_story_5038_50381301_25_dialog_content = "Saya tidak pernah berpikir saya akan dapat menikmati citra dari masa lalu lagi.",
  ui_story_5038_50381301_26_dialog_content = "Rumah masa kecil pasti membangkitkan serangan emosi ...",
  ui_story_5038_50381301_27_dialog_content = "Mari berhenti mengenang.",
  ui_story_5038_50381301_28_dialog_content = "Yang mana dari ini Kompas, Liqing?",
  ui_story_5038_50381301_29_dialog_content = "Tidak mungkin, ini tidak bisa...",
  ui_story_5038_50381301_30_dialog_content = "Ada apa, Liqing?",
  ui_story_5038_50381301_31_dialog_content = "Itu tidak ada di sini... Kenapa tidak ada di sini?",
  ui_story_5038_50381301_32_dialog_content = "Apa maksudmu?",
  ui_story_5038_50381301_33_dialog_content = "Mungkin itu tersembunyi di tempat lain.",
  ui_story_5038_50381301_34_dialog_content = "Liqing, jelaskan Kompas kepada kami dan kami akan membantu Anda menemukannya.",
  ui_story_5038_50381301_35_dialog_content = "Tapi... di mana lagi?",
  ui_story_5038_50381301_36_dialog_content = "Itu hanya bisa di dalam tangki di suatu tempat, meskipun ...",
  ui_story_5038_50381301_37_dialog_content = "Di dalam tangki?",
  ui_story_5038_50381301_38_dialog_content = "Tunggu. Apakah Kompas bukan kompas?",
  ui_story_5038_50381301_39_dialog_content = "Kompas adalah seekor ikan.",
  ui_story_5038_50381301_40_dialog_content = "Apa?!",
  ui_story_5038_50381301_41_dialog_content = "Hee...",
  ui_story_5038_50381301_42_dialog_content = "<color=#e8d9bb>*Guyuran*</color>",
  ui_story_5038_50381301_43_dialog_content = "<color=#e8d9bb>*Guyuran*</color>",
  ui_story_5038_50381301_44_dialog_content = "A-Apa yang terjadi?! Kedengarannya seperti ada sesuatu yang akan hancur!",
  ui_story_5038_50381301_45_dialog_content = "Itu porselen, tapi aku tidak bisa melihat di mana itu...",
  ui_story_5038_50381301_46_dialog_content = "Oh tidak, saya baru saja melihat seseorang kehabisan!",
  ui_story_5038_50381301_47_dialog_content = "Ada orang lain di sini?!",
  ui_story_5038_50381301_48_dialog_content = "<color=#e8d9bb>Membanting!</color>",
  ui_story_5038_50381301_49_dialog_content = "Hei, pintunya tertutup!",
  ui_story_5038_50381301_50_dialog_content = "Itu dia di sisi lain!",
  ui_story_5038_50381301_51_dialog_content = "Siapa? Siapa di sisi lain?",
  ui_story_5038_50381301_52_dialog_content = "Terima kasih...",
  ui_story_5038_50381301_53_dialog_content = "?!!",
  ui_story_5038_50381301_54_dialog_content = "Terima kasih... Terima kasih... Kamu.",
  ui_story_5038_50381301_55_dialog_content = "<color=#e8d9bb>Buk, Buk, Buk...</color>",
  ui_story_5038_50381301_56_dialog_content = "Itu…?",
  ui_story_5038_50381301_57_dialog_content = "Dia kabur! Kita harus mengejar!",
  ui_story_5038_50381301_58_dialog_content = "Pintu ini... Kapten, bisakah kau membukanya?",
  ui_story_5038_50381301_59_dialog_content = "Saya mencoba. Itu dibarikade dengan sesuatu yang berat.",
  ui_story_5038_50381301_60_dialog_content = "Ini tidak baik... Kita harus menyusulnya.",
  ui_story_5038_50381301_61_dialog_content = "Apa yang bisa kita lakukan...",
  ui_story_5038_50381301_62_dialog_content = "Ayo lemparkan diri kita ke pintu dan hancurkan!",
  ui_story_5038_50381301_63_dialog_content = "Itu tidak akan berhasil, hanya kita bertiga tidak cukup.",
  ui_story_5038_50381301_64_dialog_content = "Tenang dulu.",
  ui_story_5038_50381301_65_dialog_content = "Bagaimana saya bisa ketika dia akan lari ?!",
  ui_story_5038_50381301_66_dialog_content = "Bagaimana kita akan menemukannya di luar sana di lautan luas?",
  ui_story_5038_50381301_67_dialog_content = "Er, saya mungkin punya cara untuk membuka pintu.",
  ui_story_5038_50381301_68_dialog_content = "Sungguh?",
  ui_story_5038_50381301_69_dialog_content = "Ya, tapi aku butuh waktu.",
  ui_story_5038_50381301_70_dialog_content = "Beri aku waktu sebentar...",
  ui_story_5038_50381301_71_dialog_content = "(Ini mungkin tidak masuk akal, tapi...)",
  ui_story_5038_50381301_72_dialog_content = "(Tidak ada salahnya mencoba!)",
  ui_story_5038_50381301_73_option_content = "Force Boost!",
  ui_story_5038_50381301_74_dialog_content = "Dia tiba-tiba diam. Dia pasti menggunakan kemampuan psikisnya.",
  ui_story_5038_50381301_X74_dialog_content = "Mengapa Anda tidak menggunakan waktu ini untuk memberi tahu saya apa masalahnya dengan The Compass?",
  ui_story_5038_50381301_75_dialog_content = "Dan siapa itu yang melarikan diri?",
  ui_story_5038_50381301_76_dialog_content = "Eh, di mana saya harus mulai ...?",
  ui_story_5038_50381301_77_dialog_content = "Sebenarnya, aku belum pernah melihat orang itu sebelumnya.",
  ui_story_5038_50381301_78_dialog_content = "Tapi jika dia ada di sini, maka hanya ada satu kemungkinan.",
  ui_story_5038_50381301_79_dialog_content = "Dia Kompas.",
  ui_story_5038_50381301_80_dialog_content = "Dia adalah apa?!",
  ui_story_5038_50381301_81_dialog_content = "Satu menit Anda mengatakan Kompas adalah seekor ikan, menit berikutnya Anda memberi tahu saya bahwa dia adalah manusia. Apa yang sedang terjadi?",
  ui_story_5038_50381301_82_dialog_content = "Kompas memang seekor ikan, dan ikan ular yang sangat istimewa pada saat itu.",
  ui_story_5038_50381301_83_dialog_content = "Tapi hanya karena itu ikan bukan berarti harus terlihat seperti itu.",
  ui_story_5038_50381301_84_dialog_content = "Ingat, aku kucing.",
  ui_story_5038_50381301_85_dialog_content = "Apakah Anda mengatakan dia seorang fiendling?",
  ui_story_5038_50381301_86_dialog_content = "Ya, hanya itu kemungkinannya.",
  ui_story_5038_50381301_87_dialog_content = "Dia kemungkinan besar berubah menjadi fiendling saat kapalnya terapung-apung.",
  ui_story_5038_50381301_88_dialog_content = "Evolusi membebaskannya dari air dan pembatasan tangki.",
  ui_story_5038_50381301_89_dialog_content = "Tapi dia masih tidak bisa keluar dari kabin yang terkunci.",
  ui_story_5038_50381301_90_dialog_content = "Sampai kami memecahkan kunci ...",
  ui_story_5038_50381301_91_dialog_content = "... Begitu, ya.",
  ui_story_5038_50381301_92_dialog_content = "Kompas adalah seekor ikan... Bagaimana seekor ikan menavigasi kapal?",
  ui_story_5038_50381301_93_dialog_content = "Sebagai seorang Lin, Anda pasti sangat mengenal totem keluarga Anda, bukan?",
  ui_story_5038_50381301_94_dialog_content = "Serpentfish akan bertindak secara kolektif untuk satu individu di sekolah.",
  ui_story_5038_50381301_95_dialog_content = "Dan Kompas adalah pemimpin ikan ular.",
  ui_story_5038_50381301_96_dialog_content = "Pemimpin?!",
  ui_story_5038_50381301_97_dialog_content = "Tidak heran semua ikan ular mulai bertingkah aneh dan memenuhi wilayah laut ini.",
  ui_story_5038_50381301_98_dialog_content = "Begitulah cara Anda dan Zhong Xu mengetahui bahwa Kompas ada di sini.",
  ui_story_5038_50381301_99_dialog_content = "Benar sekali.",
  ui_story_5038_50381301_100_dialog_content = "Hmm, sepertinya aku mengerti sekarang.",
  ui_story_5038_50381301_101_dialog_content = "Serpentfish ahli dalam melintasi perairan antara dua benua, karena memang sifatnya.",
  ui_story_5038_50381301_102_dialog_content = "Mantan Shadowind mengeksploitasi kemampuan mereka dengan merebut ikan ular utama.",
  ui_story_5038_50381301_103_dialog_content = "Dengan menahan pemimpin mereka, seluruh sekolah mulai membantu kapal menyeberangi lautan...",
  ui_story_5038_50381301_104_dialog_content = "Benar.",
  ui_story_5038_50381301_105_dialog_content = "Lins mengurung ikan ular utama di kapal.",
  ui_story_5038_50381301_106_dialog_content = "Generasi demi generasi berlalu, dan ikan ular yang baru lahir datang untuk melihat Shadowind sebagai pemimpin mereka.",
  ui_story_5038_50381301_107_dialog_content = "Mereka akan berkumpul di belakang kapal dan mendorongnya ke depan setiap kali kapal berlayar.",
  ui_story_5038_50381301_108_dialog_content = "Jadi tidak perlu khawatir tersesat atau terdampar karena cuaca buruk.",
  ui_story_5038_50381301_109_dialog_content = "Ikan akan selalu mengantarkan mereka ke tempat tujuan.",
  ui_story_5038_50381301_110_dialog_content = "Kenapa tidak ada yang memberitahuku tentang ini sebelumnya?",
  ui_story_5038_50381301_111_dialog_content = "Keluarga Lin tidak melakukannya, begitu pula Anda maupun Zhong Xu.",
  ui_story_5038_50381301_112_dialog_content = "Tentang itu ... Zhong Xu agak menjelaskan sedikit, tetapi saya tidak begitu mengerti.",
  ui_story_5038_50381301_113_dialog_content = "Kedengarannya rumit. Sesuatu tentang rahasia dagang, melindungi kehormatan keluarga, dan sebagainya.",
  ui_story_5038_50381301_114_dialog_content = "Secara keseluruhan, menjaga ibu adalah pilihan terbaik.",
  ui_story_5038_50381301_115_dialog_content = "...",
  ui_story_5038_50381301_116_dialog_content = "Bagi saya, yah ... Saya kira saya merasa bersalah tentang semuanya.",
  ui_story_5038_50381301_117_dialog_content = "Sejak saya menginjakkan kaki di Shadowind tua, saya menjadi kaki tangan perbudakan.",
  ui_story_5038_50381301_118_dialog_content = "Setiap kali laut berubah berubah-ubah, saya terpaksa memperlakukannya seperti instrumen.",
  ui_story_5038_50381301_119_dialog_content = "Saya memanggilnya Kompas untuk membuat diri saya merasa lebih baik.",
  ui_story_5038_50381301_120_dialog_content = "Kesalahan...",
  ui_story_5038_50381301_121_dialog_content = "Setidaknya Anda memiliki pandangan ke belakang untuk merasa seperti itu.",
  ui_story_5038_50381301_122_dialog_content = "Itu mungkin karena aku selalu menganggapnya sebagai teman.",
  ui_story_5038_50381301_123_dialog_content = "Oh iya, dia punya nama. Ini Yoh.",
  ui_story_5038_50381301_124_dialog_content = "Yoh... Aku akan mengingatnya.",
  ui_story_5038_50381301_125_dialog_content = "Eh, maaf mengganggu...",
  ui_story_5038_50381301_126_dialog_content = "Saya pikir saya melakukannya.",
  ui_story_5038_50381301_127_dialog_content = "Anda melakukannya? Anda membuka pintu?",
  ui_story_5038_50381301_128_dialog_content = "Ya, itu akan terbuka sedikit.",
  ui_story_5038_50381301_129_dialog_content = "Wow, mengesankan!",
  ui_story_5038_50381301_130_dialog_content = "Kalian berdua harus mempersiapkan diri.",
  ui_story_5038_50381301_131_dialog_content = "Persiapkan diri kita? Untuk apa?",
  ui_story_5038_50381301_132_dialog_content = "Mereka datang!",
  ui_story_5038_50381301_133_dialog_content = "<color=#e8d9bb>Brak!</color>",
  ui_story_5038_50381301_134_dialog_content = "Grrr!",
  ui_story_5038_50381301_135_dialog_content = "Ah!!! Itu mengejutkan saya!",
  ui_story_5038_50381301_136_dialog_content = "Bagaimana Eclipsites bisa masuk?",
  ui_story_5038_50381301_137_dialog_content = "Tunggu sebentar, begitukah caramu membuka pintu?",
  ui_story_5038_50381301_138_dialog_content = "Menggambar Eclipsites dan membuatnya menabraknya?",
  ui_story_5038_50381301_139_dialog_content = "Tidakkah Anda menyebutnya kekerasan tetapi efektif?",
  ui_story_5038_50381301_140_dialog_content = "Dilakukan dengan baik. Jauh lebih mudah berurusan dengan Eclipsites daripada pintunya.",
  ui_story_5038_50381301_141_dialog_content = "Ayo musnahkan mereka!",
  ui_story_5038_50381302_1_dialog_content = "Apa yang sedang terjadi? Apa yang salah?",
  ui_story_5038_50381302_2_dialog_content = "Eclipsites... Mereka ada di geladak!",
  ui_story_5038_50381302_3_dialog_content = "Mereka datang dari kapal di belakang kami!",
  ui_story_5038_50381302_4_dialog_content = "Graaah!",
  ui_story_5038_50381302_5_dialog_content = "Enyahlah, dasar kotor!",
  ui_story_5038_50381302_6_dialog_content = "Graah...",
  ui_story_5038_50381302_7_dialog_content = "Ada terlalu banyak dari mereka...",
  ui_story_5038_50381302_8_dialog_content = "Silakan mundur, Yang Mulia.",
  ui_story_5038_50381302_9_dialog_content = "Biarkan saya menangani pekerjaan kasar seperti ini.",
  ui_story_5038_50381302_10_dialog_content = "Semuanya, berkumpul di buritan!",
  ui_story_5038_50381302_11_dialog_content = "Pegang garis melawan Eclipsites. Jangan biarkan mereka melakukan apa yang mereka suka!",
  ui_story_5038_50381302_12_dialog_content = "Iya!",
  ui_story_5038_50381302_13_dialog_content = "Apa yang terjadi, Tuan Zhong?",
  ui_story_5038_50381302_14_dialog_content = "Mengapa sebuah kapal yang penuh dengan Eclipsites membidik kita?",
  ui_story_5038_50381302_15_dialog_content = "Itu kapal yang sangat besar...",
  ui_story_5038_50381302_16_dialog_content = "Mungkin ombak membawanya secara kebetulan dan jarak pandang yang rendah menambah masalah.",
  ui_story_5038_50381302_17_dialog_content = "Oh tidak, mereka menghancurkan tiang kapal!",
  ui_story_5038_50381302_18_dialog_content = "Awas, sebagian besar geladak telah rusak!",
  ui_story_5038_50381302_19_dialog_content = "Ini buruk, kita harus melakukan sesuatu!",
  ui_story_5038_50381302_20_dialog_content = "Eclipsite Busuk!",
  ui_story_5038_50381302_21_dialog_content = "Ayo bantu, Jiu!",
  ui_story_5038_50381302_22_dialog_content = "Tolong tunggu sebentar.",
  ui_story_5038_50381302_23_dialog_content = "Kenapa?",
  ui_story_5038_50381302_24_dialog_content = "Bertarung di Shadowind hanya akan semakin merusak kapal.",
  ui_story_5038_50381302_25_dialog_content = "Kita harus memindahkan medan pertempuran.",
  ui_story_5038_50381302_26_dialog_content = "Pindah? Maksudmu...",
  ui_story_5038_50381302_27_dialog_content = "Kumpulkan papan dan bangun jembatan ke kapal lain itu.",
  ui_story_5038_50381302_28_dialog_content = "Jika harus ada api, mari kita pastikan bukan kapal kita yang terbakar.",
  ui_story_5038_50381401_1_dialog_content = "Anda tidak dalam kondisi untuk bertarung, tuanku. Harap tetap di sini.",
  ui_story_5038_50381401_2_dialog_content = "Kami memiliki cukup tenaga untuk menyingkirkan Eclipsites.",
  ui_story_5038_50381401_3_dialog_content = "Dia benar. Tidak ada gunanya membuat dirimu terluka.",
  ui_story_5038_50381401_4_dialog_content = "Jangan khawatirkan dirimu dengan itu.",
  ui_story_5038_50381401_5_dialog_content = "Saya tidak akan mengikuti jika saya yakin saya akan menjadi beban.",
  ui_story_5038_50381401_6_dialog_content = "(Jangan salah, ini adalah Shadowind yang asli.)",
  ui_story_5038_50381401_7_dialog_content = "(Kompas sangat dekat. Saya akan mengambilnya kali ini.)",
  ui_story_5038_50381401_8_dialog_content = "(Saya tidak mengingkari janji saya, Tuan Lin.)",
  ui_story_5038_50381401_9_dialog_content = "Ini dia lebih banyak Eclipsites, Yang Mulia.",
  ui_story_5038_50381401_10_dialog_content = "Ada lebih banyak di sini daripada di kapal kami.",
  ui_story_5038_50381401_11_dialog_content = "Tidak masalah, kami akan—",
  ui_story_5038_50381401_12_dialog_content = "Sebentar, tolong mundur beberapa langkah.",
  ui_story_5038_50381401_13_dialog_content = "Jangan terjebak dalam garis api saya.",
  ui_story_5038_50381401_14_dialog_content = "Hah? Tuanku, apa yang kau...",
  ui_story_5038_50381401_15_dialog_content = "<size=50>Api akan membara semuanya menjadi abu!</size>",
  ui_story_5038_50381401_16_dialog_content = "Hati-hati, Yang Mulia!",
  ui_story_5038_50381401_17_dialog_content = "Gaahhhh!",
  ui_story_5038_50381401_18_dialog_content = "Api yang sangat kuat!",
  ui_story_5038_50381401_19_dialog_content = "Semua Eclipsites hangus...",
  ui_story_5038_50381401_20_dialog_content = "Bahkan kabut telah menghilang!",
  ui_story_5038_50381401_21_dialog_content = "Tidak heran Lord Zhong bersikeras untuk datang.",
  ui_story_5038_50381401_22_dialog_content = "Tidak mungkin dia bisa melepaskan sesuatu seperti ini di kapal Shadowind.",
  ui_story_5038_50381401_23_dialog_content = "Kapal tua ini sudah lama hanyut, diterjang ombak, tergerus angin laut yang asin.",
  ui_story_5038_50381401_24_dialog_content = "Itu adalah cangkang dari dirinya yang dulu sekarang. Satu-satunya hal yang masih berlaku adalah bingkainya.",
  ui_story_5038_50381401_25_dialog_content = "Api akan berkobar dengan intens di sini.",
  ui_story_5038_50381401_26_dialog_content = "Besar! Ayo cepat dan tangani Eclipsites dengan api Lord Zhong!",
  ui_story_5038_50381401_27_dialog_content = "Shadowind masih menunggu kita untuk kembali dan membantu.",
  ui_story_5038_50381401_28_dialog_content = "Hati-hati, Yang Mulia, dek yang melemah karena api bisa runtuh.",
  ui_story_5038_50381401_29_dialog_content = "Hmm, kau benar tentang itu...",
  ui_story_5038_50381401_30_dialog_content = "Mari kita berpegangan satu sama lain, Jiu.",
  ui_story_5038_50381401_31_dialog_content = "Dengan begitu, jika salah satu dari kami terpeleset, yang lain dapat membantu.",
  ui_story_5038_50381401_32_dialog_content = "T-Tunggu...",
  ui_story_5038_50381401_33_dialog_content = "Seperti yang Anda katakan, Yang Mulia.",
  ui_story_5038_50381401_34_dialog_content = "Baiklah, kalian berdua, biarkan aku membersihkan jalan di depan untukmu.",
  ui_story_5038_50381401_35_dialog_content = "Ya, mari kita terus bergerak maju.",
  ui_story_5038_50381401_36_dialog_content = "Ada hal lain yang ingin saya lakukan selain menyingkirkan Eclipsites.",
  ui_story_5038_50381401_37_dialog_content = "Haruskah Anda melakukannya di kapal ini?",
  ui_story_5038_50381401_38_dialog_content = "Jika saya benar, ini adalah Shadowind asli.",
  ui_story_5038_50381401_39_dialog_content = "Saya memiliki ikatan tertentu dengan kapal.",
  ui_story_5038_50381401_40_dialog_content = "Oh, jadi ini kapal legendaris yang hilang...",
  ui_story_5038_50381401_41_dialog_content = "Ada barang antik di kapal.",
  ui_story_5038_50381401_42_dialog_content = "Aku harus mengambilnya sebelum kapal terbakar.",
  ui_story_5038_50381401_43_dialog_content = "Kedengarannya seperti sesuatu yang sangat penting.",
  ui_story_5038_50381401_44_dialog_content = "Ya, itu bisa membantu kita kembali ke Longzhou.",
  ui_story_5038_50381401_45_dialog_content = "(Kompas telah diabaikan begitu lama, saya harap tidak apa-apa.)",
  ui_story_5038_50381401_46_dialog_content = "(Agak konyol ketika memikirkannya ...)",
  ui_story_5038_50381401_47_dialog_content = "(Bahwa umur panjang rute antara dua benua menunggangi seekor ikan.)",
  ui_story_5038_50381401_48_dialog_content = "<color=#e8d9bb>*Menginjak langkah kaki*...</color>",
  ui_story_5038_50381401_49_dialog_content = "Hm?",
  ui_story_5038_50381401_50_dialog_content = "Tunggu, sepertinya aku mendengar suara.",
  ui_story_5038_50381401_51_dialog_content = "Sebuah Eclipsite yang bersembunyi mungkin?",
  ui_story_5038_50381401_52_dialog_content = "Tidak, Yang Mulia, kedengarannya seperti...",
  ui_story_5038_50381401_53_dialog_content = "<color=#e8d9bb>Acak, acak ...</color>",
  ui_story_5038_50381401_54_dialog_content = "Suara langkah kaki.",
  ui_story_5038_50381401_55_dialog_content = "Langkah kaki?! Apakah seharusnya ada orang di sini selain kita?",
  ui_story_5038_50381401_56_dialog_content = "Itu adalah kamu.",
  ui_story_5038_50381401_57_dialog_content = "!!!",
  ui_story_5038_50381401_58_dialog_content = "Siapa ini? Siapa yang berbicara?",
  ui_story_5038_50381401_59_dialog_content = "Keluar dan—",
  ui_story_5038_50381401_60_dialog_content = "Kontrol.",
  ui_story_5038_50381401_61_dialog_content = "Ugh!",
  ui_story_5038_50381401_62_dialog_content = "Saya mendapatkan Anda, Yang Mulia!",
  ui_story_5038_50381401_63_dialog_content = "L-Lihat!",
  ui_story_5038_50381401_64_dialog_content = "Tuan Zhong—",
  ui_story_5038_50381401_65_dialog_content = "*Batuk-batuk*",
  ui_story_5038_50381401_66_dialog_content = "Siapa kau?",
  ui_story_5038_50381401_67_dialog_content = "Aku mengenalmu.",
  ui_story_5038_50381401_68_dialog_content = "Tapi aku tidak tahu...",
  ui_story_5038_50381401_69_dialog_content = "Tunggu, kamu punya ekor?!",
  ui_story_5038_50381401_70_dialog_content = "Anda... berada... di... kapal.",
  ui_story_5038_50381401_71_dialog_content = "Itu adalah ekor ikan ular.",
  ui_story_5038_50381401_72_dialog_content = "Itu adalah sifat Lin. Apakah Anda Lin?",
  ui_story_5038_50381401_73_dialog_content = "Anda... membantu... Lins.",
  ui_story_5038_50381401_74_dialog_content = "Tidak, Anda tidak mungkin menjadi seorang Lin.",
  ui_story_5038_50381401_75_dialog_content = "Tidak ada yang selamat dari pembantaian itu.",
  ui_story_5038_50381401_76_dialog_content = "Satu-satunya hal yang akan muncul di sini adalah milik Lin.",
  ui_story_5038_50381401_77_dialog_content = "Namamu.",
  ui_story_5038_50381401_78_dialog_content = "Zhong ... Xu.",
  ui_story_5038_50381401_79_dialog_content = "Anda itu.",
  ui_story_5038_50381401_80_dialog_content = "Harta karun yang paling dihargai oleh Lins.",
  ui_story_5038_50381401_81_dialog_content = "Kamu adalah Yo.",
  ui_story_5038_50381401_82_dialog_content = "Siapa anak itu? Dan mengapa dia menyakiti Tuan Zhong?",
  ui_story_5038_50381401_83_dialog_content = "Hati-hati, dia sangat kuat.",
  ui_story_5038_50381401_84_dialog_content = "Bagaimana bisa anak kecil seperti itu...",
  ui_story_5038_50381401_85_dialog_content = "Mungkinkah dia seorang fiendling?",
  ui_story_5038_50381401_86_dialog_content = "Aku tidak percaya ini adalah penampilanmu sekarang...",
  ui_story_5038_50381401_87_dialog_content = "Mengapa Anda menyerang saya?",
  ui_story_5038_50381401_88_dialog_content = "Lins... pantas... untuk... mati.",
  ui_story_5038_50381401_89_dialog_content = "... Seperti yang saya duga, Anda membenci mereka.",
  ui_story_5038_50381401_90_dialog_content = "Karena mereka menjadikanmu seorang tahanan.",
  ui_story_5038_50381401_91_dialog_content = "Semuanya... di... di... kapal.",
  ui_story_5038_50381401_92_dialog_content = "Harus mati.",
  ui_story_5038_50381401_93_dialog_content = "Saya, bersama dengan keluarga Lin, telah lama meramalkan kebencian Anda yang tak terelakkan.",
  ui_story_5038_50381401_94_dialog_content = "Tetapi tidak seorang pun dari kami berharap suatu hari nanti akan berhadapan dengan kebencian itu.",
  ui_story_5038_50381401_95_dialog_content = "Kapal... pantas... mati... paling.",
  ui_story_5038_50381401_96_dialog_content = "Kebencian Anda dibenarkan, jadi Anda dipersilakan untuk itu.",
  ui_story_5038_50381401_97_dialog_content = "Kami mewarisi warisan pendahulu kami, serta hutang mereka.",
  ui_story_5038_50381401_98_dialog_content = "Beberapa hanya kurang beruntung dari yang lain dan terjebak di antara keduanya.",
  ui_story_5038_50381401_99_dialog_content = "Ini tampaknya menjadi kekacauan bagus lainnya yang harus saya keluarkan dari Anda, Lin, teman lama.",
  ui_story_5038_50381401_100_dialog_content = "Semua... dari... kalian... adalah...",
  ui_story_5038_50381401_101_dialog_content = "musuh... dari... laut.",
  ui_story_5038_50381401_102_dialog_content = "Kamu... dan... ini... kapal.",
  ui_story_5038_50381401_103_dialog_content = "Tenggelam... ke... lautan.",
  ui_story_5038_50381401_104_dialog_content = "Apa yang terjadi?!",
  ui_story_5038_50381401_105_dialog_content = "Tunggu, Yoh!",
  ui_story_5038_50381401_106_dialog_content = "I-Itu suara Liqing!",
  ui_story_5038_50381401_107_dialog_content = "Huff... Akhirnya berhasil menyusulmu!",
  ui_story_5038_50381401_108_dialog_content = "Li... qing...",
  ui_story_5038_50381401_109_dialog_content = "Jadi seperti inilah tampilan The Compass.",
  ui_story_5038_50381401_110_dialog_content = "Mengapa semua orang di sini? Apa yang terjadi?",
  ui_story_5038_50381401_111_dialog_content = "Kalian bertiga telah berada di sini selama ini?",
  ui_story_5038_50381401_112_dialog_content = "Apa yang sedang terjadi? Dan siapa anak itu?",
  ui_story_5038_50381401_113_dialog_content = "Itulah Kompas yang kami cari.",
  ui_story_5038_50381401_114_dialog_content = "Kompas?!",
  ui_story_5038_50381401_115_dialog_content = "Tak satu pun dari peramal saya memilih untuk mengungkapkannya kepada saya ...",
  ui_story_5038_50381401_116_dialog_content = "Tunggu sebentar, bacaannya!",
  ui_story_5038_50381401_117_dialog_content = "Saya dihadapkan dengan kelompok tiga binatang yang sangat aneh: tikus yang ragu-ragu, monyet yang bodoh, dan kelinci yang cerdik.",
  ui_story_5038_50381401_118_dialog_content = "\"Yang ilusi menjadi nyata, ketika yang nyata menjadi ilusi.\" Pada dasarnya, itu memberitahu kita untuk <color=#FFB400>mengganti</color> yang telah kita hilangkan.",
  ui_story_5038_50381401_119_dialog_content = "Jadi itu maksudnya!",
  ui_story_5038_50381401_120_dialog_content = "Apa yang Anda mengoceh tentang?",
  ui_story_5038_50381401_121_dialog_content = "Tongkat meramalkan seluruh perjalanan ini.",
  ui_story_5038_50381401_122_dialog_content = "\"Tikus yang ragu-ragu\" adalah kapten yang bimbang antara menemukan Kompas dan pergi ke Longzhou.",
  ui_story_5038_50381401_123_dialog_content = "\"Kelinci yang cerdik\"... Anda tahu pepatah: \"Kelinci yang cerdik memiliki tiga tempat persembunyian.\" Itu berbicara tentang Kompas. Kami tidak tahu apa itu, apa fungsinya, atau di mana itu.",
  ui_story_5038_50381401_124_dialog_content = "Tongkat kedua, \"monyet bodoh\", mendamaikan tongkat pertama dan terakhir.",
  ui_story_5038_50381401_125_dialog_content = "Hanya dengan menjadi orang bodoh, menapaki jalan yang tidak mungkin dan melakukan yang tidak mungkin, perjalanan kita dapat diakhiri.",
  ui_story_5038_50381401_126_dialog_content = "Saat Anda menjumlahkan ketiga trigram, Anda dapat melihat bahwa yang akan kami ganti bukanlah bagian dari kapal.",
  ui_story_5038_50381401_127_dialog_content = "Itu berbicara tentang seluruh kapal itu sendiri!",
  ui_story_5038_50381401_128_dialog_content = "Apa yang kamu coba lakukan, Yoh?",
  ui_story_5038_50381401_129_dialog_content = "Apakah Anda mencoba untuk membunuhnya?",
  ui_story_5038_50381401_130_dialog_content = "...",
  ui_story_5038_50381401_131_dialog_content = "Bukan hanya saya. Dia ingin menenggelamkan Shadowind juga.",
  ui_story_5038_50381401_132_dialog_content = "Kenapa kamu ingin melakukan itu?",
  ui_story_5038_50381401_133_dialog_content = "Aku tahu betapa sulitnya bagimu terkurung di tangki kecil.",
  ui_story_5038_50381401_134_dialog_content = "Dan aku tahu kau menyimpan dendam. Anda merasa marah dan bahkan dengki.",
  ui_story_5038_50381401_135_dialog_content = "Tapi tidak semua orang itu sama, tidak semua orang berusaha menyakitimu.",
  ui_story_5038_50381401_136_dialog_content = "Anda seharusnya tidak membuat orang yang tidak bersalah membayar dosa orang lain!",
  ui_story_5038_50381401_137_dialog_content = "Kamu... seharusnya... tidak... keluar... keluar.",
  ui_story_5038_50381401_138_dialog_content = "Kenapa tidak?",
  ui_story_5038_50381401_139_dialog_content = "Anda akan mati.",
  ui_story_5038_50381401_140_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5038_50381401_141_dialog_content = "Oh tidak, deknya putus!",
  ui_story_5038_50381401_142_dialog_content = "Renungkanlah, Yoh! Apakah ini yang benar-benar Anda inginkan?",
  ui_story_5038_50381401_143_dialog_content = "Tidak ada seorang pun di sini yang melakukan kesalahan, terutama saya!",
  ui_story_5038_50381401_144_dialog_content = "Apakah Anda lupa bagaimana saya memberi Anda makan setiap hari?",
  ui_story_5038_50381401_145_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5038_50381401_146_dialog_content = "Kamu-Kamu—!",
  ui_story_5038_50381401_X146_dialog_content = "Dia sudah melewati titik mendengarkan siapa pun lagi. Jika kita tidak menghentikannya, semua orang di kapal akan binasa.",
  ui_story_5038_50381401_X147_dialog_content = "Mari kita coba mencari cara untuk menghentikannya terlebih dahulu.",
  ui_story_5038_50381401_147_dialog_content = "Itu sia-sia, nak. Sedikit niat baik yang dia miliki terhadap Anda tidak cukup untuk memadamkan kebenciannya.",
  ui_story_5038_50381401_148_dialog_content = "Apakah Anda berharap untuk menggunakan makanan ikan yang Anda berikan padanya sebelumnya untuk ditukar dengan nyawa semua orang?",
  ui_story_5038_50381401_149_dialog_content = "Namun…",
  ui_story_5038_50381401_150_dialog_content = "Shadowind tidak akan menyerah begitu saja.",
  ui_story_5038_50381401_151_dialog_content = "Apakah kami mengatakan Anda bisa mengamuk dan melakukan apa pun yang Anda inginkan?",
  ui_story_5038_50381401_152_dialog_content = "Ya, kami tidak akan membiarkan siapa pun merusak kapal!",
  ui_story_5038_50381401_153_dialog_content = "Apa menurutmu... tidak apa-apa memukul anak kecil?",
  ui_story_5038_50381401_154_dialog_content = "Dia seorang fiendling dan mungkin cukup tua untuk menjadi kakekmu.",
  ui_story_5038_50381401_155_dialog_content = "Dia akan menyerang!",
  ui_story_5038_50381401_156_dialog_content = "Bersiaplah untuk bertarung!",
  ui_story_5038_50381402_1_dialog_content = "Keluar dari jalan.",
  ui_story_5038_50381402_2_dialog_content = "Dia kehilangan banyak kekuatan!",
  ui_story_5038_50381402_3_dialog_content = "Menyerang kami sepertinya akan mengambil banyak darinya.",
  ui_story_5038_50381402_4_dialog_content = "Ya. Dia seorang fiendling baru dan masih tidak tahu bagaimana mengatur kekuatannya.",
  ui_story_5038_50381402_5_dialog_content = "Dia membuang terlalu banyak energi untuk serangan sia-sia.",
  ui_story_5038_50381402_6_dialog_content = "Kita harus menaklukkannya sebelum dia mendapat kesempatan untuk membalas.",
  ui_story_5038_50381402_7_dialog_content = "Tentu, biarkan aku membantu!",
  ui_story_5038_50381402_8_dialog_content = "Tenggelam... sekarang.",
  ui_story_5038_50381402_9_dialog_content = "<color=#e8d9bb>Krak!</color>",
  ui_story_5038_50381402_10_dialog_content = "D-Dia menyerang lambung kapal!",
  ui_story_5038_50381402_11_dialog_content = "Dan jika saya melihatnya dengan benar, ikan ular sedang berenang ke sini!",
  ui_story_5038_50381402_12_dialog_content = "Bergeraklah, Liqing.",
  ui_story_5038_50381402_13_dialog_content = "Siap!",
  ui_story_5038_50381402_14_dialog_content = "Jadi kita beralih dari teman menjadi sesama teman, ya, Yoh?",
  ui_story_5038_50381402_15_dialog_content = "Li... qing...",
  ui_story_5038_50381402_16_dialog_content = "Anda telah belajar berbicara.",
  ui_story_5038_50381402_17_dialog_content = "Jangan... hentikan... aku.",
  ui_story_5038_50381402_18_dialog_content = "Sayang sekali kami tidak pernah memiliki kesempatan untuk berbicara.",
  ui_story_5038_50381402_19_dialog_content = "Keluar... dari... jalan.",
  ui_story_5038_50381402_20_dialog_content = "Apa masalah Anda? Saya seorang fiendling yang lebih berpengalaman dari Anda!",
  ui_story_5038_50381402_21_dialog_content = "Masih banyak hal yang perlu kamu pelajari!",
  ui_story_5038_50381402_22_dialog_content = "Sebagai seniormu, aku ingin mengajarimu, tapi...",
  ui_story_5038_50381402_23_dialog_content = "Itu harus menunggu sampai setelah aku mengalahkanmu!",
  ui_story_5038_50381402_24_dialog_content = "(Sekarang, Yuebai!)",
  ui_story_5038_50381402_25_dialog_content = "!!!",
  ui_story_5038_50381402_26_dialog_content = "Jangan menyentuh kapalku.",
  ui_story_5038_50381402_27_dialog_content = "Ugh...",
  ui_story_5038_50381402_28_dialog_content = "Dia terluka! Dapatkan dia sekarang!",
  ui_story_5038_50381402_29_dialog_content = "Oke! Aku mendapatkan lengan kirinya!",
  ui_story_5038_50381402_30_dialog_content = "Saya akan mengambil tangan kanan, Yang Mulia.",
  ui_story_5038_50381402_31_dialog_content = "K-Kalian tidak perlu terlalu kasar...",
  ui_story_5038_50381402_32_dialog_content = "Dia benar-benar terkuras.",
  ui_story_5038_50381402_33_dialog_content = "Dia adalah?",
  ui_story_5038_50381402_34_dialog_content = "Desis... desis...",
  ui_story_5038_50381402_35_dialog_content = "Ikan tidak berteriak. Dia belum belajar bagaimana menangis kesakitan.",
  ui_story_5038_50381402_36_dialog_content = "Fiuh, akhirnya kita menang.",
  ui_story_5038_50381402_37_dialog_content = "Apakah ini berarti kita memiliki Kompas sekarang?",
  ui_story_5038_50381402_38_dialog_content = "Ya. Dia adalah Kompas, tanpa keraguan.",
  ui_story_5038_50381402_39_dialog_content = "Menjadi seorang fiendling tidak mengubah perannya sebagai The Compass.",
  ui_story_5038_50381402_40_dialog_content = "Jadi apa yang kita lakukan sekarang?",
  ui_story_5038_50381402_41_dialog_content = "...",
  ui_story_5038_50381402_42_dialog_content = "...",
  ui_story_5038_50381402_43_dialog_content = "Menurut prosedur, kita harus mengurungnya di Shadowind.",
  ui_story_5038_50381402_44_dialog_content = "Kemudian minta dia untuk mengirimkan sinyal untuk kembali.",
  ui_story_5038_50381402_45_dialog_content = "Begitu serpentfish mendapat sinyal, mereka akan berkumpul di sekitar kapal dan mengantar kita kembali ke Longzhou.",
  ui_story_5038_50381402_46_dialog_content = "Pelayaran ini akan bebas dari bahaya lebih lanjut, sama seperti pelayaran yang tak terhitung jumlahnya sebelumnya.",
  ui_story_5038_50381402_47_dialog_content = "Huh...",
  ui_story_5038_50381402_48_dialog_content = "Haruskah kita mengurung seorang anak?",
  ui_story_5038_50381402_49_dialog_content = "Pelayaran yang aman kedengarannya bagus, tetapi saya tidak sepenuhnya nyaman dengan opsi ini.",
  ui_story_5038_50381402_50_dialog_content = "Ya, apalagi saat kita baru saja menyaksikan penghinaannya terhadap kita.",
  ui_story_5038_50381402_51_dialog_content = "Nenek moyang Lin mengilhami kebencian, yang semakin dalam dengan setiap penumpang yang pernah naik.",
  ui_story_5038_50381402_52_dialog_content = "Mereka semua memilih untuk percaya bahwa Kompas hanyalah seekor ikan, tidak dapat menyimpan dendam.",
  ui_story_5038_50381402_53_dialog_content = "Semua orang percaya bahwa jika tidak ada kebencian, tidak ada kejahatan, dan tanpa kejahatan, tidak perlu ada rasa bersalah.",
  ui_story_5038_50381402_54_dialog_content = "Tapi sudah terlambat untuk penyesalan saat kebencian terwujud di depan matamu.",
  ui_story_5038_50381402_55_dialog_content = "Apakah Anda merasa menyesal, Tuan Zhong?",
  ui_story_5038_50381402_56_dialog_content = "Anda merasa mengurung Kompas juga salah, bukan?",
  ui_story_5038_50381402_57_dialog_content = "Saya menyesali banyak hal.",
  ui_story_5038_50381402_58_dialog_content = "Membantai semua orang itu salah, dan memperbudak Kompas itu salah.",
  ui_story_5038_50381402_59_dialog_content = "Memindahkan masalah yang seharusnya diselesaikan di darat ke laut adalah bagaimana kami berakhir di posisi ini.",
  ui_story_5038_50381402_60_dialog_content = "Jadi, apakah kita akan menempuh jalan yang salah yang sama...?",
  ui_story_5038_50381402_61_dialog_content = "Mengingat usia saya, saya tidak memiliki masalah untuk menebus dosa-dosa saya dengan hidup saya.",
  ui_story_5038_50381402_62_dialog_content = "Tetapi ada lebih banyak orang yang hadir di sini daripada saya sendiri.",
  ui_story_5038_50381402_63_dialog_content = "Apakah kita memiliki harapan untuk mencapai Longzhou tanpa mengeksploitasi Kompas?",
  ui_story_5038_50381402_64_dialog_content = "Hmm…",
  ui_story_5038_50381402_65_dialog_content = "Kapalnya rusak dan kami masih belum tahu seberapa parah kerusakannya...",
  ui_story_5038_50381402_66_dialog_content = "Saya tahu apa yang dimaksud Zhong Xu, karena saya sendiri sudah banyak memikirkannya.",
  ui_story_5038_50381402_67_dialog_content = "Lebih sering daripada tidak, tangan Anda diikat saat berada di laut.",
  ui_story_5038_50381402_68_dialog_content = "Saya menganggap Yoh sebagai teman saya dan ingin melihatnya bebas, tapi...",
  ui_story_5038_50381402_69_dialog_content = "Saya tidak bisa membayar harga untuk keputusan itu.",
  ui_story_5038_50381402_70_dialog_content = "Harga...",
  ui_story_5038_50381402_71_dialog_content = "(Tidak ada yang mengatakan sepatah kata pun sekarang.)",
  ui_story_5038_50381402_72_dialog_content = "(Kita semua saling bertukar pandang untuk mencoba menutupi ketidakberdayaan yang kita rasakan.)",
  ui_story_5038_50381402_73_dialog_content = "(Seolah-olah kita menunjukkan penyesalan melalui kesunyian.)",
  ui_story_5038_50381402_74_dialog_content = "(Kami tahu itu salah, tapi kami tidak punya pilihan lain.)",
  ui_story_5038_50381402_75_dialog_content = "Jangan terlalu murung.",
  ui_story_5038_50381402_76_dialog_content = "Kami menemukan Kompas. Kita harus senang bahwa kita menyelesaikan misi kita.",
  ui_story_5038_50381402_77_dialog_content = "Fakta bahwa kita dapat menyelesaikan perjalanan kita memang patut dirayakan, Kapten.",
  ui_story_5038_50381402_78_dialog_content = "Tapi pikiran mengunci anak itu...",
  ui_story_5038_50381402_79_dialog_content = "Siapa bilang kita mengurungnya? Apakah itu perlu?",
  ui_story_5038_50381402_80_dialog_content = "Hah?",
  ui_story_5038_50381402_81_dialog_content = "Apa maksudmu, Kapten?",
  ui_story_5038_50381402_82_dialog_content = "Kami harus menemukan Kompas untuk memiliki harapan mencapai Longzhou.",
  ui_story_5038_50381402_83_dialog_content = "Sekarang setelah kami menemukannya, kami memiliki banyak opsi untuk bagaimana kami dapat menggunakannya.",
  ui_story_5038_50381402_84_dialog_content = "Jelas tidak ada dari kita yang setuju dengan cara keluarga Lin melakukannya.",
  ui_story_5038_50381402_85_dialog_content = "Jadi saya akan mengeksplorasi opsi lain.",
  ui_story_5038_50381402_86_dialog_content = "Betulkah? Kami benar-benar tidak harus menahan Yoh?",
  ui_story_5038_50381402_87_dialog_content = "...",
  ui_story_5038_50381402_88_dialog_content = "Katakan padaku, apakah kamu bersedia menjadi tamu di kapal Shadowind?",
  ui_story_5038_50381402_89_dialog_content = "...Tidak.",
  ui_story_5038_50381402_90_dialog_content = "Tentu saja tidak.",
  ui_story_5038_50381402_91_dialog_content = "Maka saya kira ini adalah di mana kita berpisah.",
  ui_story_5038_50381402_92_dialog_content = "Kapal ini akan segera tenggelam. Anda harus kembali ke laut.",
  ui_story_5038_50381402_93_dialog_content = "Biarkan dia pergi. Kami kembali ke kapal kami.",
  ui_story_5038_50381402_94_dialog_content = "A-Apakah kamu yakin?",
  ui_story_5038_50381402_95_dialog_content = "Tidak mungkin menemukannya lagi.",
  ui_story_5038_50381402_96_dialog_content = "Dia seekor ikan. Dia jauh lebih cocok untuk lautan daripada kapal.",
  ui_story_5038_50381402_97_dialog_content = "Ayo pergi. Kabutnya hilang. Kita harus melanjutkan perjalanan.",
  ui_story_5038_50381402_98_dialog_content = "Sudahkah Anda mengambil keputusan?",
  ui_story_5038_50381402_99_dialog_content = "Ya.",
  ui_story_5038_50381402_100_dialog_content = "Apakah Anda akan menghentikan saya, Tuan Zhong?",
  ui_story_5038_50381402_101_dialog_content = "Saya berjanji pada Tuan Lin tua untuk melindungi harta keluarga.",
  ui_story_5038_50381402_102_dialog_content = "Saya telah memenuhi janji itu dengan mengantarkan Kompas kepada anggota keluarga Lin.",
  ui_story_5038_50381402_103_dialog_content = "Selama Anda menyadari konsekuensi dari keputusan Anda, saya akan menghormatinya.",
  ui_story_5038_50381402_104_dialog_content = "Ayo, Anda mendengar perintah kapten.",
  ui_story_5038_50381402_105_dialog_content = "Dia tahu lebih banyak dari kita dalam hal berlayar.",
  ui_story_5038_50381402_106_dialog_content = "Ya, benar... Kita tidak perlu khawatir.",
  ui_story_5038_50381402_107_dialog_content = "Ayo pergi... Bergerak, PlayerName, kenapa kamu hanya berdiri di sana?",
  ui_story_5038_50381402_108_dialog_content = "Oh, aku hanya menonton ikan ular.",
  ui_story_5038_50381402_109_dialog_content = "Sungguh spektakuler bagaimana mereka terus mengitari kapal.",
  ui_story_5038_50381402_110_dialog_content = "Seperti mereka hanya menunggu sampai tenggelam.",
  ui_story_5038_50381402_111_dialog_content = "Oh, jangan mulai membuat puisi di sini atau yang lainnya. Anda dapat melakukannya dari Shadowind.",
  ui_story_5038_50381402_112_dialog_content = "Ayo bergerak.",
  ui_story_5038_50381402_113_dialog_content = "Oke, aku datang.",
  ui_story_5038_50381402_114_dialog_content = "Selamat, Yoh, kamu bebas sekarang!",
  ui_story_5038_50381402_115_dialog_content = "Gratis...",
  ui_story_5038_50381402_116_dialog_content = "Apakah kamu tidak mengerti? Mereka bilang mereka membiarkanmu pergi.",
  ui_story_5038_50381402_117_dialog_content = "Tidak mudah menjadi fiendling. Ingatlah untuk terus berlatih berbicara.",
  ui_story_5038_50381402_118_dialog_content = "Mencoba untuk berbicara dengan Anda melelahkan.",
  ui_story_5038_50381402_119_dialog_content = "Biarkan aku pergi?",
  ui_story_5038_50381402_120_dialog_content = "Ya, tidakkah kamu mengerti?",
  ui_story_5038_50381402_121_dialog_content = "Pergilah dan pergilah ke mana pun Anda seharusnya berada.",
  ui_story_5038_50381402_122_dialog_content = "Aku…",
  ui_story_5038_50381402_123_dialog_content = "Aku harus pergi. Aku tidak akan jatuh ke dalam air.",
  ui_story_5038_50381402_124_dialog_content = "Tapi jangan pernah lupa bahwa Liqing adalah temanmu.",
  ui_story_5038_50381402_125_dialog_content = "Dah!",
  ui_story_5038_50381402_126_dialog_content = "Itu dia, Kapten!",
  ui_story_5038_50381402_127_dialog_content = "Kapal itu ditabrak, lalu ditumpangi Eclipsites, dan mengalami banyak kerusakan.",
  ui_story_5038_50381402_128_dialog_content = "Kami sedang bekerja keras mencoba menyatukannya kembali...",
  ui_story_5038_50381402_129_dialog_content = "Dipahami. Jangan berhenti dengan perbaikan, tetapi pastikan untuk segera membuka layar.",
  ui_story_5038_50381402_130_dialog_content = "Kami sedang berlayar.",
  ui_story_5038_50381402_131_dialog_content = "Sekarang? Bukankah kita harus berkumpul kembali dulu?",
  ui_story_5038_50381402_132_dialog_content = "Kami tidak punya waktu.",
  ui_story_5038_50381402_133_dialog_content = "Serpentfish akan segera memulai perjalanan pulang dan kita harus mengikuti di belakang mereka.",
  ui_story_5038_50381402_134_dialog_content = "Ikan ular?",
  ui_story_5038_50381402_135_dialog_content = "Memang benar, ikan ular mulai berenang!",
  ui_story_5038_50381402_136_dialog_content = "Mereka semua menuju ke arah yang sama!",
  ui_story_5038_50381402_137_dialog_content = "Di situlah letak Longzhou.",
  ui_story_5038_50381402_138_dialog_content = "Tidak ada apa pun di lautan yang ingin pulang lebih dari yang mereka lakukan.",
  ui_story_5038_50381402_139_dialog_content = "Oh, aku mengerti!",
  ui_story_5038_50381402_140_dialog_content = "Anda tahu bahwa begitu Anda melepaskan Yoh, ikan ular akan melanjutkan perjalanan aslinya.",
  ui_story_5038_50381402_141_dialog_content = "Mereka bisa membawa kita ke rute tercepat kembali ke Longzhou!",
  ui_story_5038_50381402_142_dialog_content = "Kedengarannya sederhana, tetapi mengikuti serpentfish lebih sulit dari yang Anda pikirkan.",
  ui_story_5038_50381402_143_dialog_content = "Saya akan membutuhkan bantuan semua orang di bagian terakhir perjalanan ini.",
  ui_story_5038_50381402_144_dialog_content = "Kamu dapat mengandalkannya!",
  ui_story_5038_50381402_145_dialog_content = "Oh tidak, kami membocorkan lagi...",
  ui_story_5038_50381402_146_dialog_content = "Kami membutuhkan lebih banyak tangan di geladak!",
  ui_story_5038_50381402_147_dialog_content = "Setiap anggota kru terlalu sibuk untuk membantu saat ini.",
  ui_story_5038_50381402_148_dialog_content = "Akan sangat sulit bagi Shadowind yang babak belur untuk mengarungi lautan yang ganas.",
  ui_story_5038_50381402_149_dialog_content = "Akankah ini bertahan?",
  ui_story_5038_50381402_150_dialog_content = "Retak yang kita tutup sebelumnya bocor lagi.",
  ui_story_5038_50381402_151_dialog_content = "Kami bekerja keras untuk menyelamatkan air, tetapi levelnya masih naik.",
  ui_story_5038_50381402_152_dialog_content = "Apa yang bisa kita lakukan sekarang...",
  ui_story_5038_50381402_153_dialog_content = "Sudahlah, karena semua orang sudah cukup sibuk.",
  ui_story_5038_50381402_154_dialog_content = "Kami hanya harus menjamin lebih cepat.",
  ui_story_5038_50381402_155_dialog_content = "Lihat, saya punya ember di masing-masing tangan sekarang.",
  ui_story_5038_50381402_156_dialog_content = "Tunggu sampai saya mendapatkan satu di mulut saya, maka saya dapat menjamin air senilai tiga orang!",
  ui_story_5038_50381402_157_dialog_content = "A-Apakah itu akan berhasil?",
  ui_story_5038_50381402_158_dialog_content = "Itu harus. Semua orang habis-habisan karena kita begitu dekat.",
  ui_story_5038_50381402_159_dialog_content = "Semuanya akan baik-baik saja selama kapal masih bisa berlayar dengan kecepatan penuh.",
  ui_story_5038_50381402_160_dialog_content = "Anda harus pergi dan biarkan saya bekerja!",
  ui_story_5038_50381402_161_dialog_content = "Siapa yang punya ember kosong? Berikan saya satu!",
  ui_story_5038_50381402_162_dialog_content = "Sebelah sini, PlayerName!",
  ui_story_5038_50381402_163_dialog_content = "Tolong bantu saya!",
  ui_story_5038_50381402_164_dialog_content = "Apa yang terjadi, Dantang? Apa yang kamu lakukan...?",
  ui_story_5038_50381402_165_dialog_content = "Kerekan yang menahan layar pada tempatnya rusak, jadi sekarang tali harus diawaki dengan tangan.",
  ui_story_5038_50381402_166_dialog_content = "Saya melakukannya sebelumnya, tetapi sekarang ...",
  ui_story_5038_50381402_167_dialog_content = "Angin bertiup kencang dan secara fisik membebani saya.",
  ui_story_5038_50381402_168_dialog_content = "Oh begitu! Saya dapat membantu.",
  ui_story_5038_50381402_169_dialog_content = "Jadi aku terus menariknya seperti ini?",
  ui_story_5038_50381402_170_dialog_content = "Ya, seperti itu.",
  ui_story_5038_50381402_171_dialog_content = "Tanganmu merah semua... Apakah kamu baik-baik saja?",
  ui_story_5038_50381402_172_dialog_content = "Tidak masalah. Itu hanya karena saya tidak pernah melakukan pekerjaan fisik seperti ini.",
  ui_story_5038_50381402_173_dialog_content = "Saya akan benar-benar tidak berguna jika saya bahkan tidak bisa menangani tugas kecil ini.",
  ui_story_5038_50381402_174_dialog_content = "Tapi kita tidak tahu berapa lama lagi kita masih punya. Tanganmu...",
  ui_story_5038_50381402_175_dialog_content = "Terus? Bahkan Shadowind belum menyerah.",
  ui_story_5038_50381402_176_dialog_content = "Lempar peti ini ke laut!",
  ui_story_5038_50381402_177_dialog_content = "Iya!",
  ui_story_5038_50381402_178_dialog_content = "Wow, rasanya membebaskan membuang barang ke laut!",
  ui_story_5038_50381402_179_dialog_content = "Dan ini juga! Lemparkan!",
  ui_story_5038_50381402_180_dialog_content = "Kami membuang semua selimut?",
  ui_story_5038_50381402_181_dialog_content = "Ya, kita tidak akan tidur untuk sementara waktu.",
  ui_story_5038_50381402_182_dialog_content = "Baiklah, ini juga masuk ke laut!",
  ui_story_5038_50381402_183_dialog_content = "Kehilangan segala sesuatu yang tidak penting. Setiap bit penting!",
  ui_story_5038_50381402_184_dialog_content = "Kami berjuang melawan laut itu sendiri untuk waktu yang lebih lama!",
  ui_story_5038_50381402_185_dialog_content = "Benar bahwa.",
  ui_story_5038_50381402_186_dialog_content = "Buang, singkirkan semuanya!",
  ui_story_5038_50381402_187_dialog_content = "Dan semua meja, kursi, dan perabotan!",
  ui_story_5038_50381402_188_dialog_content = "(Orang-orang di kapal tidak pernah lebih sibuk.)",
  ui_story_5038_50381402_189_dialog_content = "(Setiap anggota kru, dan setiap bagian kapal, dikerjakan secara maksimal.)",
  ui_story_5038_50381402_190_dialog_content = "(Ada dua kemungkinan hasil bagi kita: Tenggelam, atau Longzhou.)",
  ui_story_5038_50381402_191_dialog_content = "(Ini pertarungan antara apa yang realistis dan apa yang idealis.)",
  ui_story_5038_50381402_192_dialog_content = "(Jauh di luar, ke arah daratan, matahari terbit di cakrawala, saat kapal kami terus tenggelam.)",
  ui_story_5038_50381402_193_dialog_content = "(Alam semesta sedang menunggu dengan cemas untuk mengungkapkan kepada kita nasib terakhir kita.)",
  ui_story_5038_50381402_194_dialog_content = "Kami sudah selesai, seluruh palka kebanjiran!",
  ui_story_5038_50381402_195_dialog_content = "Ada ide, pelaut veteran?",
  ui_story_5038_50381402_196_dialog_content = "Semuanya banjir...",
  ui_story_5038_50381402_197_dialog_content = "Tidak ada yang bisa kita lakukan. Jika palka kebanjiran, selanjutnya...",
  ui_story_5038_50381402_198_dialog_content = "Wah, ada air di geladak!",
  ui_story_5038_50381402_199_dialog_content = "Apa yang harus kita lakukan sekarang...",
  ui_story_5038_50381402_200_dialog_content = "K-Kami tenggelam...",
  ui_story_5038_50381402_201_dialog_content = "Apa yang kita lakukan, apa yang kita lakukan...",
  ui_story_5038_50381402_202_dialog_content = "Kapten! Kapten!",
  ui_story_5038_50381402_203_dialog_content = "Kamu mau pergi kemana? Apakah Anda melihat apa yang terjadi—",
  ui_story_5038_50381402_204_dialog_content = "Jangan panik. Tunggu saja di dek.",
  ui_story_5038_50381402_205_dialog_content = "Shadowind tidak akan tenggelam.",
  ui_story_5038_50381402_206_dialog_content = "<color=#e8d9bb>Dor! Dor! Dor!</color>",
  ui_story_5038_50381402_207_dialog_content = "A-Apa itu?",
  ui_story_5038_50381402_208_dialog_content = "Sesuatu menabrak bagian bawah kapal...",
  ui_story_5038_50381402_209_dialog_content = "Tunggu sebentar! Kalian merasakan itu? Sepertinya kita akan naik!",
  ui_story_5038_50381402_210_dialog_content = "Kamu benar! Apa yang terjadi-",
  ui_story_5038_50381402_211_dialog_content = "<color=#e8d9bb>Wuuss!</color>",
  ui_story_5038_50381402_212_dialog_content = "Apakah kita terbang?!",
  ui_story_5038_50381402_213_dialog_content = "L-Lihat ke sana! Itu ikan, banyak ikan ular!",
  ui_story_5038_50381402_214_dialog_content = "Mereka membawa kapal di punggung mereka!",
  ui_story_5038_50381402_215_dialog_content = "Ya ampun, betapa spektakulernya!",
  ui_story_5038_50381402_216_dialog_content = "Sudah kubilang ikan ular jauh lebih cocok di lautan daripada di kapal.",
  ui_story_5038_50381402_217_dialog_content = "Ya, Yoh membantu kami!",
  ui_story_5038_50381402_218_dialog_content = "Kamu disana, Yo?",
  ui_story_5038_50381402_219_dialog_content = "Terima kasih!!!",
  ui_story_5038_50381402_220_dialog_content = "Apa menurutmu ini akan terjadi saat kau membiarkan Yoh pergi, Yuebai?",
  ui_story_5038_50381402_221_dialog_content = "Tidak. Tidak ada yang bisa memprediksi arah laut yang fana.",
  ui_story_5038_50381402_222_dialog_content = "Yang saya tahu adalah kami melakukan yang terbaik, dan mencapai semua tujuan kami.",
  ui_story_5038_50381402_223_dialog_content = "Kami pasti akan mencapai Longzhou.",
  ui_story_5038_50381501_1_dialog_content = "Apakah Tuan Zhong sudah datang?",
  ui_story_5038_50381501_2_dialog_content = "Cepat, bawa dia ke sini.",
  ui_story_5038_50381501_3_dialog_content = "Datang, datang! Astaga, kalian semua hanya menyuruh orang berkeliling.",
  ui_story_5038_50381501_4_dialog_content = "Apa yang kamu lakukan, Liqing?",
  ui_story_5038_50381501_5_dialog_content = "Kami tidak ingin Anda melewatkan pemandangan menakjubkan.",
  ui_story_5038_50381501_6_dialog_content = "Lihat ke sana. Apa yang kamu lihat?",
  ui_story_5038_50381501_7_dialog_content = "Itu…?",
  ui_story_5038_50381501_8_dialog_content = "Kami pulang?",
  ui_story_5038_50381501_9_dialog_content = "Ya, kami pulang! Itu Longzhou!",
  ui_story_5038_50381501_10_dialog_content = "Apakah kamu kehilangannya?",
  ui_story_5038_50381501_11_dialog_content = "Longzhou...",
  ui_story_5038_50381501_12_dialog_content = "Dalam hidup saya, tanah di bawah kaki saya jarang menjadi Longzhou.",
  ui_story_5038_50381501_13_dialog_content = "Saya tidak berharap diri saya merasakan begitu banyak nostalgia setelah mendengar Anda mengungkitnya.",
  ui_story_5038_50381501_14_dialog_content = "Kami telah pergi terlalu lama.",
  ui_story_5038_50381501_15_dialog_content = "Ya. Kami telah melalui banyak hal dan melakukan perjalanan sejauh ini.",
  ui_story_5038_50381501_16_dialog_content = "Selama perjalanan ini, kami telah berganti kapal. Saya sekarang terkurung di kursi roda juga.",
  ui_story_5038_50381501_17_dialog_content = "Tidak akan mudah bagiku untuk menyapa Kaisar saat aku mengunjunginya lagi.",
  ui_story_5038_50381501_18_dialog_content = "Jangan bilang cuma istana yang kamu rindukan tentang Longzhou.",
  ui_story_5038_50381501_19_dialog_content = "Anda akan bernostalgia ketika Anda mencapai usia saya juga.",
  ui_story_5038_50381501_20_dialog_content = "Apakah itu istana kerajaan atau di mana pun, saya merindukan setiap tempat yang pernah saya kunjungi.",
  ui_story_5038_50381501_21_dialog_content = "Ini seperti tugas berbicara dengan Anda ...",
  ui_story_5038_50381501_22_dialog_content = "Katakan saja, apakah Anda menikmati pemandangan dari dek sekarang?",
  ui_story_5038_50381501_23_dialog_content = "Ya, saya sangat menikmatinya.",
  ui_story_5038_50381501_24_dialog_content = "Lihat, ikan ular berenang menjauh!",
  ui_story_5038_50381501_25_dialog_content = "Tentu saja. Mereka tidak bisa pergi ke pantai bersama kita.",
  ui_story_5038_50381501_26_dialog_content = "Mereka akan melakukan hal mereka sendiri setelah membantu kami.",
  ui_story_5038_50381501_27_dialog_content = "Setelah sekian lama digendong oleh mereka, sedikit sedih mengucapkan selamat tinggal.",
  ui_story_5038_50381501_28_dialog_content = "Mereka mungkin memanjakan saya.",
  ui_story_5038_50381501_29_dialog_content = "Tuanku bilang perpisahan selalu pahit manis.",
  ui_story_5038_50381501_30_dialog_content = "Tapi karena mereka tidak dimaksudkan untuk tinggal bersama kita, lebih baik menerima perpisahan yang pantas.",
  ui_story_5038_50381501_31_dialog_content = "Ya, saya kira. Semua perjalanan akan berakhir.",
  ui_story_5038_50381501_32_dialog_content = "Selamat tinggal! Terima kasih semua!",
  ui_story_5038_50381501_33_dialog_content = "*Menangis* Kami akhirnya pulang...",
  ui_story_5038_50381501_34_dialog_content = "Ya, saya pikir kita semua akan mati di laut.",
  ui_story_5038_50381501_35_dialog_content = "Sangat menyenangkan melihat daratan.",
  ui_story_5038_50381501_36_dialog_content = "Ini semua berkat kapten. Tanpa dia, kapal itu akan tenggelam sepuluh kali lipat.",
  ui_story_5038_50381501_37_dialog_content = "Ya, kami memiliki kapten yang luar biasa!",
  ui_story_5038_50381501_38_dialog_content = "Coba pikirkan tentang apa yang dia tuntun untuk kita capai?",
  ui_story_5038_50381501_39_dialog_content = "Kami telah memulihkan rute Lin!",
  ui_story_5038_50381501_40_dialog_content = "Hei, ini kaptennya!",
  ui_story_5038_50381501_41_dialog_content = "Di sini, kapten! Kami hanya menumpuk pujian pada Anda!",
  ui_story_5038_50381501_42_dialog_content = "Kalian...",
  ui_story_5038_50381501_43_dialog_content = "Apa yang kamu lakukan nongkrong di sini? Kembali ke posting Anda!",
  ui_story_5038_50381501_44_dialog_content = "Kapal sedang menuju pelabuhan. Ini belum selesai.",
  ui_story_5038_50381501_45_dialog_content = "Dengar itu, ini belum berakhir sampai selesai, perintah kapten!",
  ui_story_5038_50381501_46_dialog_content = "Aye aye!",
  ui_story_5038_50381501_47_dialog_content = "Aku, uh, sedikit gugup.",
  ui_story_5038_50381501_48_dialog_content = "Apa yang harus saya lakukan setelah turun dari kapal?",
  ui_story_5038_50381501_49_dialog_content = "Apa yang membuatmu gugup? Ikuti saja kami!",
  ui_story_5038_50381501_50_dialog_content = "Anda baru saja melewati badai hebat di laut. Bagaimana bisa berada di darat lebih menakutkan?",
  ui_story_5038_50381501_51_dialog_content = "Tapi lingkungan ini benar-benar baru...",
  ui_story_5038_50381501_52_dialog_content = "Tidak ada yang saya kenal, dan saya sendirian.",
  ui_story_5038_50381501_53_dialog_content = "Apa maksudmu kau sendirian? Apakah kamu tidak memiliki kami?",
  ui_story_5038_50381501_54_dialog_content = "Benar.",
  ui_story_5038_50381501_55_dialog_content = "Tetap bersama saya di Longzhou, dan saya akan memastikan Anda memiliki waktu terbaik dalam hidup Anda.",
  ui_story_5038_50381501_56_dialog_content = "Baiklah, mari kita mulai berkemas.",
  ui_story_5038_50381501_57_dialog_content = "Kapten mendesak semua orang untuk mulai bersiap-siap untuk turun.",
  ui_story_5038_50381501_58_dialog_content = "Manisan hawthorn!",
  ui_story_5038_50381501_59_dialog_content = "Manisan hawthorn untuk dijual!",
  ui_story_5038_50381501_60_dialog_content = "Berapa harganya, Pak?",
  ui_story_5038_50381501_61_dialog_content = "Hei, ada pembuat permen di sana, ayo kita lihat!",
  ui_story_5038_50381501_62_dialog_content = "Apakah itu pangsit manis yang saya cium?",
  ui_story_5038_50381501_63_dialog_content = "Wow, jalanan ramai!",
  ui_story_5038_50381501_64_dialog_content = "Begitu banyak orang!",
  ui_story_5038_50381501_65_dialog_content = "Jadi, bagaimana menurutmu?",
  ui_story_5038_50381501_66_dialog_content = "Saya tidak yakin... Apakah jalanan di Longzhou selalu ramai seperti ini?",
  ui_story_5038_50381501_67_dialog_content = "Tidak selalu. Anda membuatnya tepat pada waktunya untuk akhir Festival Musim Semi.",
  ui_story_5038_50381501_68_dialog_content = "Ini adalah waktu paling populer di Longzhou. Jalanan dipenuhi dengan hal-hal yang menyenangkan dan enak.",
  ui_story_5038_50381501_69_dialog_content = "Lihat, anak itu memegang apa yang disebut Manisan Hawthorn. Mereka sangat asam, manis, dan enak.",
  ui_story_5038_50381501_70_dialog_content = "Dan di atas meja itu ada patung-patung kecil yang dibentuk dari gula. Itu hanya untuk penampilan, tidak bisa dimakan.",
  ui_story_5038_50381501_71_dialog_content = "Kemudian direbus dalam panci besar itu, ada pangsit manis, hanya tersedia selama ini.",
  ui_story_5038_50381501_72_dialog_content = "Wow, semuanya terlihat bagus!",
  ui_story_5038_50381501_73_dialog_content = "Tanyakan saja kepada saya jika Anda ingin tahu tentang apa saja!",
  ui_story_5038_50381501_74_dialog_content = "Biarkan aku menerima ini semua.",
  ui_story_5038_50381501_75_dialog_content = "Kios di tanah dengan penjual mengocok tabung tongkat...",
  ui_story_5038_50381501_76_dialog_content = "Oh, jangan jatuh untuk itu! Ini penipuan total!",
  ui_story_5038_50381501_77_dialog_content = "Penipuan?",
  ui_story_5038_50381501_78_dialog_content = "Ya, itu disebut meramal. Tidak ada gunanya menulis tentang rumah.",
  ui_story_5038_50381501_79_dialog_content = "Para penipu itu akan mengatakan apa saja untuk menangkapmu hook, line, dan pendosa.",
  ui_story_5038_50381501_80_dialog_content = "Ini sedikit lebih dari membuat barang untuk menipu Anda dari uang Anda.",
  ui_story_5038_50381501_81_dialog_content = "Mengapa mereka tidak ditangkap dan dimasukkan ke dalam penjara?",
  ui_story_5038_50381501_82_dialog_content = "Nah, agak rumit...",
  ui_story_5038_50381501_83_dialog_content = "Bagaimanapun, jangan dengarkan mereka, jangan percayai mereka. Jika Anda ingin tahu apa yang akan terjadi di masa depan, saya orangnya!",
  ui_story_5038_50381501_84_dialog_content = "K-Kamu?",
  ui_story_5038_50381501_85_dialog_content = "Saya pikir meramal adalah penipuan?",
  ui_story_5038_50381501_86_dialog_content = "Ini tentang siapa yang melakukan ramalan. Sudah kubilang, ini rumit.",
  ui_story_5038_50381501_87_dialog_content = "Heh, ada pepatah di Longzhou yang berbunyi, \"Dua perdagangan jarang setuju.\"",
  ui_story_5038_50381501_88_dialog_content = "Saya akan membiarkan Anda merenungkan itu, PlayerName.",
  ui_story_5038_50381501_89_dialog_content = "Bersihkan jalan, bersihkan jalan!",
  ui_story_5038_50381501_90_dialog_content = "Apa kau tidak melihat kursi roda lewat?",
  ui_story_5038_50381501_91_dialog_content = "Pelan-pelan, Liqing, agar kami tidak mengganggu orang lain.",
  ui_story_5038_50381501_92_dialog_content = "Mustahil! Setelah semua kesulitan untuk pulang, aku akan berjalan sesukaku!",
  ui_story_5038_50381501_93_dialog_content = "Tapi kemana kita semua pergi, Kapten?",
  ui_story_5038_50381501_94_dialog_content = "Shadowind adalah kapal Lins, jadi tentu saja, aku harus kembali ke Lin Guild.",
  ui_story_5038_50381501_95_dialog_content = "Jika Anda tidak keberatan, Anda diundang untuk tinggal sebagai tamu saya.",
  ui_story_5038_50381501_96_dialog_content = "Lebih meriah untuk musim festival.",
  ui_story_5038_50381501_97_dialog_content = "Apakah kita akan pergi, orang tua?",
  ui_story_5038_50381501_98_dialog_content = "Aku sangat lapar.",
  ui_story_5038_50381501_99_dialog_content = "Tentu kami. Saya akan pergi bahkan tanpa undangan.",
  ui_story_5038_50381501_100_dialog_content = "Lin Guildmaster berutang banyak padaku.",
  ui_story_5038_50381501_101_dialog_content = "Tidak ada yang menagih hutang selama Festival Musim Semi, Tuan Zhong.",
  ui_story_5038_50381501_102_dialog_content = "Dan mengingat keadaan menyedihkan guild saat ini, kami tidak akan mampu membayar harga yang diminta dari seorang jenderal yang layak seperti Anda, Tuanku.",
  ui_story_5038_50381501_103_dialog_content = "Nah, itulah idenya.",
  ui_story_5038_50381501_104_dialog_content = "Saya ingin dia malu dengan fakta itu selama sisa hidupnya.",
  ui_story_5038_50381501_105_dialog_content = "Mereka kembali! Pelayaran Shadowind kembali!",
  ui_story_5038_50381501_106_dialog_content = "Silakan masuk! Itu pasti perjalanan yang sulit!",
  ui_story_5038_50381501_107_dialog_content = "Anda pasti kelelahan!",
  ui_story_5038_50381501_108_dialog_content = "Jadi ini rumah Lin?",
  ui_story_5038_50381501_109_dialog_content = "Saya tidak menyangka bangunan itu agak biasa untuk klan yang membangun kapal sebesar Shadowind.",
  ui_story_5038_50381501_110_dialog_content = "Lagipula, mereka tidak melakukannya dengan baik.",
  ui_story_5038_50381501_111_dialog_content = "Kudengar gerbang depan mereka dulu jauh lebih megah.",
  ui_story_5038_50381501_112_dialog_content = "Saya tidak suka gerbang besar, itu sangat impersonal.",
  ui_story_5038_50381501_113_dialog_content = "Itu membuat Festival Musim Semi terasa seperti sekarang!",
  ui_story_5038_50381501_114_dialog_content = "Mengapa Anda tidak masuk karena Anda di rumah?",
  ui_story_5038_50381501_115_dialog_content = "Jangan hanya berdiri di sana.",
  ui_story_5038_50381501_116_dialog_content = "Siapa pria tua ini?",
  ui_story_5038_50381501_117_dialog_content = "Guildmaster, Anda tidak perlu keluar untuk menyambut kami.",
  ui_story_5038_50381501_118_dialog_content = "Bagaimana tidak, mendengar berita tentang kembalinya Shadowind?",
  ui_story_5038_50381501_119_dialog_content = "Anda semua adalah tamu terhormat atas apa yang Anda lakukan. Seharusnya aku menunggumu di dermaga secara langsung.",
  ui_story_5038_50381501_120_dialog_content = "Itu benar, dia seharusnya mengadakan pesta di dermaga untuk menyambut kita.",
  ui_story_5038_50381501_121_dialog_content = "Daripada hanya duduk di rumah, menikmati hasil kerja kita.",
  ui_story_5038_50381501_122_dialog_content = "Zhong Xu, kamu kembali!",
  ui_story_5038_50381501_123_dialog_content = "Kakimu...",
  ui_story_5038_50381501_124_dialog_content = "Mereka baik-baik saja.",
  ui_story_5038_50381501_125_dialog_content = "Yang saya derita dalam pertempuran untuk Tentara Kekaisaran selama bertahun-tahun hanyalah beberapa luka.",
  ui_story_5038_50381501_126_dialog_content = "Tapi menjalankan tugas untuk guildmu, aku berhasil mematahkan kedua kakiku.",
  ui_story_5038_50381501_127_dialog_content = "Old Lin, kamu telah mengalahkan Kaisar sendiri.",
  ui_story_5038_50381501_128_dialog_content = "Tolong jangan katakan itu, aku tidak akan berani...",
  ui_story_5038_50381501_129_dialog_content = "Aku akan mencarikanmu dokter terbaik. Tetaplah dan luangkan waktu Anda untuk pulih.",
  ui_story_5038_50381501_130_dialog_content = "Itu tidak perlu. Saya cukup menikmati bersantai di kursi roda.",
  ui_story_5038_50381501_131_dialog_content = "Selain itu, bagaimana kelihatannya Liqing jika seseorang berhasil menyembuhkan kakiku?",
  ui_story_5038_50381501_132_dialog_content = "Itu mustahil!",
  ui_story_5038_50381501_133_dialog_content = "Kakimu tidak bisa disembuhkan, tidak peduli siapa yang mencobanya!",
  ui_story_5038_50381501_134_dialog_content = "D-Dia sangat blak-blakan, bukan?",
  ui_story_5038_50381501_135_dialog_content = "Jangan pedulikan dia. Liqing selalu menjadi penembak jitu.",
  ui_story_5038_50381501_136_dialog_content = "Perjalanan yang kami lalui cukup seru...",
  ui_story_5038_50381501_137_dialog_content = "Namun, saya gagal mengambil The Compass, Lin.",
  ui_story_5038_50381501_138_dialog_content = "Zhongxu...",
  ui_story_5038_50381501_139_dialog_content = "Kamu mempermalukan saya.",
  ui_story_5038_50381501_140_dialog_content = "Tidak mudah bagimu untuk membuatnya kembali seperti semula.",
  ui_story_5038_50381501_141_dialog_content = "Ini salahku karena tidak mampu melindungi bisnis keluarga dan membebani teman.",
  ui_story_5038_50381501_142_dialog_content = "Saya dengan ini meminta maaf kepada Anda, Zhong Xu, serta semua orang yang hadir.",
  ui_story_5038_50381501_143_dialog_content = "Oh, lupakan itu.",
  ui_story_5038_50381501_144_dialog_content = "Aku kehilangan The Compass, jadi kita seimbang.",
  ui_story_5038_50381501_145_dialog_content = "Tapi Anda memiliki ahli waris yang brilian yang sekarang bisa mengarungi rute tanpa Kompas.",
  ui_story_5038_50381501_146_dialog_content = "Anda harus menyimpan sentimen Anda untuknya.",
  ui_story_5038_50381501_147_dialog_content = "Omong-omong, itu benar. Ini dia, kembali ke Longzhou dengan aman tanpa The Compass.",
  ui_story_5038_50381501_148_dialog_content = "Anda telah melakukannya dengan sangat baik, Yuebai.",
  ui_story_5038_50381501_149_dialog_content = "Harus kuakui, Guildmaster.",
  ui_story_5038_50381501_150_dialog_content = "Kami sebenarnya memiliki The Compass, tetapi saya memutuskan untuk melepaskannya.",
  ui_story_5038_50381501_151_dialog_content = "Anda membiarkan...",
  ui_story_5038_50381501_152_dialog_content = "Saya merasa tidak benar bagaimana kami mengeksploitasi The Compass.",
  ui_story_5038_50381501_153_dialog_content = "Hati nurani saya bersih, tetapi faktanya tetap bahwa saya kehilangan aset yang berharga.",
  ui_story_5038_50381501_154_dialog_content = "Oleh karena itu, saya akan menerima hukuman apa pun yang Anda pilih.",
  ui_story_5038_50381501_155_dialog_content = "Ha ha ha ha. Apakah Anda mengaku dosa, atau melontarkan tuduhan?",
  ui_story_5038_50381501_156_dialog_content = "Apakah Anda belajar menyembunyikan pedang dalam kata-kata Anda dari Tuan Zhong di sana?",
  ui_story_5038_50381501_157_dialog_content = "Itu bukan maksud saya, Pak.",
  ui_story_5038_50381501_158_dialog_content = "Itu bukanlah harta yang berharga, tetapi upaya terakhir untuk mengarungi lautan.",
  ui_story_5038_50381501_159_dialog_content = "Aku seharusnya senang kau tidak harus bergantung padanya lagi.",
  ui_story_5038_50381501_160_dialog_content = "Terima kasih atas kebaikan Anda, Guildmaster.",
  ui_story_5038_50381501_161_dialog_content = "Mengapa kamu begitu formal, anakku?",
  ui_story_5038_50381501_162_dialog_content = "Anda mempelopori rute maritim untuk Lin Guild sendiri. Anda mungkin akan segera menjadi Guildmaster berikutnya.",
  ui_story_5038_50381501_163_dialog_content = "Apa?!",
  ui_story_5038_50381501_164_dialog_content = "Pak, anda melebih-lebihkan...",
  ui_story_5038_50381501_165_dialog_content = "Tidak, bukan aku. Anda pantas mendapatkannya.",
  ui_story_5038_50381501_166_dialog_content = "Saya harap Anda akan melupakan asal-usul Anda. Itu semua di masa lalu.",
  ui_story_5038_50381501_167_dialog_content = "Apa yang bisa dilakukan Lin, Mu Yuebai juga bisa melakukannya.",
  ui_story_5038_50381501_168_dialog_content = "Siap, Pak.",
  ui_story_5038_50381501_169_dialog_content = "Nah, itu sudah cukup mengoceh dari saya.",
  ui_story_5038_50381501_170_dialog_content = "Diluar dingin. Mengapa Anda semua tidak masuk dan menikmati makanan enak?",
  ui_story_5038_50381501_171_dialog_content = "Ya, apa yang masih kita tunggu? Guildmaster telah berbicara!",
  ui_story_5038_50381501_172_dialog_content = "Ayo, kita bisa bicara di dalam!",
  ui_story_5038_50381501_173_dialog_content = "<color=#e8d9bb>Acak, acak ...</color>",
  ui_story_5038_50381501_174_dialog_content = "Apa aku harus masuk juga?",
  ui_story_5038_50381501_175_dialog_content = "Tentu saja. Mengapa, apakah Anda harus pergi ke suatu tempat?",
  ui_story_5038_50381501_176_dialog_content = "Tidak tapi...",
  ui_story_5038_50381501_177_dialog_content = "Aku merasa aneh menumpang makanan dari guild sebagai orang luar...",
  ui_story_5038_50381501_178_dialog_content = "Orang luar? Tidak setelah kau membantu Shadowind melewati semua masalah itu!",
  ui_story_5038_50381501_179_dialog_content = "Lihat, semua orang sudah kenyang.",
  ui_story_5038_50381501_180_dialog_content = "Anggur dan masakan lezat... Anda tidak perlu bertanya dua kali kepada saya!",
  ui_story_5038_50381501_181_dialog_content = "Meja rumah tangga yang kaya harus diisi dengan segala macam hal yang lezat! Ayo pergi, Ji!",
  ui_story_5038_50381501_182_dialog_content = "Hati-hati melewati ambang pintu, Yang Mulia!",
  ui_story_5038_50381501_183_dialog_content = "Wow, mereka semua menghilang dalam sekejap mata...",
  ui_story_5038_50381501_184_dialog_content = "Itu sebabnya saya mengatakan kepada Anda untuk tidak khawatir.",
  ui_story_5038_50381501_185_dialog_content = "Jangan ragu untuk tinggal di sini selama Anda berada di Longzhou.",
  ui_story_5038_50381501_186_dialog_content = "Saat Shadowind berlayar lagi, aku akan mengantarmu kembali ke Astra.",
  ui_story_5038_50381501_187_dialog_content = "Tetap dengan Lins? seharusnya aku tidak mengganggumu...",
  ui_story_5038_50381501_188_dialog_content = "Bisa aja. Jangan mengambil stereotip kesopanan Longzhou sekarang.",
  ui_story_5038_50381501_189_dialog_content = "Masuklah sebelum makanannya habis.",
  ui_story_5038_50381501_190_dialog_content = "(Longzhou adalah tempat yang sangat ramai dan ramai.)",
  ui_story_5038_50381501_191_dialog_content = "(Tidak ada yang bisa merasa kesepian di tengah keramaian.)",
  ui_story_5038_50381501_192_dialog_content = "<color=#e8d9bb>Beberapa hari kemudian</color>",
  ui_story_5038_50381501_193_dialog_content = "Pergi ke Shadowind? Sekarang?",
  ui_story_5038_50381501_194_dialog_content = "Ya, Yuebai mengumpulkan semua orang. Anda adalah orang terakhir.",
  ui_story_5038_50381501_195_dialog_content = "Tapi saya tidak ingin melakukan perjalanan lain, jadi mengapa saya harus pergi?",
  ui_story_5038_50381501_196_dialog_content = "Jangan khawatir, ini bukan perjalanan lain. Kami tidak menculikmu ke Astra.",
  ui_story_5038_50381501_197_dialog_content = "Dia juga tidak memberi tahu saya secara spesifik, jadi saya kira kita akan mengetahuinya!",
  ui_story_5038_50381501_198_dialog_content = "Baiklah, aku akan pergi, karena kita tidak terlalu jauh dari dermaga.",
  ui_story_5038_50381501_199_dialog_content = "Bagus sekali!",
  ui_story_5038_50381501_200_dialog_content = "Bagaimana Longzhou memperlakukanmu, PlayerName? Bersenang senang?",
  ui_story_5038_50381501_201_dialog_content = "Ini masih agak baru bagi saya, dan saya gugup berbicara dengan penduduk setempat.",
  ui_story_5038_50381501_202_dialog_content = "Juga, saya tidak tahu ke mana harus pergi.",
  ui_story_5038_50381501_203_dialog_content = "Astaga, sepertinya keluarga Lin bukanlah tuan rumah yang baik.",
  ui_story_5038_50381501_204_dialog_content = "Temui aku nanti, dan aku akan mengajakmu berkeliling.",
  ui_story_5038_50381501_205_dialog_content = "Tentu, kedengarannya bagus!",
  ui_story_5038_50381501_206_dialog_content = "Ngomong-ngomong, ada satu hal ...",
  ui_story_5038_50381501_207_dialog_content = "Ada apa?",
  ui_story_5038_50381501_208_dialog_content = "Saya membawa surat ke Longzhou.",
  ui_story_5038_50381501_209_dialog_content = "Saya menghabiskan dua hari terakhir mencoba menemukan alamat penerima, tetapi tidak bisa.",
  ui_story_5038_50381501_210_dialog_content = "Lalu kemarin, saya tidak sengaja menumpahkan air ke amplop.",
  ui_story_5038_50381501_211_dialog_content = "Segel lilin larut, dan setumpuk <color=#FFB400>kertas merah</color> terbang keluar.",
  ui_story_5038_50381501_212_dialog_content = "Kertas merah?!",
  ui_story_5038_50381501_213_dialog_content = "Ya. Mereka tampak seperti guntingan kupu-kupu. Mereka berkumpul bersama dan terbang menjauh.",
  ui_story_5038_50381501_214_dialog_content = "Tidak ada yang lain di dalam amplop itu. Saya tidak yakin apakah ini dianggap sebagai terkirim.",
  ui_story_5038_50381501_215_dialog_content = "Hmm…",
  ui_story_5038_50381501_216_dialog_content = "Ada pemikiran tentang itu, Tianxian?",
  ui_story_5038_50381501_217_dialog_content = "Membuat penasaran...",
  ui_story_5038_50381501_218_dialog_content = "Jangan khawatir tentang itu. Pengirim mendapatkan keinginan mereka.",
  ui_story_5038_50381501_X218_dialog_content = "Kupu-kupu menyukai bunga. Mereka akan menemukan tujuan mereka.",
  ui_story_5038_50381501_219_dialog_content = "Bagianmu sudah selesai.",
  ui_story_5038_50381501_220_dialog_content = "Sudah? Itu saja?",
  ui_story_5038_50381501_221_dialog_content = "Tentu saja.",
  ui_story_5038_50381501_X221_dialog_content = "Saya tidak pernah berharap itu benar-benar tiba di sini, dari seberang lautan.",
  ui_story_5038_50381501_X222_dialog_content = "<size=35>Berkat dan kemalangan ada bersama-sama. Benar saja, kelangsungan hidup kami yang diberkati tidak muncul begitu saja.</size>",
  ui_story_5038_50381501_X223_dialog_content = "<size=35>Sekarang...</size>",
  ui_story_5038_50381501_X224_dialog_content = "Apa? Maksud kamu apa?",
  ui_story_5038_50381501_X225_dialog_content = "Tidak apa-apa, tidak apa-apa. Saya berbicara sendiri.",
  ui_story_5038_50381501_222_dialog_content = "Hei, ada dermaga.",
  ui_story_5038_50381501_223_dialog_content = "Ayo cepat.",
  ui_story_5038_50381501_224_dialog_content = "Apakah paku dipalu?",
  ui_story_5038_50381501_225_dialog_content = "Ya! Ada yang butuh kuku sisa?",
  ui_story_5038_50381501_226_dialog_content = "Lihat, ini dia dua orang terakhir!",
  ui_story_5038_50381501_227_dialog_content = "Kami telah menunggumu.",
  ui_story_5038_50381501_228_dialog_content = "Semua orang ada di sini sekarang, Kapten!",
  ui_story_5038_50381501_229_dialog_content = "Semua hadir?",
  ui_story_5038_50381501_230_dialog_content = "Oke, mari kita mulai bisnis.",
  ui_story_5038_50381501_231_dialog_content = "Apa yang kita lakukan di sini, Kapten?",
  ui_story_5038_50381501_232_dialog_content = "Kami telah melalui banyak hal bersama.",
  ui_story_5038_50381501_233_dialog_content = "Oleh karena itu, kita akan menyaksikan momen ini bersama-sama.",
  ui_story_5038_50381501_234_dialog_content = "Saat ini?",
  ui_story_5038_50381501_235_dialog_content = "Kapten!",
  ui_story_5038_50381501_236_dialog_content = "Perbaikan selesai. Semua pemeriksaan selesai.",
  ui_story_5038_50381501_237_dialog_content = "Shadowind sama bagusnya dengan yang baru!",
  ui_story_5038_50381501_238_dialog_content = "<size=45>Hore!</size>",
  ui_story_5038_50381501_239_dialog_content = "Wow! Kapal sudah diperbaiki!",
  ui_story_5038_50381501_240_dialog_content = "Ya. Akhirnya.",
  ui_story_5038_50381501_241_dialog_content = "Sekarang dia benar-benar telah menyelesaikan perjalanannya.",
  ui_story_5038_50381501_242_dialog_content = "Pelayarannya telah menjadi siklus kerusakan dan perbaikan yang tak berkesudahan. Hari ini, akhirnya berakhir.",
  ui_story_5038_50381501_243_dialog_content = "Perjalanan ini telah mencapai akhir yang memuaskan.",
  ui_story_5038_50381501_244_dialog_content = "Ini bagus! Saya hampir lupa bagaimana rupa Shadowind pada awalnya!",
  ui_story_5038_50381501_245_dialog_content = "Semuanya baru dan dipoles, bahkan tidak ada goresan... agak sulit untuk membiasakan diri.",
  ui_story_5038_50381501_246_dialog_content = "Jangan ragu untuk menjelajah nanti.",
  ui_story_5038_50381501_247_dialog_content = "Tetapi untuk saat ini, saya membutuhkan Anda semua untuk melakukan satu hal lagi.",
  ui_story_5038_50381501_248_dialog_content = "Ada apa?",
  ui_story_5038_50381501_249_dialog_content = "Merupakan kebiasaan bagi pengrajin untuk mengukir nama mereka pada karya yang paling mereka banggakan.",
  ui_story_5038_50381501_250_dialog_content = "Sebanyak perbaikan yang kami lakukan selama pelayaran, semua orang di sini berperan dalam mengembalikan kapal ke kejayaannya.",
  ui_story_5038_50381501_251_dialog_content = "Saya ingin melihat nama Anda menghiasi Shadowind baru ini.",
  ui_story_5038_50381501_252_dialog_content = "Mari kita ukir nama kita di \"telinga kelinci\" tradisional yang ikonik.",
  ui_story_5038_50381501_253_dialog_content = "Oh, kedengarannya menyenangkan!",
  ui_story_5038_50381501_254_dialog_content = "Ide yang hebat! Aku menyukainya!",
  ui_story_5038_50381501_255_dialog_content = "Saya harap tidak ada yang keberatan dengan skrip saya yang mengerikan ...",
  ui_story_5038_50381501_256_dialog_content = "Saya melihat semua orang setuju.",
  ui_story_5038_50381501_257_dialog_content = "Kalau begitu, mari kita mulai dengan teman kita dari luar negeri.",
  ui_story_5038_50381501_258_dialog_content = "Apakah Anda berbicara tentang saya ?!",
  ui_story_5038_50381501_259_dialog_content = "Ya. Biasanya para tamu pergi duluan di Longzhou.",
  ui_story_5038_50381501_260_dialog_content = "Ini pahatnya. Ukir nama Anda di mana pun Anda suka.",
  ui_story_5038_50381501_261_dialog_content = "Ini agak canggung.",
  ui_story_5038_50381501_262_dialog_content = "Dan saya rasa tidak ada yang bisa membaca nama saya...",
  ui_story_5038_50381501_263_dialog_content = "Itu bahkan lebih baik. Kami tidak akan tahu jika Anda mengacau!",
  ui_story_5038_50381501_264_dialog_content = "Merupakan hak istimewa untuk pergi dulu. Anda bisa memilih tempat terbaik dan paling menonjol.",
  ui_story_5038_50381501_265_dialog_content = "Ya, apa yang membuat canggung?",
  ui_story_5038_50381501_266_dialog_content = "Oke, baiklah...",
  ui_story_5038_50381501_267_dialog_content = "Saya akan mulai kalau begitu.",
  ui_story_5038_50381501_268_dialog_content = "Ya lakukanlah.",
  ui_story_5038_50381501_269_dialog_content = "(Tangan, pegang pahat dengan kuat, dan jangan goyang.)",
  ui_story_5038_50381501_270_dialog_content = "(Ayo pergi dengan tempat ini di tepi sini.)",
  ui_story_5038_50381501_271option_content = "PlayerName",
  ui_story_5038_50381501_272_dialog_content = "Ini dia! Itu terlihat bagus!",
  ui_story_5038_50381501_273_dialog_content = "Buat lebih besar agar kita bisa melihatnya!",
  ui_story_5038_50381501_274_dialog_content = "(Tidak ada yang bisa meninggalkan bekas di lautan.)",
  ui_story_5038_50381501_275_dialog_content = "(Segala sesuatu di permukaannya bersifat sementara, baik itu air yang tenang atau gelombang yang bergolak.)",
  ui_story_5038_50381501_276_dialog_content = "(Namun akan selalu ada orang yang mencoba.)",
  ui_story_5038_50381501_277_dialog_content = "(Cobalah, seperti saya, untuk menorehkan nama mereka di tempat yang akan tetap ada selamanya.)",
  ui_story_5038_50381501_278_dialog_content = "(Ini akan menemani Shadowind saat melakukan perjalanan antar benua.)",
  ui_story_5038_50381501_279_dialog_content = "(Itu tidak memiliki kekuatan untuk mengubah laut.)",
  ui_story_5038_50381501_280_dialog_content = "(Tapi mungkin bagi sebagian orang, nama saya akan identik dengan perairannya.)",
  ui_story_5038_50381501_281_dialog_content = "PlayerName",
  ui_story_5038_50381501_282_dialog_content = "Bersambung..."
